"""The four guards and `when` (§ 5.4). There are four kinds and no others.

A guard is evaluated against the store as the command would leave it: the
command's changes are applied inside the open transaction first, so a guard
sees the fields and relations the same command sets. A refusal rolls all of it
back.
"""

from __future__ import annotations

from .store import id_order
from .values import effective, is_set, same


def item_view(store, norm: dict, item_id: str) -> dict:
    """The item's type, state and effective field values."""
    row = store.item_row(item_id)
    tdecl = norm["types"][row["type"]]
    stored = store.values(item_id)
    fields = {f: stored.get(f) for f in tdecl["fields"]}
    return {"id": item_id, "type": row["type"], "state": row["state"],
            "fields": fields, "decl": tdecl}


def _effective(view: dict, field: str):
    return effective(view["decl"]["fields"][field]["kind"],
                     view["fields"].get(field))


def applies(guard: dict, view: dict) -> bool:
    when = guard.get("when")
    if not when:
        return True
    (field, values), = when.items()
    value = _effective(view, field)
    return any(same(value, v) for v in values)


def _required(guard, view):
    missing, below = [], {}
    for field in guard["fields"]:
        kind = view["decl"]["fields"][field]["kind"]
        if not is_set(kind, view["fields"].get(field)):
            missing.append(field)
    for field, minimum in guard["at_least"].items():
        values = view["decl"]["fields"][field]["values"]
        value = _effective(view, field)
        rank = next((n for n, v in enumerate(values) if same(v, value)), None)
        floor = next(n for n, v in enumerate(values) if same(v, minimum))
        if value is None or rank is None or rank < floor:
            below[field] = {"value": value, "at_least": minimum}
    if missing or below:
        return {"missing": missing, "below": below}
    return None


def _actor(guard, actor):
    needs = {}
    ok = True
    if "actor_kind" in guard:
        needs["actor_kind"] = guard["actor_kind"]
        ok = ok and actor.get("kind") == guard["actor_kind"]
    if "name" in guard:
        needs["name"] = guard["name"]
        ok = ok and actor.get("name") == guard["name"]
    return None if ok else {"actor": actor, "needs": needs}


def _relations_closed(guard, view, store, norm):
    kind, direction = guard["relation"], guard["direction"]
    if direction == "incoming":
        others = [src for _k, src, _d in store.edges(kind=kind,
                                                     dst=view["id"])]
    else:
        others = [dst for _k, _s, dst in store.edges(kind=kind,
                                                     src=view["id"])]
    open_ends = []
    for other in others:
        row = store.item_row(other)
        terminal = norm["types"][row["type"]]["terminal"]
        if row["state"] not in terminal:
            open_ends.append(other)
    if open_ends:
        return {"not_terminal": sorted(set(open_ends), key=id_order)}
    return None


def _limit(guard, view, store, norm, target_state):
    """Guards run after the command's changes are applied, so this item
    already sits in `target_state` and `items_in` returns it: it counts
    itself once, in the loop."""
    per = guard["per"]
    mine = {f: _effective(view, f) for f in per}
    count = 0
    for other in store.items_in(view["type"], target_state):
        if other == view["id"]:
            count += 1
            continue
        other_view = item_view(store, norm, other)
        if all(same(_effective(other_view, f), mine[f]) for f in per):
            count += 1
    if count > guard["max"]:
        return {"count": count, "max": guard["max"], "values": mine}
    return None


def evaluate(guards: list, *, store, norm: dict, item_id: str,
             target_state: str, actor: dict):
    """Every guard that applies, evaluated. Returns `(refusals, warnings)`,
    each a list of `{index, kind, when, detail}`."""
    view = item_view(store, norm, item_id)
    refusals, warnings = [], []
    for index, guard in enumerate(guards):
        if not applies(guard, view):
            continue
        kind = guard["kind"]
        if kind == "required":
            detail = _required(guard, view)
        elif kind == "actor":
            detail = _actor(guard, actor)
        elif kind == "relations_closed":
            detail = _relations_closed(guard, view, store, norm)
        elif kind == "limit":
            detail = _limit(guard, view, store, norm, target_state)
        else:  # pragma: no cover — the template validator admits four kinds
            raise ValueError(kind)
        if detail is None:
            continue
        failure = {"index": index, "kind": kind, "when": guard.get("when"),
                   "detail": detail}
        if kind == "limit" and guard["mode"] == "warn":
            warnings.append(failure)
        else:
            refusals.append(failure)
    return refusals, warnings

"""Where the project is and where its store lives (§ 5.7, NN-K5).

The anchor order is the one every Perry tool resolves in: `--root`, then
`PERRY_PROJECT`, then the walk up from the working directory. The git common
dir is read from `.git` and `commondir`, never asked of `git`: the kernel runs
no command (NN-K2). Everything here takes the environment and the working
directory as arguments, so a caller can resolve for a directory it is not in.
"""

from __future__ import annotations

from pathlib import Path

from .errors import KernelError
from .values import SURROGATE

ANCHOR_DIR = ".perry"
OUTSIDE_GIT_STORE = "perry.db"   # under <anchor>/.perry/
STORE_DIR = "perry"                # under <git common dir>/
SLUG_SAFE = frozenset(b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz"
                      b"0123456789._-")


def working_directory(cwd) -> Path:
    if cwd is None:
        raise KernelError("io_error", "the working directory no longer exists")
    cwd = Path(cwd)
    if SURROGATE.search(str(cwd)):
        raise KernelError("io_error", "the working directory's path is not "
                                      "valid UTF-8")
    return cwd


def resolve_path(text: str, cwd, source: str = "a path") -> Path:
    """An absolute, resolved path, or a typed refusal. `~user` that names no
    one, a symlink loop and an unreadable component are `io_error`, never an
    exception (NN-K6)."""
    if text == "":
        # `Path("")` is the working directory: an empty value must never
        # quietly become one (the flags are refused at parse, § 5.1).
        raise KernelError("usage", f"{source} was given an empty value")
    try:
        path = Path(text).expanduser()
        if not path.is_absolute():
            path = working_directory(cwd) / path
        path = path.resolve()
    except (OSError, RuntimeError) as exc:
        raise KernelError("io_error", f"{source}: cannot resolve the path: "
                                      f"{getattr(exc, 'strerror', None) or exc}",
                          {"source": source})
    if SURROGATE.search(str(path)):
        raise KernelError("io_error", f"{source}: the path is not valid UTF-8",
                          {"source": source})
    return path


def _abs(text: str, cwd, source: str = "a path") -> Path:
    return resolve_path(text, cwd, source)


def env_value(environ, name: str, *, empty: str = "unset"):
    """An environment variable's value, or None when it is unset.

    What an EMPTY value means is decided per variable, and never by
    truthiness at the call site (the user's decision, 2026-09-25):
    - `PERRY_PROJECT` (empty="unset"): unset, as `bin/lib §
      resolve_project_root` treats it, so the two resolvers agree;
    - `PERRY_STORE` (empty="refuse"): `usage`, as `--store ""` is — an empty
      value must never fall through to the derived, shared store.
    `PERRY_KERNEL_TESTING` is read by `testing()`, not here."""
    value = environ.get(name)
    if value is None:
        return None
    if value == "":
        if empty == "refuse":
            raise KernelError("usage", f"{name} is set but empty; if it came "
                                       f"from a shell variable, the variable "
                                       f"is unset", {"variable": name})
        return None
    if SURROGATE.search(value):
        raise KernelError("usage", f"{name} is not valid UTF-8",
                          {"variable": name})
    return value


def testing(environ) -> bool:
    """Is `PERRY_KERNEL_TESTING` set? Present counts, empty included: it is
    a safety switch, and one that is set but empty fails safe, refusing the
    derived store rather than reaching it."""
    return "PERRY_KERNEL_TESTING" in environ


def _holds_anchor(directory: Path) -> bool:
    try:
        return (directory / ANCHOR_DIR).is_dir()
    except OSError:
        return False


def resolve_anchor(root_flag: str | None, environ, cwd) -> Path:
    """The project anchor: `--root`, else `PERRY_PROJECT`, else the first
    directory at or above `cwd` that holds `.perry/`."""
    # The flag wins (NN-K5), so the environment is not read when it is
    # given: a PERRY_PROJECT that could not be used must not refuse a
    # command that named its project.
    project = (env_value(environ, "PERRY_PROJECT") if root_flag is None
               else None)
    if root_flag is not None:
        chosen, source = _abs(root_flag, cwd, "--root"), "--root"
    elif project is not None:
        chosen, source = _abs(project, cwd, "PERRY_PROJECT"), "PERRY_PROJECT"
    else:
        start = resolve_path(".", cwd, "the working directory")
        for directory in (start, *start.parents):
            if _holds_anchor(directory):
                return directory
        raise KernelError("anchor_not_found",
                          f"no directory at or above {start} holds "
                          f"{ANCHOR_DIR}/", {"searched_from": str(start)})
    if not _holds_anchor(chosen):
        raise KernelError("anchor_not_found",
                          f"{chosen} (from {source}) holds no {ANCHOR_DIR}/",
                          {"path": str(chosen), "source": source})
    return chosen


def _read_text(path: Path) -> str:
    try:
        return path.read_text(encoding="utf-8")
    except OSError as exc:
        raise KernelError("io_error", f"cannot read {path}: {exc.strerror}",
                          {"path": str(path)})
    except UnicodeDecodeError:
        raise KernelError("io_error", f"{path} is not valid UTF-8",
                          {"path": str(path)})


def _kind(path: Path):
    """`dir`, `file` or None; an unreadable component is `io_error`."""
    try:
        if path.is_dir():
            return "dir"
        if path.is_file():
            return "file"
    except OSError as exc:
        raise KernelError("io_error", f"cannot inspect {path}: "
                                      f"{exc.strerror}", {"path": str(path)})
    return None


def git_layout(anchor: Path):
    """`(top, git_dir, common_dir)` for the worktree holding `anchor`, or None
    outside git. `GIT_DIR` and `GIT_COMMON_DIR` are ignored on purpose."""
    for directory in (anchor, *anchor.parents):
        dotgit = directory / ".git"
        kind = _kind(dotgit)
        if kind == "dir":
            git_dir = _abs(str(dotgit), directory)
        elif kind == "file":
            pointer = None
            for line in _read_text(dotgit).splitlines():
                if line.startswith("gitdir:"):
                    pointer = line[len("gitdir:"):].strip()
                    break
            if not pointer:
                raise KernelError("io_error", f"{dotgit} has no gitdir: line",
                                  {"path": str(dotgit)})
            git_dir = _abs(pointer, directory)
        else:
            continue
        commondir = git_dir / "commondir"
        if _kind(commondir) == "file":
            common = _abs(_read_text(commondir).strip(), git_dir)
        else:
            common = git_dir
        return directory, git_dir, common
    return None


def slug(anchor: Path, top: Path) -> str:
    """`root` for a worktree's top level, else `root/<path>` with every byte
    outside [A-Za-z0-9._-] written as %XX. Injective."""
    rel = anchor.relative_to(top).as_posix()
    text = "root" if rel == "." else f"root/{rel}"
    return "".join(chr(b) if b in SLUG_SAFE else f"%{b:02X}"
                   for b in text.encode("utf-8"))


def derived_store(anchor: Path) -> Path:
    layout = git_layout(anchor)
    if layout is None:
        return anchor / ANCHOR_DIR / OUTSIDE_GIT_STORE
    top, _git_dir, common = layout
    return common / STORE_DIR / f"{slug(anchor, top)}.db"


def resolve_store(store_flag: str | None, environ, cwd, anchor_fn):
    """`(path, derived)`. `--store`, else `PERRY_STORE`, else derived from the
    anchor, which `anchor_fn()` resolves only when it is needed."""
    if store_flag is not None:
        return _abs(store_flag, cwd, "--store"), False
    named = env_value(environ, "PERRY_STORE", empty="refuse")
    if named is not None:
        return _abs(named, cwd, "PERRY_STORE"), False
    path = derived_store(anchor_fn())
    if testing(environ):
        raise KernelError("store_live_under_test",
                          "PERRY_KERNEL_TESTING is set and no store was named; "
                          "pass --store or PERRY_STORE",
                          {"derived": str(path)})
    return path, True

"""The store: sqlite3 in WAL mode, one transaction per command (§ 5.7).

Every write, live or replayed, goes through `apply_event`. `import` replays an
export through the same function a live command writes through, so a replay
cannot disagree with the writes it replays.
"""

from __future__ import annotations

import json
import random
import sqlite3
import time
import urllib.parse
from pathlib import Path

from .errors import KernelError
from .values import canonical, same

APPLICATION_ID = 0x5045524B  # "PERK"
FORMAT = 1
BUSY_TIMEOUT_S = 5.0

#: One statement per entry: `executescript` would COMMIT the open transaction.
SCHEMA = (
    "CREATE TABLE meta (key TEXT PRIMARY KEY, value TEXT NOT NULL)",
    "CREATE TABLE template (version INTEGER PRIMARY KEY, body TEXT NOT NULL, "
    "applied_seq INTEGER NOT NULL, applied_at TEXT NOT NULL)",
    "CREATE TABLE item (id TEXT PRIMARY KEY, type TEXT NOT NULL, "
    "prefix TEXT NOT NULL, num INTEGER NOT NULL, state TEXT, "
    "seq INTEGER NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL)",
    "CREATE INDEX item_order ON item (prefix, num)",
    "CREATE TABLE value (item TEXT NOT NULL, field TEXT NOT NULL, "
    "value TEXT NOT NULL, PRIMARY KEY (item, field))",
    "CREATE TABLE relation (kind TEXT NOT NULL, src TEXT NOT NULL, "
    "dst TEXT NOT NULL, PRIMARY KEY (kind, src, dst))",
    "CREATE INDEX relation_dst ON relation (kind, dst)",
    "CREATE TABLE attachment (item TEXT NOT NULL, ref TEXT NOT NULL, "
    "hash TEXT, PRIMARY KEY (item, ref))",
    "CREATE TABLE event (seq INTEGER PRIMARY KEY, at TEXT NOT NULL, "
    "actor TEXT, command TEXT NOT NULL, items TEXT NOT NULL, transition TEXT, "
    "changes TEXT NOT NULL, note TEXT, warnings TEXT NOT NULL)",
    "CREATE TABLE ceiling (prefix TEXT PRIMARY KEY, n INTEGER NOT NULL)",
    # Defence in depth for NN-K10 and the append-only log: the store itself
    # refuses what no command is allowed to do.
    "CREATE TRIGGER event_append_only_u BEFORE UPDATE ON event "
    "BEGIN SELECT RAISE(ABORT, 'events are append-only'); END",
    "CREATE TRIGGER event_append_only_d BEFORE DELETE ON event "
    "BEGIN SELECT RAISE(ABORT, 'events are append-only'); END",
    "CREATE TRIGGER item_never_deleted BEFORE DELETE ON item "
    "BEGIN SELECT RAISE(ABORT, 'no command deletes an item'); END",
    "CREATE TRIGGER ceiling_never_falls BEFORE UPDATE ON ceiling "
    "WHEN NEW.n < OLD.n "
    "BEGIN SELECT RAISE(ABORT, 'a ceiling is never lowered'); END",
    "CREATE TRIGGER ceiling_never_deleted BEFORE DELETE ON ceiling "
    "BEGIN SELECT RAISE(ABORT, 'a ceiling is never lowered'); END",
)

TABLES = ("meta", "template", "item", "value", "relation", "attachment",
          "event", "ceiling")


#: The longest number part an id can have: a type pads to at most 18 digits
#: (`template.MAX_DIGITS`), and a minted number never passes 2^53, which has
#: 16. Checked before `int()`, which refuses more than 4,300 digits by raising.
MAX_ID_DIGITS = 18


def split_id(item_id: str):
    """`(prefix, number)`, or None when `item_id` is not an id's shape."""
    if not isinstance(item_id, str) or "-" not in item_id:
        return None
    prefix, _, digits = item_id.partition("-")
    if (not prefix or not digits.isascii() or not digits.isdigit()
            or len(digits) > MAX_ID_DIGITS):
        return None
    return prefix, int(digits)


def id_order(item_id: str):
    parts = split_id(item_id)
    return parts if parts else (item_id, -1)


def _deadline() -> float:
    return time.monotonic() + BUSY_TIMEOUT_S


def _busy(exc: sqlite3.Error) -> bool:
    low = str(exc).lower()
    return "locked" in low or "busy" in low


def _retrying(fn, deadline: float):
    """`fn()`, run again while sqlite answers busy or locked and `deadline`
    has not passed. sqlite's busy handler waits out a lock another connection
    holds, but it is not called where waiting could deadlock (two
    connections upgrading one file's lock at once, as two first inits do):
    SQLITE_BUSY then comes back at once. `store_busy` means the lock was not
    acquired within 5 s, so the kernel waits the rest of the 5 s itself."""
    while True:
        try:
            return fn()
        except sqlite3.OperationalError as exc:
            if not _busy(exc) or time.monotonic() >= deadline:
                raise
            time.sleep(0.005 + random.random() * 0.02)


def _db_error(exc: sqlite3.Error, path) -> KernelError:
    text = str(exc)
    low = text.lower()
    if "locked" in low or "busy" in low:
        return KernelError("store_busy", f"{path}: the write lock was not "
                                         f"acquired within "
                                         f"{BUSY_TIMEOUT_S:g} s",
                           {"store": str(path)})
    if "not a database" in low:
        return KernelError("store_foreign", f"{path} is not a kernel store",
                           {"store": str(path)})
    if "readonly" in low or "unable to open" in low or "disk i/o" in low:
        return KernelError("io_error", f"{path}: {text}", {"path": str(path)})
    return KernelError("store_corrupt", f"{path}: {text}", {"store": str(path)})


class Store:
    """One open store. Use as a context manager: the transaction is the
    `with` block, and leaving it by an exception rolls it back."""

    def __init__(self, conn: sqlite3.Connection, path, write: bool):
        self.conn = conn
        self.path = path
        self.write = write
        self._committed = False
        self._mismatch = "internal"

    # ── opening ────────────────────────────────────────────────────────────

    @staticmethod
    def _connect(path, *, create: bool) -> sqlite3.Connection:
        if str(path) == ":memory:":
            conn = sqlite3.connect(":memory:", isolation_level=None)
        else:
            mode = "rwc" if create else "rw"
            uri = f"file:{urllib.parse.quote(str(path))}?mode={mode}"
            conn = sqlite3.connect(uri, uri=True, timeout=BUSY_TIMEOUT_S,
                                   isolation_level=None)
        conn.execute(f"PRAGMA busy_timeout = {int(BUSY_TIMEOUT_S * 1000)}")
        return conn

    @staticmethod
    def probe(path) -> str:
        """`absent`, `empty` (no kernel content), `store`, or raises
        store_foreign / store_version / store_corrupt. A probe is a hint read
        outside any write transaction; a write decides again inside its own
        (`contents`), because another process can init in between (F6).

        The header and the table list are read in ONE read snapshot. Read one
        statement at a time, a concurrent init committing between them
        showed `application_id` 0 beside `user_version` 1, and the store was
        called foreign (round 4)."""
        p = Path(path)
        try:
            exists, is_dir = p.exists(), p.is_dir()
        except OSError as exc:
            raise KernelError("io_error", f"cannot inspect {p}: "
                                          f"{exc.strerror}", {"path": str(p)})
        if not exists:
            return "absent"
        if is_dir:
            raise KernelError("store_foreign", f"{p} is a directory",
                              {"store": str(p)})

        def read_header():
            conn = Store._connect(p, create=False)
            try:
                conn.execute("BEGIN")
                return Store._header(conn)
            finally:
                conn.close()  # ends the read transaction

        try:
            header = _retrying(read_header, _deadline())
        except sqlite3.Error as exc:
            raise _db_error(exc, p)
        return Store._verdict(header, p)

    @staticmethod
    def _header(conn):
        """`(application_id, user_version, table names)`, read on `conn` in
        whatever transaction it has open. sqlite errors propagate."""
        app = conn.execute("PRAGMA application_id").fetchone()[0]
        ver = conn.execute("PRAGMA user_version").fetchone()[0]
        names = [r[0] for r in conn.execute(
            "SELECT name FROM sqlite_master WHERE type = 'table'")]
        return app, ver, names

    @staticmethod
    def _verdict(header, p) -> str:
        """`empty` or `store`; raises store_foreign / version / corrupt."""
        app, ver, names = header
        if app == 0 and ver == 0 and not names:
            return "empty"
        if app != APPLICATION_ID:
            raise KernelError("store_foreign", f"{p} is not a kernel store; it "
                                               f"is left untouched",
                              {"store": str(p)})
        if ver > FORMAT:
            raise KernelError("store_version",
                              f"{p} is format {ver}; this kernel reads "
                              f"format {FORMAT}", {"store": str(p),
                                                   "format": ver})
        if ver != FORMAT or not set(TABLES) <= set(names):
            raise KernelError("store_corrupt", f"{p}: the kernel's tables are "
                                               f"incomplete", {"store": str(p)})
        return "store"

    def contents(self) -> str:
        """`empty` or `store`, decided inside this store's open transaction:
        a write that must know whether the store is initialised asks here,
        under the lock, never from an earlier probe."""
        try:
            header = self._header(self.conn)
        except sqlite3.Error as exc:
            raise _db_error(exc, self.path)
        return self._verdict(header, self.path)

    @classmethod
    def open(cls, path, *, write: bool) -> "Store":
        """Open an initialised store and begin the command's transaction.

        The deadline is set before the probe, not after it (TASK-489, F4): a
        probe that waited out a busy store leaves the steps below only what
        remains of the 5 s, so `store_busy` comes within 5 s of the call
        rather than after the probe's wait and a whole deadline more."""
        deadline = _deadline()
        state = cls.probe(path)
        if state in ("absent", "empty"):
            raise KernelError("store_missing",
                              f"{path} has not been initialised; run init",
                              {"store": str(path)})
        try:
            conn = cls._connect(path, create=False)
            mode = _retrying(lambda: conn.execute(
                "PRAGMA journal_mode").fetchone()[0], deadline)
            if str(mode).lower() != "wal":
                conn.close()
                raise KernelError("store_corrupt",
                                  f"{path}: journal_mode is {mode}, not wal",
                                  {"store": str(path)})
            _retrying(lambda: conn.execute("PRAGMA synchronous = FULL"),
                      deadline)
            if conn.execute("PRAGMA synchronous").fetchone()[0] != 2:
                conn.close()
                raise KernelError("store_corrupt", f"{path}: synchronous=FULL "
                                                   f"could not be set",
                                  {"store": str(path)})
            _retrying(lambda: conn.execute(
                "BEGIN IMMEDIATE" if write else "BEGIN"), deadline)
            if not write:
                # A deferred read transaction takes its snapshot at the first
                # read; take it now.
                _retrying(lambda: conn.execute(
                    "SELECT value FROM meta WHERE key = 'format'").fetchall(),
                    deadline)
            return cls(conn, path, write)
        except sqlite3.Error as exc:
            raise _db_error(exc, path)

    @classmethod
    def create(cls, path, *, memory: bool = False) -> "Store":
        """A new store's file, in WAL mode, inside an open write transaction.
        The schema is written by `initialise` in the same transaction."""
        deadline = _deadline()
        try:
            if memory:
                conn = cls._connect(":memory:", create=True)
            else:
                Path(path).parent.mkdir(parents=True, exist_ok=True)
                conn = cls._connect(path, create=True)
                mode = _retrying(lambda: conn.execute(
                    "PRAGMA journal_mode = WAL").fetchone()[0], deadline)
                if str(mode).lower() != "wal":
                    conn.close()
                    raise KernelError("io_error", f"{path}: WAL mode refused",
                                      {"path": str(path)})
                _retrying(lambda: conn.execute("PRAGMA synchronous = FULL"),
                          deadline)
            _retrying(lambda: conn.execute("BEGIN IMMEDIATE"), deadline)
            return cls(conn, path, True)
        except OSError as exc:
            raise KernelError("io_error", f"cannot create {path}: "
                                          f"{exc.strerror}", {"path": str(path)})
        except sqlite3.Error as exc:
            raise _db_error(exc, path)

    def initialise(self):
        """The schema and the format marker, in the open transaction. The
        state root arrives by the `init` event's `state_root` change."""
        self.q(f"PRAGMA application_id = {APPLICATION_ID}")
        self.q(f"PRAGMA user_version = {FORMAT}")
        for statement in SCHEMA:
            self.q(statement)
        self.q("INSERT INTO meta VALUES ('format', ?)", (str(FORMAT),))

    # ── the transaction ────────────────────────────────────────────────────

    def __enter__(self):
        return self

    def __exit__(self, exc_type, exc, tb):
        try:
            if not self._committed:
                self.conn.execute("ROLLBACK")
        except sqlite3.Error:
            pass
        finally:
            self.conn.close()
        return False

    def commit(self):
        try:
            self.conn.execute("COMMIT")
        except sqlite3.Error as exc:
            raise _db_error(exc, self.path)
        self._committed = True

    def rollback(self):
        try:
            self.conn.execute("ROLLBACK")
        except sqlite3.Error:
            pass
        self._committed = True  # nothing left to roll back on exit

    def q(self, sql: str, params=()):
        try:
            return self.conn.execute(sql, params).fetchall()
        except sqlite3.Error as exc:
            raise _db_error(exc, self.path)

    # ── reads ──────────────────────────────────────────────────────────────

    def _loads(self, text, where: str):
        """A stored JSON value, or store_corrupt: a row that cannot be read
        back is damage, not an internal fault (§ 5.1)."""
        try:
            return json.loads(text)
        except (TypeError, ValueError):
            raise KernelError("store_corrupt",
                              f"{self.path}: {where} cannot be read back",
                              {"store": str(self.path), "row": where})

    def meta(self, key: str):
        rows = self.q("SELECT value FROM meta WHERE key = ?", (key,))
        return rows[0][0] if rows else None

    def meta_seq(self, key: str):
        """A meta value that holds an event seq, or None when unset. Text
        that is not a short run of ASCII digits is damage, checked before
        `int()` sees it."""
        raw = self.meta(key)
        if raw is None:
            return None
        if not (raw.isascii() and raw.isdigit() and len(raw) <= 19):
            raise KernelError("store_corrupt", f"{self.path}: meta {key} "
                                               f"cannot be read back",
                              {"store": str(self.path), "row": f"meta {key}"})
        return int(raw)

    def set_meta(self, key: str, value: str):
        self.q("INSERT INTO meta VALUES (?, ?) ON CONFLICT(key) DO UPDATE "
               "SET value = excluded.value", (key, value))

    def store_seq(self) -> int:
        return self.q("SELECT COALESCE(MAX(seq), 0) FROM event")[0][0]

    def event_count(self) -> int:
        return self.q("SELECT COUNT(*) FROM event")[0][0]

    def template_row(self):
        rows = self.q("SELECT version, body, applied_seq, applied_at "
                      "FROM template ORDER BY version DESC LIMIT 1")
        if not rows:
            return None
        version, body, applied_seq, applied_at = rows[0]
        return {"version": version,
                "template": self._loads(body, f"template {version}"),
                "applied_seq": applied_seq, "applied_at": applied_at}

    def item_row(self, item_id: str):
        rows = self.q("SELECT id, type, state, seq, created_at, updated_at "
                      "FROM item WHERE id = ?", (item_id,))
        if not rows:
            return None
        i, t, s, seq, c, u = rows[0]
        return {"id": i, "type": t, "state": s, "seq": seq, "created_at": c,
                "updated_at": u}

    def item_type(self, item_id: str):
        rows = self.q("SELECT type FROM item WHERE id = ?", (item_id,))
        return rows[0][0] if rows else None

    def values(self, item_id: str) -> dict:
        return {f: self._loads(v, f"{item_id}.{f}") for f, v in self.q(
            "SELECT field, value FROM value WHERE item = ?", (item_id,))}

    def all_item_ids(self) -> list[str]:
        return [r[0] for r in self.q("SELECT id FROM item ORDER BY prefix, num")]

    def edges(self, kind=None, src=None, dst=None) -> list[tuple]:
        sql, params, where = "SELECT kind, src, dst FROM relation", [], []
        for col, val in (("kind", kind), ("src", src), ("dst", dst)):
            if val is not None:
                where.append(f"{col} = ?")
                params.append(val)
        if where:
            sql += " WHERE " + " AND ".join(where)
        rows = self.q(sql, params)
        return sorted(rows, key=lambda r: (r[0], id_order(r[1]),
                                           id_order(r[2])))

    def edges_touching(self, item_id: str) -> list[tuple]:
        rows = self.q("SELECT kind, src, dst FROM relation WHERE src = ? OR "
                      "dst = ?", (item_id, item_id))
        return sorted(rows, key=lambda r: (r[0], id_order(r[1]),
                                           id_order(r[2])))

    def has_edge(self, kind, src, dst) -> bool:
        return bool(self.q("SELECT 1 FROM relation WHERE kind = ? AND src = ? "
                           "AND dst = ?", (kind, src, dst)))

    def reaches(self, kind: str, start: str, target: str) -> bool:
        """Is `target` reachable from `start` along edges of `kind`?"""
        seen, frontier = {start}, [start]
        while frontier:
            node = frontier.pop()
            if node == target:
                return True
            for (nxt,) in self.q("SELECT dst FROM relation WHERE kind = ? AND "
                                 "src = ?", (kind, node)):
                if nxt not in seen:
                    seen.add(nxt)
                    frontier.append(nxt)
        return False

    def attachments(self, item_id: str) -> list[dict]:
        return [{"ref": r, "hash": h} for r, h in self.q(
            "SELECT ref, hash FROM attachment WHERE item = ? ORDER BY ref",
            (item_id,))]

    def attachment_hash(self, item_id: str, ref: str):
        """`(present, hash)`."""
        rows = self.q("SELECT hash FROM attachment WHERE item = ? AND ref = ?",
                      (item_id, ref))
        return (True, rows[0][0]) if rows else (False, None)

    def ceiling(self, prefix: str):
        rows = self.q("SELECT n FROM ceiling WHERE prefix = ?", (prefix,))
        return rows[0][0] if rows else None

    def items_in(self, item_type: str, state: str) -> list[str]:
        return [r[0] for r in self.q(
            "SELECT id FROM item WHERE type = ? AND state = ? "
            "ORDER BY prefix, num", (item_type, state))]

    def events(self) -> list[dict]:
        return [self._event(r) for r in self.q(
            "SELECT seq, at, actor, command, items, transition, changes, note, "
            "warnings FROM event ORDER BY seq")]

    def _event(self, row) -> dict:
        seq, at, actor, command, items, transition, changes, note, warn = row
        where = f"event {seq}"
        return {"seq": seq, "at": at,
                "actor": (self._loads(actor, where) if actor is not None
                          else None),
                "command": command, "items": self._loads(items, where),
                "transition": transition,
                "changes": self._loads(changes, where),
                "note": note, "warnings": self._loads(warn, where)}

    # ── the one write path ────────────────────────────────────────────────

    def current(self, primary, key: str):
        """The stored value a change key names, for the before comparison."""
        if key == "state_root":
            return self.meta("state_root")
        if key == "template":
            row = self.template_row()
            return row["version"] if row else None
        if key.startswith("ceiling:"):
            return self.ceiling(key[len("ceiling:"):])
        if key.startswith("rel:"):
            _, kind, src, dst = key.split(":", 3)
            return self.has_edge(kind, src, dst)
        row = self.item_row(primary) if primary else None
        if key == "type":
            return row["type"] if row else None
        if key == "state":
            return row["state"] if row else None
        if key.startswith("field:"):
            rows = self.q("SELECT value FROM value WHERE item = ? AND "
                          "field = ?", (primary, key[len("field:"):]))
            return (self._loads(rows[0][0], f"{primary}.{key[6:]}") if rows
                    else None)
        if key.startswith("attach:"):
            present, digest = self.attachment_hash(primary,
                                                   key[len("attach:"):])
            return {"hash": digest} if present else None
        raise KernelError("export_invalid", f"unknown change key {key}",
                          {"key": key})

    def apply_event(self, event: dict, *, mismatch: str, check=None) -> None:
        """Replay: apply the changes, then append the event."""
        self.apply_changes(event, mismatch=mismatch, check=check)
        self.append_event(event)

    def apply_changes(self, event: dict, *, mismatch: str,
                      check=None) -> None:
        """Apply every change of `event` and bump each touched item's seq.
        `items[0]` is the item that the `type`, `state`, `field:` and
        `attach:` keys belong to.

        Every change's `before` is compared with the stored value first. A
        replay that disagrees is `export_invalid`; a live write that disagrees
        is a kernel defect, so the caller passes `internal`.

        `check(event, primary, key, after)`, when given, runs after the
        before comparison and before the change lands, so it sees the store
        as the event's earlier changes left it. `import` passes the check
        that holds a replayed value to the template in force (TASK-489); a
        live write has already checked its values against the template."""
        seq, at = event["seq"], event["at"]
        items = event["items"]
        primary = items[0] if items else None
        self._mismatch = mismatch
        for change in event["changes"]:
            key, before, after = change["key"], change["before"], change["after"]
            now = self.current(primary, key)
            if not same(now, before):
                raise KernelError(
                    mismatch,
                    f"event {seq}: {key} is {canonical(now)} in the store, "
                    f"and the event says it was {canonical(before)}",
                    {"seq": seq, "key": key, "stored": now, "before": before})
            if check is not None:
                check(event, primary, key, after)
            self._apply_change(primary, key, after, seq, at)
        for item_id in items:
            self.q("UPDATE item SET seq = ?, updated_at = ? WHERE id = ?",
                   (seq, at, item_id))
            row = self.item_row(item_id)
            if row is None or row["state"] is None:
                raise KernelError(mismatch,
                                  f"event {seq} leaves {item_id} without a "
                                  f"type and a state", {"seq": seq})

    def append_event(self, event: dict) -> None:
        self.q("INSERT INTO event VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)",
               (event["seq"], event["at"],
                canonical(event["actor"]) if event["actor"] is not None
                else None,
                event["command"], canonical(event["items"]),
                event["transition"], canonical(event["changes"]),
                event["note"], canonical(event["warnings"])))

    def _apply_change(self, primary, key, after, seq, at):
        if key == "state_root":
            self.set_meta("state_root", after)
        elif key == "template":
            self.q("INSERT INTO template VALUES (?, ?, ?, ?)",
                   (after["version"], json.dumps(after, ensure_ascii=False),
                    seq, at))
        elif key.startswith("ceiling:"):
            self._raise_ceiling(key[len("ceiling:"):], after)
        elif key.startswith("rel:"):
            _, kind, src, dst = key.split(":", 3)
            if self.has_edge(kind, src, dst) == bool(after):
                # No command writes a relation change that flips nothing: `rel
                # add` of an edge that exists, and `rel remove` of one that
                # does not, are `unchanged` and append no event (NN-K8). A
                # replayed one is refused for every kind alike, so a no-op
                # `parent` change and a no-op `blocks` change get one answer
                # (TASK-487 round 3, F1; decided in TASK-489).
                raise KernelError(self._mismatch,
                                  f"event {seq}: {key} changes nothing; the "
                                  f"edge is already "
                                  f"{'there' if after else 'absent'}",
                                  {"seq": seq, "key": key})
            if after:
                for end in (src, dst):
                    if self.item_type(end) is None:
                        raise KernelError(self._mismatch,
                                          f"event {seq}: {key} names no item "
                                          f"{end}", {"seq": seq, "key": key})
                self._check_edge_shape(kind, src, dst, seq)
                self.q("INSERT OR IGNORE INTO relation VALUES (?, ?, ?)",
                       (kind, src, dst))
            else:
                self.q("DELETE FROM relation WHERE kind = ? AND src = ? AND "
                       "dst = ?", (kind, src, dst))
        elif key == "type":
            prefix, num = split_id(primary)
            self.q("INSERT INTO item (id, type, prefix, num, state, seq, "
                   "created_at, updated_at) VALUES (?, ?, ?, ?, NULL, ?, ?, ?)",
                   (primary, after, prefix, num, seq, at, at))
            self._raise_ceiling(prefix, num)
        elif key == "state":
            self.q("UPDATE item SET state = ? WHERE id = ?", (after, primary))
        elif key.startswith("field:"):
            field = key[len("field:"):]
            if after is None:
                self.q("DELETE FROM value WHERE item = ? AND field = ?",
                       (primary, field))
            else:
                self.q("INSERT INTO value VALUES (?, ?, ?) ON CONFLICT(item, "
                       "field) DO UPDATE SET value = excluded.value",
                       (primary, field, canonical(after)))
        elif key.startswith("attach:"):
            ref = key[len("attach:"):]
            if after is None:
                self.q("DELETE FROM attachment WHERE item = ? AND ref = ?",
                       (primary, ref))
            else:
                self.q("INSERT INTO attachment VALUES (?, ?, ?) ON CONFLICT("
                       "item, ref) DO UPDATE SET hash = excluded.hash",
                       (primary, ref, after.get("hash")))
        else:
            raise KernelError("internal", f"unknown change key {key}")

    def _check_edge_shape(self, kind: str, src: str, dst: str, seq: int):
        """The shape every edge keeps, checked on the one path that writes
        edges: `rel add`, both ends of `item create`'s relations, and
        `import`'s replay. No self-edge, at most one `parent` per item, and no
        `blocks` or `parent` cycle. A live write is refused with the rule's
        own code; a replay that breaks one is `export_invalid`."""
        replay = self._mismatch != "internal"
        details = {"kind": kind, "from": src, "to": dst}

        def refuse(code, message, **extra):
            if replay:
                raise KernelError(self._mismatch, f"event {seq}: {message}",
                                  {"seq": seq, **details, **extra})
            raise KernelError(code, message, {**details, **extra})

        if src == dst:
            refuse("relation_invalid", f"{src} cannot relate to itself")
        if kind == "parent":
            # The edge being added is never among these. A live write reaches
            # here only for an edge that is absent: `rel add` of an existing
            # edge is `unchanged` before it gets this far, and `item create`
            # makes edges to an item that did not exist. A replayed change
            # reaches here only if it flips the edge: `_apply_change` refuses
            # one whose edge is already there (`before: true, after: true`)
            # first. So src -> dst does not exist yet on any path.
            others = [d for _k, _s, d in self.edges(kind="parent", src=src)]
            if others:
                refuse("relation_invalid", f"{src} already has a parent, "
                                           f"{others[0]}", parent=others[0])
        if kind in ("blocks", "parent") and self.reaches(kind, dst, src):
            refuse("relation_cycle",
                   f"{kind} {src} -> {dst} would close a cycle")

    def _raise_ceiling(self, prefix: str, n: int):
        now = self.ceiling(prefix)
        if now is None:
            self.q("INSERT INTO ceiling VALUES (?, ?)", (prefix, n))
        elif n > now:
            self.q("UPDATE ceiling SET n = ? WHERE prefix = ?", (n, prefix))

"""The process template, format 1 (§ 5.2): validation and the normalised view.

`KEYS` is the key schema. The validator reads it and `describe` reports it, so
the two cannot say different things.
"""

from __future__ import annotations

import re

from .values import (FIELD_KINDS, ValueProblem, canonical, check_scalar,
                     json_type, same)

FORMAT = 1
NAME_RE = re.compile(r"^[a-z][a-z0-9_]{0,39}$")
PREFIX_RE = re.compile(r"^[A-Z][A-Z0-9]{0,9}$")
RESERVED_FIELDS = ("id", "type", "state")
BUILTIN_RELATIONS = {
    "blocks": "from blocks to",
    "parent": "to is the parent of from",
}
GUARD_KINDS = ("required", "actor", "relations_closed", "limit")
DIRECTIONS = ("incoming", "outgoing")
LIMIT_MODES = ("refuse", "warn")
MAX_DIGITS = 18

#: The legal keys at every level. `required` keys must be present; `optional`
#: keys may be left out (§ 5.2 "Keys").
KEYS = {
    "template": {"required": ["format", "name", "version", "types",
                              "relations"], "optional": []},
    "type": {"required": ["prefix", "states", "initial", "terminal", "fields",
                          "transitions"],
             "optional": ["digits", "create_guards"],
             "defaults": {"digits": 1, "create_guards": []}},
    "field": {"required": ["kind"], "optional": [],
              "by_kind": {"enum": {"required": ["values"],
                                   "optional": ["ordered"],
                                   "defaults": {"ordered": False}},
                          "ref": {"required": ["to"], "optional": []},
                          "list": {"required": ["of"], "optional": []}}},
    "transition": {"required": ["from", "to", "guards"], "optional": []},
    "guard": {"required": ["kind"], "optional": ["when"],
              "by_kind": {"required": {"required": [],
                                       "optional": ["fields", "at_least"]},
                          "actor": {"required": [],
                                    "optional": ["actor_kind", "name"]},
                          "relations_closed": {"required": ["relation",
                                                            "direction"],
                                               "optional": []},
                          "limit": {"required": ["max", "mode"],
                                    "optional": ["per"],
                                    "defaults": {"per": []}}}},
    "relation": {"required": ["from", "to"], "optional": []},
}


def _in(value, names) -> bool:
    """Membership that a list or an object in the caller's template cannot
    turn into a TypeError: only a string can name something."""
    return isinstance(value, str) and value in names


class Problems:
    def __init__(self):
        self.items: list[dict] = []

    def add(self, path: str, message: str):
        self.items.append({"path": path, "message": message})

    def __bool__(self):
        return bool(self.items)


def _keys(obj, level: dict, path: str, problems: Problems, kind=None) -> bool:
    """Only the declared keys, and every required one. False if `obj` is not
    an object at all."""
    if not isinstance(obj, dict):
        problems.add(path, f"expected an object, got {json_type(obj)}")
        return False
    required = list(level["required"])
    optional = list(level["optional"])
    if _in(kind, level.get("by_kind", {})):
        required += level["by_kind"][kind]["required"]
        optional += level["by_kind"][kind]["optional"]
    legal = set(required) | set(optional)
    for key in obj:
        if key not in legal:
            problems.add(f"{path}.{key}", f"unknown key; legal: "
                                          f"{', '.join(sorted(legal))}")
    for key in required:
        if key not in obj:
            problems.add(f"{path}.{key}", "required key is missing")
    return True


def _name(value, path: str, problems: Problems) -> bool:
    if not isinstance(value, str) or not NAME_RE.match(value):
        problems.add(path, f"{canonical(value)} does not match "
                           f"{NAME_RE.pattern}")
        return False
    return True


def _name_list(value, path: str, problems: Problems, *, allowed=None,
               empty_ok=False) -> list:
    if not isinstance(value, list) or (not value and not empty_ok):
        problems.add(path, "expected a non-empty array of names"
                     if not empty_ok else "expected an array of names")
        return []
    out = []
    for n, v in enumerate(value):
        if not isinstance(v, str):
            problems.add(f"{path}[{n}]", "expected a name")
            continue
        if allowed is not None and v not in allowed:
            problems.add(f"{path}[{n}]", f"{v} is not one of "
                                         f"{', '.join(sorted(allowed))}")
            continue
        if v in out:
            problems.add(f"{path}[{n}]", f"{v} is listed twice")
            continue
        out.append(v)
    return out


def _field_decl(decl, path: str, problems: Problems, types: set,
                element: bool = False) -> None:
    kind = decl.get("kind") if isinstance(decl, dict) else None
    if not _keys(decl, KEYS["field"], path, problems, kind):
        return
    if kind not in FIELD_KINDS:
        problems.add(f"{path}.kind", f"{canonical(kind)} is not one of "
                                     f"{', '.join(FIELD_KINDS)}")
        return
    if element and kind in ("list", "metric"):
        problems.add(f"{path}.kind", "a list element cannot be a list or a "
                                     "metric")
        return
    if kind == "enum":
        values = decl.get("values")
        if not isinstance(values, list) or not values:
            problems.add(f"{path}.values", "expected a non-empty array")
        else:
            for n, v in enumerate(values):
                if not isinstance(v, (str, bool)):
                    problems.add(f"{path}.values[{n}]",
                                 "an enum value is a string or a boolean")
                elif any(same(v, w) for w in values[:n]):
                    problems.add(f"{path}.values[{n}]", "listed twice")
        if "ordered" in decl and not isinstance(decl["ordered"], bool):
            problems.add(f"{path}.ordered", "expected a boolean")
    elif kind == "ref":
        if "to" in decl:
            _name_list(decl["to"], f"{path}.to", problems, allowed=types)
    elif kind == "list":
        if "of" in decl:
            _field_decl(decl["of"], f"{path}.of", problems, types, element=True)


def _when(when, path: str, problems: Problems, fields: dict) -> None:
    if not isinstance(when, dict) or len(when) != 1:
        problems.add(path, "when names exactly one field")
        return
    (name, values), = when.items()
    decl = fields.get(name)
    if decl is None or not isinstance(decl, dict):
        problems.add(f"{path}.{name}", "not a field of this type")
        return
    if decl.get("kind") in ("list", "metric"):
        problems.add(f"{path}.{name}", "when cannot name a list or a metric "
                                       "field")
        return
    if not isinstance(values, list) or not values:
        problems.add(f"{path}.{name}", "expected a non-empty array of values")
        return
    for n, v in enumerate(values):
        if v is None:
            continue
        if decl.get("kind") == "ref":
            # An id cannot be resolved against a store here; only its shape.
            if not isinstance(v, str) or not v:
                problems.add(f"{path}.{name}[{n}]", "a ref value is an id")
            continue
        try:
            check_scalar(decl, v)
        except ValueProblem as exc:
            problems.add(f"{path}.{name}[{n}]", exc.message)
        except (KeyError, TypeError):
            # The field's own declaration is malformed; that is reported at
            # the field's path.
            pass


def _guard(guard, path: str, problems: Problems, fields: dict,
           relation_kinds: set) -> None:
    kind = guard.get("kind") if isinstance(guard, dict) else None
    if not _keys(guard, KEYS["guard"], path, problems, kind):
        return
    if kind not in GUARD_KINDS:
        problems.add(f"{path}.kind", f"{canonical(kind)} is not one of "
                                     f"{', '.join(GUARD_KINDS)}")
        return
    if "when" in guard:
        _when(guard["when"], f"{path}.when", problems, fields)
    if kind == "required":
        names = guard.get("fields", [])
        at_least = guard.get("at_least", {})
        if not isinstance(names, list):
            problems.add(f"{path}.fields", "expected an array of field names")
            names = []
        if not isinstance(at_least, dict):
            problems.add(f"{path}.at_least", "expected an object")
            at_least = {}
        if not names and not at_least:
            problems.add(path, "required needs a non-empty fields or at_least")
        _name_list(names, f"{path}.fields", problems, allowed=set(fields),
                   empty_ok=True)
        for name, minimum in at_least.items():
            decl = fields.get(name)
            if not isinstance(decl, dict):
                problems.add(f"{path}.at_least.{name}", "not a field of this "
                                                        "type")
            elif decl.get("kind") != "enum" or decl.get("ordered") is not True:
                problems.add(f"{path}.at_least.{name}", "at_least names an "
                                                        "ordered enum")
            elif not isinstance(decl.get("values"), list) or not any(
                    same(minimum, v) for v in decl["values"]):
                problems.add(f"{path}.at_least.{name}",
                             f"{canonical(minimum)} is not one of its values")
    elif kind == "actor":
        if "actor_kind" not in guard and "name" not in guard:
            problems.add(path, "actor needs actor_kind, name, or both")
        if "actor_kind" in guard and guard["actor_kind"] not in ("human",
                                                                 "agent"):
            problems.add(f"{path}.actor_kind", "human or agent")
        if "name" in guard and (not isinstance(guard["name"], str)
                                or not guard["name"].strip()):
            problems.add(f"{path}.name", "a non-empty string")
    elif kind == "relations_closed":
        if "relation" in guard and not _in(guard["relation"],
                                           relation_kinds):
            problems.add(f"{path}.relation",
                         f"{canonical(guard['relation'])} is not a relation "
                         f"kind")
        if "direction" in guard and guard["direction"] not in DIRECTIONS:
            problems.add(f"{path}.direction", "incoming or outgoing")
    elif kind == "limit":
        mx = guard.get("max")
        if "max" in guard and (isinstance(mx, bool) or not isinstance(mx, int)
                               or mx < 1):
            problems.add(f"{path}.max", "an integer of at least 1")
        if "mode" in guard and guard["mode"] not in LIMIT_MODES:
            problems.add(f"{path}.mode", "refuse or warn")
        per = guard.get("per", [])
        names = _name_list(per, f"{path}.per", problems, allowed=set(fields),
                           empty_ok=True)
        for n, name in enumerate(names):
            if fields[name].get("kind") in ("list", "metric"):
                problems.add(f"{path}.per[{n}]", "per cannot name a list or a "
                                                 "metric field")


def validate(template) -> list[dict]:
    """Every problem with a template, as `{path, message}`. Empty when valid."""
    problems = Problems()
    if not _keys(template, KEYS["template"], "template", problems):
        return problems.items
    fmt = template.get("format")
    if "format" in template and (isinstance(fmt, bool) or fmt != FORMAT):
        problems.add("template.format", f"this kernel reads format {FORMAT}")
    if "name" in template and (not isinstance(template["name"], str)
                               or not template["name"].strip()):
        problems.add("template.name", "a non-empty string")
    ver = template.get("version")
    if "version" in template and (isinstance(ver, bool)
                                  or not isinstance(ver, int) or ver < 1):
        problems.add("template.version", "a positive integer")
    types = template.get("types")
    relations = template.get("relations")
    if "types" in template and (not isinstance(types, dict) or not types):
        problems.add("template.types", "a non-empty object of types")
        types = {}
    if "relations" in template and not isinstance(relations, dict):
        problems.add("template.relations", "an object of relation kinds")
        relations = {}
    types = types if isinstance(types, dict) else {}
    relations = relations if isinstance(relations, dict) else {}
    type_names = {t for t in types if isinstance(t, str) and NAME_RE.match(t)}
    for t in types:
        _name(t, f"template.types.{t}", problems)
    for r in relations:
        path = f"template.relations.{r}"
        if _name(r, path, problems) and r in BUILTIN_RELATIONS:
            problems.add(path, f"{r} is built in and cannot be declared")
        decl = relations[r]
        if _keys(decl, KEYS["relation"], path, problems):
            for end in ("from", "to"):
                if end in decl:
                    _name_list(decl[end], f"{path}.{end}", problems,
                               allowed=type_names)
    relation_kinds = set(BUILTIN_RELATIONS) | {
        r for r in relations if isinstance(r, str)}
    prefixes: dict[str, str] = {}
    for t, decl in types.items():
        path = f"template.types.{t}"
        if not _keys(decl, KEYS["type"], path, problems):
            continue
        prefix = decl.get("prefix")
        if "prefix" in decl:
            if not isinstance(prefix, str) or not PREFIX_RE.match(prefix):
                problems.add(f"{path}.prefix", f"{canonical(prefix)} does not "
                                               f"match {PREFIX_RE.pattern}")
            elif prefix in prefixes:
                problems.add(f"{path}.prefix", f"{prefix} is also "
                                               f"{prefixes[prefix]}'s prefix")
            else:
                prefixes[prefix] = t
        digits = decl.get("digits", 1)
        if isinstance(digits, bool) or not isinstance(digits, int) or not (
                1 <= digits <= MAX_DIGITS):
            problems.add(f"{path}.digits", f"an integer from 1 to {MAX_DIGITS}")
        states = []
        if "states" in decl:
            states = _name_list(decl["states"], f"{path}.states", problems)
            for n, s in enumerate(states):
                _name(s, f"{path}.states[{n}]", problems)
        state_set = set(states)
        if "initial" in decl and not _in(decl["initial"], state_set):
            problems.add(f"{path}.initial", "not one of the type's states")
        if "terminal" in decl:
            _name_list(decl["terminal"], f"{path}.terminal", problems,
                       allowed=state_set)
        fields = decl.get("fields")
        if "fields" in decl and not isinstance(fields, dict):
            problems.add(f"{path}.fields", "an object of field declarations")
        fields = fields if isinstance(fields, dict) else {}
        for f, fdecl in fields.items():
            fpath = f"{path}.fields.{f}"
            if _name(f, fpath, problems) and f in RESERVED_FIELDS:
                problems.add(fpath, f"{f} cannot be a field name")
            _field_decl(fdecl, fpath, problems, type_names)
        good_fields = {f: d for f, d in fields.items() if isinstance(d, dict)}
        guards = decl.get("create_guards", [])
        if not isinstance(guards, list):
            problems.add(f"{path}.create_guards", "an array of guards")
            guards = []
        for n, g in enumerate(guards):
            _guard(g, f"{path}.create_guards[{n}]", problems, good_fields,
                   relation_kinds)
        transitions = decl.get("transitions")
        if "transitions" in decl and not isinstance(transitions, dict):
            problems.add(f"{path}.transitions", "an object of transitions")
        transitions = transitions if isinstance(transitions, dict) else {}
        for name, tdecl in transitions.items():
            tpath = f"{path}.transitions.{name}"
            _name(name, tpath, problems)
            if not _keys(tdecl, KEYS["transition"], tpath, problems):
                continue
            if "from" in tdecl:
                _name_list(tdecl["from"], f"{tpath}.from", problems,
                           allowed=state_set)
            if "to" in tdecl and not _in(tdecl["to"], state_set):
                problems.add(f"{tpath}.to", "not one of the type's states")
            tguards = tdecl.get("guards")
            if "guards" in tdecl and not isinstance(tguards, list):
                problems.add(f"{tpath}.guards", "an array of guards")
                tguards = []
            for n, g in enumerate(tguards or []):
                _guard(g, f"{tpath}.guards[{n}]", problems, good_fields,
                       relation_kinds)
    return problems.items


def normalize(template: dict) -> dict:
    """A valid template with every default filled in. Never stored: the store
    keeps what the caller applied, verbatim."""
    out = {"format": template["format"], "name": template["name"],
           "version": template["version"], "types": {},
           "relations": {k: {"from": list(v["from"]), "to": list(v["to"])}
                         for k, v in template["relations"].items()}}
    for t, decl in template["types"].items():
        fields = {}
        for f, fdecl in decl["fields"].items():
            fields[f] = _normalize_field(fdecl)
        out["types"][t] = {
            "prefix": decl["prefix"],
            "digits": decl.get("digits", 1),
            "states": list(decl["states"]),
            "initial": decl["initial"],
            "terminal": list(decl["terminal"]),
            "fields": fields,
            "create_guards": [_normalize_guard(g)
                              for g in decl.get("create_guards", [])],
            "transitions": {
                n: {"from": list(td["from"]), "to": td["to"],
                    "guards": [_normalize_guard(g) for g in td["guards"]]}
                for n, td in decl["transitions"].items()},
        }
    return out


def _normalize_field(decl: dict) -> dict:
    out = dict(decl)
    if decl["kind"] == "enum":
        out.setdefault("ordered", False)
    if decl["kind"] == "list":
        out["of"] = _normalize_field(decl["of"])
    return out


def _normalize_guard(guard: dict) -> dict:
    out = dict(guard)
    out.setdefault("when", None)
    if guard["kind"] == "limit":
        out.setdefault("per", [])
    if guard["kind"] == "required":
        out.setdefault("fields", [])
        out.setdefault("at_least", {})
    return out


def relation_kinds(norm: dict) -> set:
    return set(BUILTIN_RELATIONS) | set(norm["relations"])


def schema() -> dict:
    """The key schema as `describe` reports it."""
    return {level: {k: v for k, v in spec.items()} for level, spec in
            KEYS.items()}

"""JSON helpers, field-kind validation and the metric formula (§ 5.3, § 5.5).

Nothing here touches the store. A `ref` value is resolved through a lookup
function the caller passes in, so this module stays pure.
"""

from __future__ import annotations

import datetime
import json
import math
import re

FIELD_KINDS = ("text", "int", "number", "date", "enum", "actor", "ref", "list",
               "metric")
ACTOR_KINDS = ("human", "agent")
METRIC_KEYS = ("current", "target", "baseline", "direction")
DIRECTIONS = ("up", "down")
INT_LIMIT = 2 ** 53
DATE_RE = re.compile(r"^[0-9]{4}-[0-9]{2}-[0-9]{2}$")


# ── JSON ────────────────────────────────────────────────────────────────────


def canonical(value) -> str:
    """The one serialisation: sorted keys, compact, UTF-8 (§ 5.8)."""
    return json.dumps(value, sort_keys=True, separators=(",", ":"),
                      ensure_ascii=False)


#: What any JSON the kernel reads must satisfy before a command sees it, so
#: that no input class can surface as `internal`: sqlite stores integers in
#: 64 bits, UTF-8 cannot carry a lone surrogate, and nesting is bounded.
SQL_INT_MIN, SQL_INT_MAX = -(2 ** 63), 2 ** 63 - 1
MAX_DEPTH = 64
SURROGATE = re.compile("[\ud800-\udfff]")


def input_problem(value):
    """`(path, message)` for the first part of `value` that cannot be kernel
    input, or None. Walks iteratively, so depth cannot overflow the stack.
    A message never quotes the offending value."""
    stack = [(value, "", 1)]
    while stack:
        item, path, depth = stack.pop()
        where = path or "(top)"
        if depth > MAX_DEPTH:
            return where, f"nested more than {MAX_DEPTH} levels deep"
        if isinstance(item, str):
            if SURROGATE.search(item):
                return where, "a string holds a lone surrogate, which is " \
                              "not Unicode text"
        elif isinstance(item, bool) or item is None:
            continue
        elif isinstance(item, int):
            if not SQL_INT_MIN <= item <= SQL_INT_MAX:
                return where, "an integer is outside -2^63 to 2^63-1"
        elif isinstance(item, float):
            if not math.isfinite(item):
                return where, "a number is not finite"
        elif isinstance(item, list):
            stack.extend((e, f"{path}[{n}]", depth + 1)
                         for n, e in enumerate(item))
        elif isinstance(item, dict):
            for key, element in item.items():
                if SURROGATE.search(key):
                    return where, "a key holds a lone surrogate, which is " \
                                  "not Unicode text"
                stack.append((element, f"{path}.{key}" if path else key,
                              depth + 1))
    return None


def json_type(value) -> str:
    if value is None:
        return "null"
    if isinstance(value, bool):
        return "boolean"
    if isinstance(value, int):
        return "integer"
    if isinstance(value, float):
        return "number"
    if isinstance(value, str):
        return "string"
    if isinstance(value, list):
        return "array"
    if isinstance(value, dict):
        return "object"
    return type(value).__name__


def same(a, b) -> bool:
    """JSON equality: a boolean never equals a number, 1 equals 1.0."""
    if isinstance(a, bool) or isinstance(b, bool):
        return isinstance(a, bool) and isinstance(b, bool) and a == b
    if isinstance(a, (int, float)) and isinstance(b, (int, float)):
        return a == b
    if isinstance(a, list) and isinstance(b, list):
        return len(a) == len(b) and all(same(x, y) for x, y in zip(a, b))
    if isinstance(a, dict) and isinstance(b, dict):
        return a.keys() == b.keys() and all(same(a[k], b[k]) for k in a)
    return type(a) is type(b) and a == b


def is_number(value) -> bool:
    return (isinstance(value, (int, float)) and not isinstance(value, bool)
            and math.isfinite(value))


# ── set / unset (§ 5.3, the last column) ────────────────────────────────────


def is_set(kind: str, value) -> bool:
    if value is None:
        return False
    if kind == "text":
        return isinstance(value, str) and value.strip() != ""
    if kind == "list":
        return isinstance(value, list) and len(value) > 0
    if kind == "metric":
        return isinstance(value, dict) and value.get("current") is not None
    return True


def effective(kind: str, value):
    """The value a `when`, a `per` or a `where` compares: `None` when unset."""
    return value if is_set(kind, value) else None


# ── validation ──────────────────────────────────────────────────────────────


class ValueProblem(Exception):
    """A value that does not fit. `code` is field_invalid, metric_invalid or
    item_not_found; the caller turns it into a KernelError with its path."""

    def __init__(self, code: str, message: str):
        super().__init__(message)
        self.code = code
        self.message = message


def valid_date(text) -> bool:
    if not isinstance(text, str) or not DATE_RE.match(text):
        return False
    try:
        datetime.date(int(text[0:4]), int(text[5:7]), int(text[8:10]))
    except ValueError:
        return False
    return True


def normalize_actor(value, *, problem=ValueProblem, code="field_invalid"):
    """`{"kind", "name", "session"}`, session required for an agent."""
    if not isinstance(value, dict):
        raise problem(code, "an actor is an object")
    extra = sorted(set(value) - {"kind", "name", "session"})
    if extra:
        raise problem(code, f"an actor takes kind, name and session, not "
                            f"{', '.join(extra)}")
    kind = value.get("kind")
    if kind not in ACTOR_KINDS:
        raise problem(code, "an actor's kind is human or agent")
    name = value.get("name")
    if not isinstance(name, str) or not name.strip():
        raise problem(code, "an actor's name is a non-empty string")
    session = value.get("session")
    if session is not None and (not isinstance(session, str)
                                or not session.strip()):
        raise problem(code, "an actor's session is a non-empty string")
    if kind == "agent" and session is None:
        raise problem(code, "an agent actor needs a session")
    return {"kind": kind, "name": name, "session": session}


def check_scalar(decl: dict, value, lookup=None):
    """Validate one non-null value against a non-metric declaration and return
    it normalised. `lookup(id)` returns the item's type or None."""
    kind = decl["kind"]
    if kind == "text":
        if not isinstance(value, str):
            raise ValueProblem("field_invalid", "a text value is a string")
        return value
    if kind == "int":
        if isinstance(value, bool) or not isinstance(value, int):
            raise ValueProblem("field_invalid", "an int value is a JSON integer")
        if abs(value) > INT_LIMIT:
            raise ValueProblem("field_invalid", "an int value is at most 2^53 "
                                                "in magnitude")
        return value
    if kind == "number":
        if not is_number(value):
            raise ValueProblem("field_invalid", "a number value is a finite "
                                                "JSON number")
        return value
    if kind == "date":
        if not valid_date(value):
            raise ValueProblem("field_invalid", "a date value is a valid "
                                                "calendar date, YYYY-MM-DD")
        return value
    if kind == "enum":
        if not any(same(value, v) for v in decl["values"]):
            raise ValueProblem("field_invalid",
                               f"{canonical(value)} is not one of "
                               f"{canonical(decl['values'])}")
        return value
    if kind == "actor":
        return normalize_actor(value)
    if kind == "ref":
        if not isinstance(value, str):
            raise ValueProblem("field_invalid", "a ref value is an item id")
        found = lookup(value) if lookup else None
        if found is None:
            raise ValueProblem("item_not_found", f"no item {value}")
        if found not in decl["to"]:
            raise ValueProblem("field_invalid",
                               f"{value} is a {found}; this ref takes "
                               f"{', '.join(decl['to'])}")
        return value
    if kind == "list":
        if not isinstance(value, list):
            raise ValueProblem("field_invalid", "a list value is a JSON array")
        out = []
        for n, element in enumerate(value):
            if element is None:
                raise ValueProblem("field_invalid", f"element {n} is null")
            try:
                out.append(check_scalar(decl["of"], element, lookup))
            except ValueProblem as exc:
                raise ValueProblem(exc.code, f"element {n}: {exc.message}")
        return out
    raise ValueProblem("field_invalid", f"no value rule for kind {kind}")


def merge_metric(stored, given):
    """§ 5.3: a metric `set` merges the keys given into the stored value."""
    if not isinstance(given, dict):
        raise ValueProblem("metric_invalid", "a metric value is an object")
    extra = sorted(set(given) - set(METRIC_KEYS))
    if extra:
        raise ValueProblem("metric_invalid",
                           f"a metric takes {', '.join(METRIC_KEYS)}, not "
                           f"{', '.join(extra)}")
    merged = dict(stored or {})
    merged.update(given)
    return check_metric(merged)


def check_metric(value) -> dict:
    if not isinstance(value, dict):
        raise ValueProblem("metric_invalid", "a metric value is an object")
    extra = sorted(set(value) - set(METRIC_KEYS))
    if extra:
        raise ValueProblem("metric_invalid",
                           f"a metric takes {', '.join(METRIC_KEYS)}, not "
                           f"{', '.join(extra)}")
    for key in ("target", "direction"):
        if value.get(key) is None:
            raise ValueProblem("metric_invalid", f"a metric needs {key}")
    target, direction = value["target"], value["direction"]
    current, baseline = value.get("current"), value.get("baseline")
    if not is_number(target):
        raise ValueProblem("metric_invalid", "target is a finite number")
    if direction not in DIRECTIONS:
        raise ValueProblem("metric_invalid", "direction is up or down")
    for key, v in (("current", current), ("baseline", baseline)):
        if v is not None and not is_number(v):
            raise ValueProblem("metric_invalid", f"{key} is a finite number "
                                                 f"or null")
    if baseline is not None:
        beyond = target > baseline if direction == "up" else target < baseline
        if not beyond:
            raise ValueProblem("metric_invalid",
                               f"target must be {'above' if direction == 'up' else 'below'} "
                               f"baseline for direction {direction}")
    return {"current": current, "target": target, "baseline": baseline,
            "direction": direction}


# ── the metric formula (§ 5.5) ──────────────────────────────────────────────


def metric_met(value: dict):
    current = value.get("current")
    if current is None:
        return None
    if value["direction"] == "up":
        return current >= value["target"]
    return current <= value["target"]


def metric_fraction(value: dict):
    current, baseline = value.get("current"), value.get("baseline")
    if current is None or baseline is None:
        return None
    raw = (current - baseline) / (value["target"] - baseline)
    if raw <= 0:
        return 0.0
    if raw >= 1:
        return 1.0
    return min(0.999, max(0.001, round(raw, 3)))


def with_derived(value: dict) -> dict:
    """A stored metric plus `met` and `fraction`, for `item get` and `query`."""
    out = dict(value)
    out["met"] = metric_met(value)
    out["fraction"] = metric_fraction(value)
    return out

#!/usr/bin/env python3
"""Perry product release records; typed metadata and opaque, agent-authored notes.

This is product maintenance data, not a generic project's Perry state.
"""
from __future__ import annotations

import argparse
import contextlib
import datetime as dt
import fcntl
import json
import os
from pathlib import Path
import re
import subprocess
import sys
import tempfile

ROOT = Path(__file__).resolve().parent.parent
RECORDS = "release/records.jsonl"
PROJECTIONS = ("VERSION", "CHANGELOG.md")
FIELDS = {"version", "date", "kind", "phase", "task", "delivery", "integrator",
          "notes", "upgrade", "breaking", "decision"}
VERSION = re.compile(r"(?:0|[1-9][0-9]*)\.(?:0|[1-9][0-9]*)\.(?:0|[1-9][0-9]*)\Z")
PHASE = re.compile(r"[0-9]{3,}-[a-z][a-z0-9-]*\Z")
TOKEN = re.compile(r"[A-Za-z0-9][A-Za-z0-9._:/-]{0,199}\Z")
# Dogfood state is not shipped product code. The phase pointer is the one
# lifecycle exception: starting Perry's own new phase requires a minor entry.
PMO_PREFIXES = ("perry/",)
PMO_FILES = {".perry/config.jsonl", ".perry/events.jsonl", ".perry/hook.md"}
PMO_CONFIG_PREFIXES = (".perry/roles/",)
PHASE_POINTER = "perry/phase/CURRENT"


class Refused(ValueError):
    pass


def git(root: Path, *args: str, missing=False) -> bytes:
    out = subprocess.run(["git", "-C", str(root), *args], capture_output=True)
    if out.returncode and not missing:
        raise Refused("git " + args[0] + ": " + out.stderr.decode(errors="replace").strip())
    return out.stdout if out.returncode == 0 else b""


def commit(root: Path, ref: str) -> str:
    return git(root, "rev-parse", "--verify", ref + "^{commit}").decode().strip()


def version(value: str) -> tuple[int, int, int]:
    if not isinstance(value, str) or not VERSION.fullmatch(value):
        raise Refused("version must be canonical numeric major.minor.patch")
    return tuple(map(int, value.split(".")))


def required_text(value, field: str) -> None:
    if not isinstance(value, str) or not value.strip() or "\x00" in value:
        raise Refused(f"{field} requires nonempty text (write 'None.' when appropriate)")


def validate(rows: list[dict]) -> None:
    if not rows:
        raise Refused("no release records; restore the canonical record file")
    deliveries, phases, decisions = set(), set(), set()
    previous = None
    for row in rows:
        if not isinstance(row, dict) or set(row) != FIELDS:
            raise Refused("release record has missing or unknown fields")
        for field in ("notes", "upgrade", "breaking", "integrator"):
            required_text(row[field], field)
        for field in ("delivery",):
            if not isinstance(row[field], str) or not TOKEN.fullmatch(row[field]):
                raise Refused(f"invalid {field}")
        if row["delivery"] in deliveries:
            raise Refused("duplicate delivery: " + row["delivery"])
        deliveries.add(row["delivery"])
        if not isinstance(row["phase"], str) or not PHASE.fullmatch(row["phase"]):
            raise Refused("phase must be a numbered slug, e.g. 004-guided")
        if row["task"] is not None and (not isinstance(row["task"], str)
                or not re.fullmatch(r"TASK-[0-9]+", row["task"])):
            raise Refused("task must be TASK-<number> or null")
        try:
            date = dt.date.fromisoformat(row["date"])
            if date.isoformat() != row["date"]:
                raise ValueError()
        except (ValueError, TypeError):
            raise Refused("date must be YYYY-MM-DD") from None
        current = version(row["version"])
        kind = row["kind"]
        if previous is None:
            if (kind, row["version"], row["phase"], row["task"], row["delivery"]) != (
                    "baseline", "0.1.0", "004-guided", "TASK-462", "TASK-462-baseline"):
                raise Refused("first record must be the TASK-462 phase-004 0.1.0 baseline")
            phases.add(row["phase"])
        else:
            a, b, c = version(previous["version"])
            if row["date"] < previous["date"]:
                raise Refused("release dates must not go backwards")
            if kind == "patch":
                expected = (a, b, c + 1)
                if row["phase"] != previous["phase"] or row["task"] is None:
                    raise Refused("patch requires a task delivery in the current phase")
            elif kind == "phase":
                expected = (a, b + 1, 0)
                if (row["phase"] in phases or int(row["phase"].split("-", 1)[0])
                        <= int(previous["phase"].split("-", 1)[0])):
                    raise Refused("phase must be new and move forwards")
                phases.add(row["phase"])
            elif kind == "major":
                expected = (a + 1, 0, 0)
                if row["phase"] != previous["phase"]:
                    raise Refused("major allocation keeps the current phase")
            else:
                raise Refused("only the first record can be a baseline")
            if current != expected:
                raise Refused("out-of-order version: expected " + ".".join(map(str, expected)))
        if kind == "major":
            if not isinstance(row["decision"], str) or not TOKEN.fullmatch(row["decision"]):
                raise Refused("major requires an explicit human-decision reference")
            if row["decision"] in decisions:
                raise Refused("major decision reference has already been used")
            decisions.add(row["decision"])
        elif row["decision"] is not None:
            raise Refused("decision is reserved for a major allocation")
        previous = row


def load(raw: bytes) -> list[dict]:
    try:
        # Reject duplicate JSON keys, which otherwise silently replace values.
        def pairs(items):
            out = {}
            for key, value in items:
                if key in out:
                    raise Refused("duplicate JSON field: " + key)
                out[key] = value
            return out
        rows = [json.loads(line, object_pairs_hook=pairs)
                for line in raw.decode("utf-8").splitlines() if line.strip()]
    except (UnicodeError, json.JSONDecodeError) as exc:
        raise Refused("corrupt release records: " + str(exc)) from exc
    validate(rows)
    return rows


def notes(row: dict) -> str:
    task = f" · {row['task']}" if row["task"] else ""
    return (f"## {row['version']} — {row['date']}\n\n"
            f"{row['kind']} · phase {row['phase']}{task} · delivery {row['delivery']}\n\n"
            f"### Changes\n\n{row['notes']}\n\n"
            f"### Upgrade notes\n\n{row['upgrade']}\n\n"
            f"### Breaking changes\n\n{row['breaking']}\n")


def projections(rows: list[dict]) -> dict[str, bytes]:
    return {"VERSION": (rows[-1]["version"] + "\n").encode("ascii"),
            "CHANGELOG.md": ("# Perry changelog\n\nGenerated from release/records.jsonl; "
                             "edit records through the release tool.\n\n"
                             + "\n".join(notes(row) for row in reversed(rows))).encode("utf-8")}


def read(root: Path, path: str, ref: str | None = None) -> bytes:
    if ref:
        sha = commit(root, ref)
        out = subprocess.run(["git", "-C", str(root), "show", f"{sha}:{path}"],
                             capture_output=True)
        if out.returncode:
            raise Refused(f"missing {path} at {sha}")
        return out.stdout
    try:
        return (root / path).read_bytes()
    except OSError as exc:
        raise Refused(f"cannot read {path}: {exc}") from exc


def checked(root: Path, ref: str | None = None) -> list[dict]:
    rows = load(read(root, RECORDS, ref))
    for path, expected in projections(rows).items():
        if read(root, path, ref) != expected:
            raise Refused(f"projection drift: {path}; inspect records then run render --repair")
    return rows


def atomic(path: Path, data: bytes) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    fd, tmp = tempfile.mkstemp(prefix=".release-", dir=path.parent)
    try:
        with os.fdopen(fd, "wb") as stream:
            stream.write(data)
            stream.flush()
            os.fsync(stream.fileno())
        os.replace(tmp, path)
        directory = os.open(path.parent, os.O_RDONLY)
        try:
            os.fsync(directory)
        finally:
            os.close(directory)
    finally:
        if os.path.exists(tmp):
            os.unlink(tmp)


@contextlib.contextmanager
def locked(root: Path):
    path = Path(git(root, "rev-parse", "--git-path", "perry-release.lock").decode().strip())
    if not path.is_absolute():
        path = root / path
    with path.open("a") as stream:
        fcntl.flock(stream, fcntl.LOCK_EX)
        yield


def render(root: Path) -> list[dict]:
    rows = load(read(root, RECORDS))
    for path, data in projections(rows).items():
        atomic(root / path, data)
    return checked(root)


def allocate(root: Path, kind: str, *, expected: str, date: str, phase: str,
             task: str | None, delivery: str, integrator: str, changes: str,
             upgrade: str, breaking: str, decision: str | None) -> dict:
    with locked(root):
        old = checked(root)
        if old[-1]["version"] != expected:
            raise Refused("stale expected version; rebase on the main integration history")
        a, b, c = version(expected)
        number = {"patch": (a, b, c + 1), "phase": (a, b + 1, 0),
                  "major": (a + 1, 0, 0)}[kind]
        row = dict(version=".".join(map(str, number)), date=date, kind=kind,
                   phase=phase, task=task, delivery=delivery, integrator=integrator,
                   notes=changes, upgrade=upgrade, breaking=breaking, decision=decision)
        validate(old + [row])
        raw = read(root, RECORDS)
        if not raw.endswith(b"\n"):
            raw += b"\n"
        # Canonical atomic replacement first. A crash before either projection
        # finishes makes checked() refuse; explicit render repairs from truth.
        atomic(root / RECORDS, raw + (json.dumps(row, ensure_ascii=False, sort_keys=True)
                                     + "\n").encode("utf-8"))
        render(root)
        return row


def product(path: str) -> bool:
    if path in (RECORDS, *PROJECTIONS):
        return False
    return not (path in PMO_FILES or path.startswith(PMO_PREFIXES + PMO_CONFIG_PREFIXES))


def check_base(root: Path, base: str, head: str) -> dict:
    base_sha, head_sha = commit(root, base), commit(root, head)
    if subprocess.run(["git", "-C", str(root), "merge-base", "--is-ancestor",
                       base_sha, head_sha], capture_output=True).returncode:
        raise Refused("base is not an ancestor of the checked commit")
    current = checked(root, head_sha)
    paths = git(root, "diff", "--no-renames", "--name-only", "-z",
                base_sha, head_sha).decode().split("\0")
    paths = [p for p in paths if p]
    exists = git(root, "ls-tree", "--name-only", base_sha, "--", RECORDS).strip()
    if exists:
        before = checked(root, base_sha)
        if current[:len(before)] != before or len(current) < len(before):
            raise Refused("release history was rewritten or deleted")
        new = current[len(before):]
    else:
        # Only a genuinely pre-versioned ancestor gets the first-introduction
        # exception; deleting/reintroducing later cannot reset history (--full-history: nor a merge).
        if git(root, "log", "--full-history", "--format=%H", base_sha, "--", RECORDS).strip():
            raise Refused("base lost existing release history; baseline cannot be reintroduced")
        # No base ancestor held it: the ancestry-first commit touching it (merges too) adds it.
        adds = git(root, "log", "--reverse", "--topo-order", "--full-history", "--format=%H",
                   f"{base_sha}..{head_sha}", "--", RECORDS).split()
        intro = adds[0].decode() if adds else head_sha
        first = checked(root, intro)  # validate() makes row 1 the 0.1.0 baseline
        if len(first) != 1:
            raise Refused("first introduction must contain only the 0.1.0 baseline")
        if intro != head_sha:
            later = check_base(root, intro, head_sha)
            return dict(later, base=base_sha, introduced=intro,
                        new_versions=[first[0]["version"], *later["new_versions"]])
        new = current
    def pointer(sha):
        present = git(root, "ls-tree", "--name-only", sha, "--", PHASE_POINTER).strip()
        value = read(root, PHASE_POINTER, sha).decode("utf-8").strip() if present else ""
        if value in ("", "(none)", "none", "—"):
            return None
        if not PHASE.fullmatch(value):
            raise Refused("Perry phase pointer must be a single numbered slug or empty marker")
        return value
    start_phase = None
    if PHASE_POINTER in paths:
        prior, after = pointer(base_sha), pointer(head_sha)
        if after and after != prior:
            start_phase = after
    changed = [p for p in paths if product(p)]
    if start_phase:
        changed.append(PHASE_POINTER)
    if changed and not new:
        raise Refused("product changes require a new release record: " + ", ".join(changed))
    if not changed and any(r["kind"] in ("patch", "phase", "baseline") for r in new):
        raise Refused("PMO-only or synchronization changes do not allocate versions")
    if start_phase and exists and not any(r["kind"] == "phase" and r["phase"] == start_phase
                                         for r in new):
        raise Refused("Perry's new phase pointer requires its matching phase release record")
    return {"base": base_sha, "head": head_sha, "product_paths": changed,
            "new_versions": [r["version"] for r in new]}


def check_tag(rows: list[dict], tag: str) -> None:
    if tag != "v" + rows[-1]["version"]:
        raise Refused("tag must exactly match VERSION: v" + rows[-1]["version"])


def prepare(root: Path, ref: str, tag: str) -> str:
    sha = commit(root, ref)
    rows = checked(root, sha)
    check_tag(rows, tag)
    if commit(root, "HEAD") != sha or git(root, "status", "--porcelain").strip():
        raise Refused("prepare requires a clean checkout of the exact version commit")
    if git(root, "show-ref", "--verify", "refs/tags/" + tag, missing=True):
        raise Refused("tag already exists; it must not be reused or moved")
    return notes(rows[-1])


def main(argv=None) -> int:
    ap = argparse.ArgumentParser(description=__doc__)
    ap.add_argument("--root", type=Path, default=ROOT)
    sub = ap.add_subparsers(dest="command", required=True)
    for name in ("show", "check", "notes"):
        p = sub.add_parser(name)
        p.add_argument("--ref", help="read an immutable Git commit/tag instead of working files")
        if name == "show":
            p.add_argument("--json", action="store_true")
        if name == "notes":
            p.add_argument("--version")
        if name == "check":
            p.add_argument("--base", help="compare explicit ancestor to --ref (default HEAD)")
            p.add_argument("--tag")
    p = sub.add_parser("render")
    p.add_argument("--repair", action="store_true", required=True)
    for kind in ("patch", "phase", "major"):
        p = sub.add_parser(kind)
        for flag in ("expected-version", "date", "phase", "delivery", "integrator",
                     "notes-file", "upgrade-file", "breaking-file"):
            p.add_argument("--" + flag, required=True)
        p.add_argument("--task", required=kind == "patch")
        if kind == "major":
            p.add_argument("--decision", required=True)
    p = sub.add_parser("prepare")
    p.add_argument("--ref", required=True)
    p.add_argument("--tag", required=True)
    args = ap.parse_args(argv)
    root = args.root.resolve()
    try:
        if args.command in ("patch", "phase", "major"):
            row = allocate(root, args.command, expected=args.expected_version,
                           date=args.date, phase=args.phase, task=args.task,
                           delivery=args.delivery, integrator=args.integrator,
                           changes=Path(args.notes_file).read_text(),
                           upgrade=Path(args.upgrade_file).read_text(),
                           breaking=Path(args.breaking_file).read_text(),
                           decision=getattr(args, "decision", None))
            print(row["version"])
        elif args.command == "render":
            with locked(root):
                print(render(root)[-1]["version"])
        elif args.command == "prepare":
            print(prepare(root, args.ref, args.tag), end="")
        else:
            ref = args.ref or ("HEAD" if args.command == "check" and args.base else None)
            rows = checked(root, ref)
            if args.command == "check":
                if args.tag:
                    check_tag(rows, args.tag)
                result = check_base(root, args.base, ref) if args.base else {"version": rows[-1]["version"]}
                print(json.dumps(result, sort_keys=True))
            elif args.command == "show":
                print(json.dumps(rows[-1], ensure_ascii=False, sort_keys=True) if args.json
                      else rows[-1]["version"])
            else:
                selected = [r for r in rows if args.version is None or r["version"] == args.version]
                if not selected:
                    raise Refused("unknown release version")
                print(notes(selected[-1]), end="")
        return 0
    except (Refused, OSError) as exc:
        print("release: " + str(exc), file=sys.stderr)
        return 1


if __name__ == "__main__":
    raise SystemExit(main())

"""Bounded release consumer for tools/update-check.sh (stdlib only).

Product metadata, not project state. Never falls back from a failed release
check to main, and never resets a checkout. The shell owns host lookup/flags.
"""
from __future__ import annotations

import argparse
import fcntl
import json
import os
from pathlib import Path
import re
import subprocess
import sys
import time
import urllib.error
import urllib.request

API_URL = "https://api.github.com/repos/ranjiao/Perry/releases/latest"
VERSION = re.compile(r"(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\n", re.ASCII)
GIT_TIMEOUT = 30
MAX_RESPONSE = 1024 * 1024


class Refused(Exception):
    pass


def version(text: str) -> tuple[int, int, int]:
    match = VERSION.fullmatch(text)
    if not match:
        raise Refused("VERSION must be exactly ASCII X.Y.Z followed by a newline")
    return tuple(map(int, match.groups()))


def official_origin(origin: str) -> bool:
    return origin in {
        "git@github.com:ranjiao/Perry.git", "git@github.com:ranjiao/Perry",
        "https://github.com/ranjiao/Perry.git", "https://github.com/ranjiao/Perry",
        "ssh://git@github.com/ranjiao/Perry.git", "ssh://git@github.com/ranjiao/Perry",
    }


class NoRedirect(urllib.request.HTTPRedirectHandler):
    def redirect_request(self, *args, **kwargs):
        raise Refused("release API redirected; checkout unchanged")


def latest_release() -> dict | None:
    request = urllib.request.Request(API_URL, headers={
        "Accept": "application/vnd.github+json", "User-Agent": "Perry-update-check",
        "X-GitHub-Api-Version": "2022-11-28",
    })
    deadline = time.monotonic() + 10
    try:
        with urllib.request.build_opener(NoRedirect).open(request, timeout=5) as response:
            chunks, size = [], 0
            while True:
                if time.monotonic() >= deadline:
                    raise Refused("release API exceeded its time limit")
                chunk = response.read1(min(8192, MAX_RESPONSE + 1 - size))
                if not chunk:
                    break
                chunks.append(chunk)
                size += len(chunk)
                if size > MAX_RESPONSE:
                    raise Refused("release API response exceeds 1 MiB")
        data = json.loads(b"".join(chunks))
    except urllib.error.HTTPError as exc:
        if exc.code == 404:
            return None
        raise Refused(f"release API returned HTTP {exc.code}; checkout unchanged") from None
    except (OSError, ValueError, urllib.error.URLError):
        # Do not echo URLs, credentials, proxy details or response bodies.
        raise Refused("release API unavailable or invalid; checkout unchanged") from None
    return data


def release_metadata(data: dict) -> tuple[str, tuple[int, int, int], str]:
    if not isinstance(data, dict) or data.get("draft") is not False or data.get("prerelease") is not False:
        raise Refused("latest release is not a published stable release")
    tag = data.get("tag_name")
    if not isinstance(tag, str) or not tag.startswith("v"):
        raise Refused("release tag must be vX.Y.Z")
    value = version(tag[1:] + "\n")
    notes = data.get("body")
    if not isinstance(notes, str) or not notes.strip():
        raise Refused("release changes are missing; checkout unchanged")
    return tag, value, notes


def git(source: Path, *args: str, allowed=(0,)) -> subprocess.CompletedProcess:
    env = dict(os.environ, GIT_TERMINAL_PROMPT="0")
    env.setdefault("GIT_SSH_COMMAND", "ssh -oBatchMode=yes -oConnectTimeout=5")
    try:
        out = subprocess.run(["git", "-C", str(source), "-c", "credential.interactive=never",
                              *args], capture_output=True, env=env,
                             timeout=GIT_TIMEOUT)
    except subprocess.TimeoutExpired:
        raise Refused("git operation exceeded 30 seconds; no forced update was attempted") from None
    except OSError:
        raise Refused("git could not run; checkout unchanged") from None
    # Preserve CRLF bytes: text=True would silently normalize invalid VERSION.
    out.stdout = out.stdout.decode("utf-8", errors="replace")
    out.stderr = out.stderr.decode("utf-8", errors="replace")
    if out.returncode not in allowed:
        raise Refused(f"git {args[0]} failed; no forced update was attempted")
    return out


def ref(source: Path, name: str) -> str | None:
    out = git(source, "rev-parse", "--verify", name, allowed=(0, 128))
    return out.stdout.strip() if out.returncode == 0 else None


def dirty(source: Path) -> bool:
    return bool(git(source, "status", "--porcelain").stdout)


def origin(source: Path) -> str:
    return git(source, "remote", "get-url", "origin").stdout.strip()


def verified_tag(source: Path, tag: str) -> str:
    # Fetch only this exact tag, not main or implicitly-followed tags. Git's
    # target_commitish API field can be a mutable branch and is never used.
    if not official_origin(origin(source)):
        raise Refused("release updates require the official ranjiao/Perry origin")
    git(source, "fetch", "--quiet", "--no-tags", "origin", "refs/tags/" + tag)
    commit = ref(source, "FETCH_HEAD^{commit}")
    if not commit:
        raise Refused("release tag does not resolve to a commit")
    expected = tag[1:] + "\n"
    text = git(source, "show", commit + ":VERSION").stdout
    version(text)
    if text != expected:
        raise Refused("release tag and target-tree VERSION disagree; checkout unchanged")
    for name in ("refs/tags/" + tag, "refs/perry/releases/" + tag):
        known = ref(source, name + "^{commit}")
        if known and known != commit:
            raise Refused("release tag moved or conflicts with a known tag; checkout unchanged")
    git(source, "update-ref", "refs/perry/releases/" + tag, commit)
    return commit


def developer(source: Path, reasons: list[str], log) -> None:
    git(source, "fetch", "--quiet", "--no-tags", "origin", "main:refs/remotes/origin/main")
    behind = git(source, "rev-list", "--count", "HEAD..refs/remotes/origin/main").stdout.strip()
    log(f"Perry dev mode ({', '.join(reasons)}): {behind} new commit(s) on origin/main; report only.")
    if "symlink" in reasons:
        log("To explicitly use verified releases: perry-update-check --force --channel release")


def known_release_tag(source: Path) -> str | None:
    """Local tag/cache association is a candidate, never remote verification."""
    names = git(source, "for-each-ref", "--format=%(refname)", "--points-at=HEAD",
                "refs/tags", "refs/perry/releases").stdout.splitlines()
    for name in names:
        tag = name.rsplit("/", 1)[-1]
        if tag.startswith("v") and VERSION.fullmatch(tag[1:] + "\n"):
            return tag
    return None


def check(source: Path, *, symlink=False, channel="auto", quiet=False, force=False) -> None:
    def log(text):
        if not quiet:
            print(text)

    head = ref(source, "HEAD")
    if not head:
        raise Refused("checkout has no HEAD")
    branch = git(source, "symbolic-ref", "--quiet", "--short", "HEAD", allowed=(0, 1)).stdout.strip()
    reasons = []
    if symlink and channel != "release":
        reasons.append("symlink")
    if dirty(source):
        reasons.append("dirty")
    if branch and branch != "main":
        reasons.append("on " + branch)
    if reasons:
        developer(source, reasons, log)
        (source / ".update-check").touch()
        return
    if not official_origin(origin(source)):
        raise Refused("release updates require the official ranjiao/Perry origin")
    known_tag = known_release_tag(source)
    if not branch:
        # Classify detached local work from the commit's ref association, not
        # a self-declared VERSION whose corresponding remote tag may not exist.
        if not known_tag:
            developer(source, ["detached local work"], log)
            return
        if verified_tag(source, known_tag) != head:
            raise Refused("detached checkout is not its verified release tag")
    current_text = git(source, "show", "HEAD:VERSION", allowed=(0, 128)).stdout
    current = version(current_text) if current_text else None
    data = latest_release()
    if data is None:
        log("Perry: no published stable GitHub Release; checkout unchanged (no main fallback).")
        (source / ".update-check").touch()
        return
    tag, available, notes = release_metadata(data)
    log(f"Perry current: {current_text.strip() or 'unversioned'}; available: {tag[1:]}")
    log("Release changes:\n" + notes)
    if known_tag and current and available < current:
        raise Refused("available release is older; refusing a downgrade")
    target = verified_tag(source, tag)
    if current == available and head != target:
        developer(source, ["local commits or unreleased work"], log)
        return
    if git(source, "merge-base", "--is-ancestor", head, target, allowed=(0, 1)).returncode:
        common = git(source, "merge-base", head, target, allowed=(0, 1)).stdout.strip()
        if not common:
            raise Refused("release has unrelated history; checkout unchanged")
        developer(source, ["local commits"], log)
        return
    if current and available < current:
        raise Refused("available release is older; refusing a downgrade")
    if target != head:
        # Recheck immediately before fast-forward. Never stash/reset/force;
        # Git also refuses an interfering concurrent edit when applying it.
        now_branch = git(source, "symbolic-ref", "--quiet", "--short", "HEAD", allowed=(0, 1)).stdout.strip()
        if dirty(source) or ref(source, "HEAD") != head or now_branch != branch or not official_origin(origin(source)):
            raise Refused("checkout changed during the check; retry after reviewing local work")
        git(source, "-c", "merge.autoStash=false", "merge", "--ff-only", "--no-edit", target)
        if ref(source, "HEAD") != target:
            raise Refused("update did not reach the verified release commit")
        log(f"Perry updated to {tag} ({target[:12]}); subsequent release checks remain enabled.")
    elif force:
        log(f"Perry is already at verified release {tag}.")
    (source / ".update-check").touch()


def main(argv=None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--source", required=True, type=Path)
    parser.add_argument("--symlink", action="store_true")
    parser.add_argument("--channel", choices=("auto", "release"), default="auto")
    parser.add_argument("--quiet", action="store_true")
    parser.add_argument("--force", action="store_true")
    parser.add_argument("--strict", action="store_true")
    args = parser.parse_args(argv)
    try:
        gitdir = Path(git(args.source, "rev-parse", "--absolute-git-dir").stdout.strip())
        with (gitdir / "perry-update.lock").open("a") as lock:
            try:
                fcntl.flock(lock, fcntl.LOCK_EX | fcntl.LOCK_NB)
            except BlockingIOError:
                raise Refused("another update check is already running") from None
            check(args.source, symlink=args.symlink, channel=args.channel,
                  quiet=args.quiet, force=args.force)
        return 0
    except (Refused, OSError) as exc:
        message = str(exc) if isinstance(exc, Refused) else "local update operation failed"
        print("perry-update-check: " + message, file=sys.stderr)
        return 1 if args.strict else 0


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
"""
kb-lint — the verification loop for a knowledge base.

A knowledge base has no test suite, so "done" has no natural definition and an
agent stops when the work *looks* finished. This script is the substitute: a
check the agent can run that returns pass or fail, so the loop closes without a
human in it.

It enforces the four properties that a vault actually degrades on. Every one of
them is a thing three sessions that never read the index will get wrong:

  1. link integrity  — every [[wikilink]] and relative .md link resolves
  2. reachability    — every page is reachable from index.md, directly or not
  3. provenance      — every synthesized page cites at least one raw/ source
  4. distinctness    — no two pages claim the same title

Usage:
  bin/kb-lint [--root DIR] [--json] [--quiet]

Exit code is 1 when anything fails, so it works as a gate:
  bin/kb-lint && echo "safe to stop"

Layout it assumes (edit CONFIG below if yours differs):
  index.md    the catalog every session reads first
  wiki/       agent-written pages
  raw/        immutable source material, never edited after it lands
  log.md      append-only activity record

Python 3 standard library only. Read-only.
"""

from __future__ import annotations

import json
import re
import sys
from pathlib import Path

CONFIG = {
    "index": "index.md",
    "pages_dir": "wiki",
    "raw_dir": "raw",
    "require_provenance": True,   # set False for a vault of original writing
}

WIKILINK = re.compile(r"\[\[([^\]|#]+)")
MD_LINK = re.compile(r"\[[^\]]*\]\(([^)\s]+)\)")
H1 = re.compile(r"^#\s+(.+?)\s*$", re.M)


def read(p: Path) -> str:
    try:
        return p.read_text(encoding="utf-8", errors="replace")
    except OSError:
        return ""


def targets(text: str) -> set[str]:
    """Link targets in a page, wiki-style and markdown-style alike."""
    out = {m.group(1).strip() for m in WIKILINK.finditer(text)}
    for m in MD_LINK.finditer(text):
        t = m.group(1).split("#", 1)[0].strip()
        if t and not t.startswith(("http://", "https://", "mailto:")):
            out.add(t)
    return {t for t in out if t}


def resolve(target: str, source: Path, root: Path, pages: dict[str, Path]) -> Path | None:
    """A wikilink resolves by page name; a markdown link resolves by path."""
    stem = target[:-3] if target.endswith(".md") else target
    if stem.lower() in pages:
        return pages[stem.lower()]
    for cand in ((source.parent / target), (root / target)):
        if cand.suffix != ".md":
            cand = cand.with_suffix(".md")
        if cand.is_file():
            return cand.resolve()
    return None


def main(argv: list[str]) -> int:
    root = Path(".").resolve()
    as_json = quiet = False
    i = 0
    while i < len(argv):
        if argv[i] == "--root" and i + 1 < len(argv):
            root = Path(argv[i + 1]).expanduser().resolve()
            i += 1
        elif argv[i] == "--json":
            as_json = True
        elif argv[i] in ("--quiet", "-q"):
            quiet = True
        elif argv[i] in ("--help", "-h"):
            print(__doc__.strip())
            return 0
        i += 1

    index = root / CONFIG["index"]
    pages_dir = root / CONFIG["pages_dir"]
    raw_dir = root / CONFIG["raw_dir"]
    findings: list[dict] = []

    def add(kind, path, detail):
        findings.append({"kind": kind, "path": path, "detail": detail})

    if not index.is_file():
        add("no-index", CONFIG["index"],
            "the catalog every session reads first is missing — without it, "
            "sessions rediscover the vault instead of using it")
        if as_json:
            print(json.dumps({"ok": False, "findings": findings}, indent=2))
        elif not quiet:
            print(f"✗ {CONFIG['index']} not found")
        return 1

    page_files = sorted(pages_dir.rglob("*.md")) if pages_dir.is_dir() else []
    pages = {p.stem.lower(): p.resolve() for p in page_files}

    # 1 · link integrity
    for p in [index, *page_files]:
        text = read(p)
        for t in targets(text):
            if t.startswith(CONFIG["raw_dir"] + "/") and (root / t).exists():
                continue
            if resolve(t, p, root, pages) is None:
                add("broken-link", str(p.relative_to(root)),
                    f"'{t}' does not resolve to a page")

    # 2 · reachability — walk out from the index, transitively
    seen: set[Path] = set()
    queue = [index]
    while queue:
        cur = queue.pop()
        if cur in seen:
            continue
        seen.add(cur)
        for t in targets(read(cur)):
            hit = resolve(t, cur, root, pages)
            if hit and hit not in seen:
                queue.append(hit)
    for p in page_files:
        if p.resolve() not in seen:
            add("unreachable", str(p.relative_to(root)),
                "not reachable from the index — an unlinked page is where the "
                "next duplicate gets written")

    # 3 · provenance
    if CONFIG["require_provenance"] and raw_dir.is_dir():
        for p in page_files:
            text = read(p)
            cites = (CONFIG["raw_dir"] + "/") in text or re.search(
                r"^\s*(source|sources|from)\s*:", text, re.I | re.M)
            if not cites:
                add("no-provenance", str(p.relative_to(root)),
                    f"cites no {CONFIG['raw_dir']}/ source — a claim nobody can "
                    "re-verify is not knowledge, it is a rumour with a filename")

    # 4 · distinctness
    by_title: dict[str, list[str]] = {}
    for p in page_files:
        m = H1.search(read(p))
        if m:
            key = re.sub(r"[^a-z0-9]+", " ", m.group(1).lower()).strip()
            by_title.setdefault(key, []).append(str(p.relative_to(root)))
    for title, paths in by_title.items():
        if len(paths) > 1:
            add("duplicate-title", paths[0],
                f"'{title}' is also the title of: {', '.join(paths[1:])}")

    ok = not findings
    if as_json:
        print(json.dumps({
            "ok": ok,
            "pages": len(page_files),
            "reachable": len([p for p in page_files if p.resolve() in seen]),
            "findings": findings,
        }, indent=2))
    elif not quiet:
        if ok:
            print(f"✓ kb-lint clean — {len(page_files)} pages, all reachable, "
                  "all cited, all distinct")
        else:
            print(f"✗ kb-lint — {len(findings)} finding(s) across "
                  f"{len(page_files)} pages\n")
            for f in findings:
                print(f"  [{f['kind']}] {f['path']}")
                print(f"      {f['detail']}")
    return 0 if ok else 1


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))

#!/usr/bin/env python3
"""
deliverable-lint — the verification loop for work that does not compile.

Ops, content, and process projects have no test suite, so the only stop signal
an agent has is "it looks finished". This script replaces that with something
that returns pass or fail, built out of the three gates that actually work when
nothing can be executed:

  1. structure   — the deliverable has every section its kind requires
  2. completion  — no unresolved {{placeholders}} and no TODO markers left
  3. sign-off    — anything outward-facing carries a human name and a date

Gate 3 is the one that matters. An agent may draft, revise, and check its own
work; it may not decide that something is ready to leave the building. That
call is a person's, and this script is where the requirement is enforced rather
than hoped for.

Usage:
  bin/deliverable-lint [PATH ...] [--kind KIND] [--json] [--quiet]

  PATH      files or directories to check (default: deliverables/)
  --kind    force a kind instead of inferring from the parent directory

Exit code is 1 when anything fails:
  bin/deliverable-lint && echo "safe to publish"

Python 3 standard library only. Read-only.
"""

from __future__ import annotations

import json
import re
import sys
from pathlib import Path

# Edit this to match the kinds of work this project produces. The key is the
# directory name; anything not listed falls back to "default".
KINDS = {
    "default": {
        "sections": ["Summary", "Detail"],
        "needs_signoff": False,
    },
    "deliverables": {
        "sections": ["Summary", "Detail", "Sources"],
        "needs_signoff": True,
    },
    "incidents": {
        "sections": ["Impact", "Timeline", "Root cause", "Follow-ups"],
        "needs_signoff": True,
    },
    "runbooks": {
        "sections": ["When to use", "Steps", "Verification", "Rollback"],
        "needs_signoff": False,
    },
}

DEFAULT_TARGETS = ["deliverables", "incidents", "runbooks"]

HEADING = re.compile(r"^#{1,6}\s+(.+?)\s*$", re.M)
PLACEHOLDER = re.compile(r"\{\{[^}]{0,80}\}\}")
TODO = re.compile(r"\b(TODO|TBD|FIXME|XXX)\b")
SIGNOFF = re.compile(
    r"^\s*(?:[-*]\s*)?(?:\*\*)?sign(?:ed)?[- ]off(?:\*\*)?\s*:\s*(.+)$",
    re.I | re.M,
)
DATE = re.compile(r"\d{4}-\d{2}-\d{2}")


def norm(s: str) -> str:
    return re.sub(r"[^a-z0-9]+", " ", s.lower()).strip()


def check(path: Path, root: Path, kind: str) -> list[dict]:
    spec = KINDS.get(kind, KINDS["default"])
    try:
        text = path.read_text(encoding="utf-8", errors="replace")
    except OSError as exc:
        return [{"kind": "unreadable", "path": str(path), "detail": str(exc)}]

    rel = str(path.relative_to(root)) if path.is_relative_to(root) else str(path)
    out = []
    present = {norm(m.group(1)) for m in HEADING.finditer(text)}

    for want in spec["sections"]:
        if norm(want) not in present:
            out.append({
                "kind": "missing-section", "path": rel,
                "detail": f"required section '{want}' is absent "
                          f"(kind: {kind})",
            })

    holes = PLACEHOLDER.findall(text)
    if holes:
        out.append({
            "kind": "unfilled", "path": rel,
            "detail": f"{len(holes)} unresolved placeholder(s): "
                      f"{', '.join(sorted(set(holes))[:4])}",
        })

    marks = TODO.findall(text)
    if marks:
        out.append({
            "kind": "open-marker", "path": rel,
            "detail": f"{len(marks)} unresolved marker(s) "
                      f"({', '.join(sorted(set(marks)))}) — finished work has none",
        })

    if spec["needs_signoff"]:
        m = SIGNOFF.search(text)
        if not m:
            out.append({
                "kind": "no-signoff", "path": rel,
                "detail": "no 'Sign-off:' line. Outward-facing work needs a "
                          "person's name against it — an agent may draft and "
                          "revise, but may not decide this is ready to send",
            })
        elif not DATE.search(m.group(1)):
            out.append({
                "kind": "signoff-undated", "path": rel,
                "detail": f"sign-off '{m.group(1).strip()[:50]}' carries no "
                          "YYYY-MM-DD date, so it cannot be tied to a version",
            })
    return out


def main(argv: list[str]) -> int:
    paths, forced_kind, as_json, quiet = [], None, False, False
    i = 0
    while i < len(argv):
        a = argv[i]
        if a in ("--help", "-h"):
            print(__doc__.strip())
            return 0
        if a == "--kind" and i + 1 < len(argv):
            forced_kind = argv[i + 1]
            i += 1
        elif a == "--json":
            as_json = True
        elif a in ("--quiet", "-q"):
            quiet = True
        elif not a.startswith("-"):
            paths.append(a)
        i += 1

    root = Path(".").resolve()
    if not paths:
        paths = [p for p in DEFAULT_TARGETS if (root / p).is_dir()]
        if not paths:
            if not quiet:
                print("deliverable-lint: nothing to check "
                      f"(looked for {', '.join(DEFAULT_TARGETS)})")
            return 0

    files: list[tuple[Path, str]] = []
    for raw in paths:
        p = (root / raw).resolve() if not Path(raw).is_absolute() else Path(raw)
        if p.is_dir():
            for f in sorted(p.rglob("*.md")):
                if f.name.upper() in ("README.MD", "INDEX.MD"):
                    continue
                files.append((f, forced_kind or p.name))
        elif p.is_file():
            files.append((p, forced_kind or p.parent.name))

    findings: list[dict] = []
    for f, kind in files:
        findings.extend(check(f, root, kind))

    ok = not findings
    if as_json:
        print(json.dumps(
            {"ok": ok, "checked": len(files), "findings": findings}, indent=2))
    elif not quiet:
        if ok:
            print(f"✓ deliverable-lint clean — {len(files)} document(s)")
        else:
            print(f"✗ deliverable-lint — {len(findings)} finding(s) across "
                  f"{len(files)} document(s)\n")
            for x in findings:
                print(f"  [{x['kind']}] {x['path']}")
                print(f"      {x['detail']}")
    return 0 if ok else 1


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))

"""Validate host-agent interpretation against a specific fact snapshot."""
import hashlib
import json
import re


def attach(data, proposal):
    if not isinstance(proposal, dict) or type(proposal.get('version')) is not int or proposal.get('version') != 1:
        raise ValueError('analysis version must be 1')
    if proposal.get('snapshot') != data['snapshot']:
        raise ValueError('stale analysis: generate interpretation for the current snapshot')
    if proposal.get('producer') != 'host-agent':
        raise ValueError('analysis producer must be host-agent')
    files = {f['id']: f for f in data['files']}
    symbols = {s['id']: s for s in data['symbols']}
    units = {**{f: {'id': f, 'file': f, 'line': 1} for f in files},
             **{s: dict(item, file=item['file']) for s, item in symbols.items()}}
    owners, nodes, issues = {}, [], []
    seen = set()

    def visit(items, parent=''):
        if not isinstance(items, list) or not items:
            raise ValueError('analysis components must be a nonempty array')
        for item in items:
            if not isinstance(item, dict):
                raise ValueError('component must be an object')
            slug = item.get('id', '')
            if not isinstance(slug, str) or not re.fullmatch('[a-z][a-z0-9_-]*', slug):
                raise ValueError('component id must be a lowercase slug')
            key = f'{parent}/{slug}' if parent else slug
            if key in seen or key == 'unmapped':
                raise ValueError('duplicate or reserved component: ' + key)
            seen.add(key)
            for field in ('label', 'description', 'uncertainty'):
                if not isinstance(item.get(field), str) or not item[field].strip():
                    raise ValueError('component needs label, description and uncertainty: ' + key)
            layer = item.get('layer', 0)
            if type(layer) is not int or not 0 <= layer <= 10:
                raise ValueError('invalid layer: ' + key)
            evidence = item.get('evidence', [])
            if not isinstance(evidence, list) or any(not isinstance(e, str) or e not in data['evidence'] for e in evidence):
                raise ValueError('invalid component evidence: ' + key)
            node = {k: item[k] for k in ('label', 'description', 'uncertainty')}
            node.update(id=key, parent=parent, layer=layer, evidence=evidence, files=[], symbols=[])
            nodes.append(node)
            if 'children' in item:
                if 'members' in item:
                    raise ValueError('branch cannot declare members')
                visit(item['children'], key)
            else:
                members = item.get('members')
                if not isinstance(members, list) or not members or not evidence:
                    raise ValueError('leaf needs explicit members and evidence: ' + key)
                selected = set()
                for member in members:
                    module_only = isinstance(member, str) and member.startswith('module:')
                    member = member[7:] if module_only else member
                    if not isinstance(member, str) or member not in units:
                        raise ValueError('unknown member: ' + str(member))
                    selected.add(member)
                    if member in files and not module_only:
                        selected.update(s for s, entry in symbols.items() if entry['file'] == member)
                member_files = {units[m]['file'] for m in selected}
                if any(data['evidence'][e]['source'] not in member_files for e in evidence):
                    raise ValueError('leaf evidence must belong to its members: ' + key)
                for member in sorted(selected):
                    if member in owners:
                        raise ValueError('overlapping member: ' + member)
                    owners[member] = key
    visit(proposal.get('components'))
    unassigned = sorted(set(units) - set(owners))
    if unassigned:
        nodes.append({'id': 'unmapped', 'parent': '', 'label': '尚未解释的代码',
                      'description': '需要分析或存在覆盖缺口', 'uncertainty': '没有职责判断',
                      'layer': 0, 'evidence': [], 'files': [], 'symbols': []})
        for key in unassigned:
            owners[key] = 'unmapped'
        issues.append({'path': 'unmapped', 'kind': 'unassigned', 'candidates': unassigned})
    by_id = {n['id']: n for n in nodes}
    for unit, owner in owners.items():
        key = owner
        while key:
            node = by_id[key]
            node['files'].append(units[unit]['file'])
            if unit in symbols:
                node['symbols'].append(unit)
            key = node['parent']
    for n in nodes:
        n['files'] = sorted(set(n['files']))
        n['symbols'] = sorted(set(n['symbols']))

    def unit_at(path, line):
        candidates = [s for s in symbols.values() if s['file'] == path and s['line'] <= line <= s['end_line']]
        return min(candidates, key=lambda s: s['end_line']-s['line'])['id'] if candidates else path

    edges = {}
    def edge(a, b, evidence):
        source, target = owners[a], owners[b]
        if source != target:
            edges.setdefault((source, target), set()).add(evidence)
    for item in data['imports']:
        for target in item['targets'] if item['resolution'] == 'internal' else []:
            edge(unit_at(item['source'], item['line']), target, f"import:{item['id']}")
    for call in data['calls']:
        if call['target_symbol']:
            edge(call['owner'] or call['source'], call['target_symbol'], call['id'])
    data['architecture'] = {
        'version': 2, 'title': proposal.get('title', '代码职责现状'),
        'basis': '宿主 agent 基于当前静态证据生成；职责是推断，不是目标架构或合规认证。',
        'snapshot': data['snapshot'], 'producer': 'host-agent',
        'model_sha256': hashlib.sha256(json.dumps(proposal, sort_keys=True).encode()).hexdigest(),
        'nodes': nodes, 'owners': owners, 'units': list(units.values()), 'issues': issues,
        'scope_aliases': {},
        'edges': [{'source': a, 'target': b, 'imports': sorted(e)} for (a,b),e in sorted(edges.items())]}
    return data


def changes(data, previous):
    if not isinstance(previous, dict) or not isinstance(previous.get('files'), list) or not isinstance(previous.get('snapshot'), str):
        raise ValueError('previous must be a fact/report snapshot')
    if previous.get('root') != data['root']:
        raise ValueError('previous snapshot belongs to a different project root')
    old = {f['id']: f for f in previous['files']}
    new = {f['id']: f for f in data['files']}
    current_nodes = {n['id']: n for n in data.get('architecture', {}).get('nodes', [])}
    old_nodes = {n['id']: n for n in previous.get('architecture', {}).get('nodes', [])}
    return {'base_snapshot': previous['snapshot'], 'snapshot': data['snapshot'],
            'added': sorted(new.keys()-old.keys()), 'removed': sorted(old.keys()-new.keys()),
            'changed': sorted(f for f in new.keys() & old.keys() if new[f]['sha256'] != old[f]['sha256']),
            'components_added': sorted(current_nodes.keys()-old_nodes.keys()),
            'components_removed': sorted(old_nodes.keys()-current_nodes.keys()),
            'components_changed': sorted(k for k in current_nodes.keys() & old_nodes.keys()
                                         if current_nodes[k] != old_nodes[k]),
            'note': 'Component IDs are agent-supplied; renames are additions/removals, not proven semantic moves.'}

"""Evaluate explicit constraints derived by an agent from cited target text.

This validates provenance and checks code; it cannot certify the interpretation
of prose. No target file is ever changed and no Check: command is executed.
"""
import fnmatch
import hashlib
from pathlib import Path


def compare(data, ruleset):
    if not isinstance(ruleset, dict) or type(ruleset.get('version')) is not int or ruleset.get('version') != 1:
        raise ValueError('rules version must be 1')
    documents, rules = ruleset.get('documents'), ruleset.get('rules')
    if not isinstance(documents, list) or not documents or not isinstance(rules, list) or not rules:
        raise ValueError('rules need target documents and nonempty rules')
    root = Path(data['root']).resolve()
    texts, targets = {}, []
    for doc in documents:
        if not isinstance(doc, dict) or not isinstance(doc.get('path'), str):
            raise ValueError('invalid target document')
        path = (root / doc['path']).resolve(strict=True)
        if not path.is_relative_to(root) or Path(doc['path']).is_absolute():
            raise ValueError('target document must be inside project')
        raw = path.read_bytes()
        digest = hashlib.sha256(raw).hexdigest()
        if digest != doc.get('sha256'):
            raise ValueError('stale target rules: ' + doc['path'])
        text = raw.decode('utf-8')
        texts[doc['path']] = text.splitlines()
        targets.append({'path': doc['path'], 'sha256': digest, 'source': text})

    def patterns(rule, key):
        value = rule.get(key)
        if not isinstance(value, list) or not value or any(not isinstance(p,str) or not p for p in value):
            raise ValueError('nonempty pattern array required: ' + key)
        return value

    def matches(value, pats):
        return any(fnmatch.fnmatchcase(value, p) for p in pats)

    results, ids = [], set()
    for rule in rules:
        if not isinstance(rule, dict) or not isinstance(rule.get('id'), str) or not rule['id'] or rule['id'] in ids:
            raise ValueError('rule id missing or duplicate')
        ids.add(rule['id'])
        ref = rule.get('source', {})
        if not isinstance(ref, dict) or not isinstance(ref.get('path'), str):
            raise ValueError('invalid rule source')
        lines = texts.get(ref.get('path'))
        start, end = ref.get('line'), ref.get('end_line')
        if (lines is None or type(start) is not int or type(end) is not int or
                not 1 <= start <= end <= len(lines) or
                '\n'.join(lines[start-1:end]) != ref.get('quote')):
            raise ValueError('rule needs exact target quote and line range: ' + rule['id'])
        selected = [f for f in data['files'] if matches(f['id'], patterns(rule, 'scope'))]
        paths = {f['id'] for f in selected}
        violations, unknown = [], []
        for skipped in data['scope']['skipped_paths']:
            if matches(skipped.rstrip('/') + ('/__excluded__' if skipped.endswith('/') else ''), rule['scope']) or any(p.split('*')[0].startswith(skipped) for p in rule['scope']):
                unknown.append({'reason': 'excluded path overlaps rule scope: ' + skipped, 'evidence': []})
        if not selected:
            unknown.append({'reason': 'scope has no scanned files', 'evidence': []})
        bad = [f['id'] for f in selected if f['status'] != 'parsed']
        if bad:
            unknown.append({'reason': 'unparsed files: ' + ', '.join(bad), 'evidence': []})
        for issue in data['issues']:
            if issue['path'] in paths and issue['kind'] in ('symbol-depth-limit', 'call-depth-limit'):
                unknown.append({'reason': issue['kind'] + ': ' + issue['path'], 'evidence': []})
        kind = rule.get('kind')
        if kind == 'forbid-import':
            forbidden = patterns(rule, 'forbidden_paths')
            for item in data['imports']:
                if item['source'] not in paths:
                    continue
                key = f"import:{item['id']}"
                if item['resolution'] == 'internal' and any(matches(p, forbidden) for p in item['targets']):
                    violations.append({'reason': 'forbidden import target', 'evidence': [key]})
                elif item['resolution'] in ('unresolved', 'ambiguous'):
                    unknown.append({'reason': 'import target is not resolved', 'evidence': [key]})
            for issue in data['issues']:
                if issue['path'] in paths and issue['kind'] == 'dynamic-import-context':
                    unknown.append({'reason': 'dynamic import context: ' + issue['path'], 'evidence': []})
        elif kind == 'forbid-call':
            forbidden = patterns(rule, 'forbidden_calls')
            origin = rule.get('origin', 'any')
            if origin not in ('any', 'stdlib', 'internal'):
                raise ValueError('invalid call origin')
            for item in data['calls']:
                if item['source'] not in paths:
                    continue
                if (item['resolution'] == 'lexical-reference' and item['canonical'] and
                        (origin == 'any' or item['origin'] == origin) and matches(item['canonical'], forbidden)):
                    violations.append({'reason': 'forbidden lexical call reference (not execution proof)',
                                       'evidence': [item['id']]})
                elif item['resolution'] == 'unknown':
                    unknown.append({'reason': 'call target is not resolved', 'evidence': [item['id']]})
        else:
            raise ValueError('unsupported rule kind: ' + str(kind))
        results.append({'id': rule['id'], 'kind': kind, 'source': ref,
                        'scope': rule['scope'], 'constraint': forbidden,
                        'status': 'violation' if violations else 'unknown' if unknown else 'no_observed_violation',
                        'checked_files': len(selected), 'violations': violations, 'unknown': unknown})
    data['comparison'] = {'version': 1, 'snapshot': data['snapshot'], 'targets': targets,
                          'interpretation': 'Agent-derived rules; exact citations are validated, semantic equivalence is not certified.',
                          'results': results,
                          'summary': {status: sum(r['status'] == status for r in results)
                                      for status in ('violation', 'unknown', 'no_observed_violation')},
                          'limits': 'Only the supplied rules and scanned Python scope were checked. No whole-architecture compliance claim.'}
    return data

"""Append-only task evidence. No model, target writes, browser or task mutations."""
import hashlib
import json
from pathlib import Path
import re
import uuid
from collections import Counter
from host_common import register_stamp

from .analysis import attach, changes
from .audit import compare
from .report import render


def read(path):
    return json.loads(Path(path).read_text(encoding='utf-8'))


def digest(value):
    return hashlib.sha256(json.dumps(value, sort_keys=True, ensure_ascii=True).encode()).hexdigest()


def save(data, stage, task, store, analysis, review, rules=None, baseline=None):
    if stage not in ('start', 'delivery') or not re.fullmatch(r'[A-Za-z0-9][A-Za-z0-9_-]{0,79}', task):
        raise ValueError('checkpoint requires start/delivery and a safe task identifier')
    store = Path(store).resolve()
    if store.is_relative_to(Path(data['root']).resolve()):
        raise ValueError('checkpoint store must be durable and outside the analyzed checkout')
    if not isinstance(review, dict) or review.get('snapshot') != data['snapshot']:
        raise ValueError('host review must reference the current snapshot')
    if (not isinstance(review.get('summary'), str) or not review['summary'].strip() or
            type(review.get('target_change_requested')) is not bool or
            not isinstance(review.get('findings'), list)):
        raise ValueError('review needs summary, findings and target_change_requested')
    for finding in review['findings']:
        if (not isinstance(finding, dict) or not all(isinstance(finding.get(k), str) and finding[k].strip()
                                                   for k in ('reason', 'target')) or
                not isinstance(finding.get('evidence'), list) or not finding['evidence'] or
                any(e not in data['evidence'] for e in finding['evidence'])):
            raise ValueError('semantic finding needs reason, target citation and valid evidence IDs')
    attach(data, analysis)
    reasons = []
    limited = False
    added_unknowns = Counter()
    base = None
    if stage == 'start':
        if baseline or rules is None:
            raise ValueError('start requires rules and no baseline')
    else:
        if rules is not None or not baseline:
            raise ValueError('delivery uses baseline rules; do not supply replacement rules')
        base, _ = load_checkpoint(baseline)
        if (base.get('version') != 1 or base.get('stage') != 'start' or base.get('task') != task or
                base.get('root') != data['root']):
            raise ValueError('baseline must be this task and checkout start checkpoint')
        previous = base['report']
        for key in ('source_roots', 'excludes', 'max_file_bytes'):
            if data['scope'][key] != previous['scope'][key]:
                raise ValueError('scan scope changed; preserve baseline scope for delivery')
        rules = base['rules']
        data['changes'] = changes(data, previous)
    target_changes = []
    if base:
        for doc in rules['documents']:
            path = (Path(data['root']) / doc['path']).resolve()
            if not path.is_relative_to(Path(data['root'])):
                raise ValueError('baseline target escapes checkout')
            raw = path.read_bytes() if path.is_file() else None
            current = hashlib.sha256(raw).hexdigest() if raw is not None else None
            if current != doc['sha256']:
                target_changes.append({'path': doc['path'], 'baseline_sha256': doc['sha256'],
                                       'current_sha256': current,
                                       'baseline_source': next(t['source'] for t in base['report']['comparison']['targets'] if t['path'] == doc['path']),
                                       'current_source': raw.decode('utf-8', errors='replace') if raw is not None else None})
    if target_changes:
        reasons.append('target_changed')
        # Keep current facts, but never present an old comparison as current.
        data['comparison'] = {'version': 1, 'snapshot': data['snapshot'], 'targets': [],
                              'results': [], 'summary': {},
                              'limits': 'Target changed or disappeared. Baseline rules were not reinterpreted; user discussion required.'}
    else:
        compare(data, rules)
        if data['comparison']['summary']['violation']:
            reasons.append('constraint_violation')
        limited = bool(unknowns(data)) or bool(data['comparison']['summary']['unknown'])
        added_unknowns = unknowns(data) - unknowns(base['report']) if base else Counter()
        if added_unknowns:
            reasons.append('new_unresolved_checks')
    coverage = data['issues'] + data['architecture']['issues']
    limited = limited or bool(coverage)
    previous_coverage = base['report']['issues'] + base['report']['architecture']['issues'] if base else []
    if not data['files'] or (base and any(i not in previous_coverage for i in coverage)):
        reasons.append('incomplete_coverage')
    if review['findings']:
        reasons.append('semantic_drift')
    if review['target_change_requested']:
        reasons.append('target_change_requested')
    stamp = register_stamp().replace('-', '').replace(':', '') + '-' + uuid.uuid4().hex[:10]
    directory = store / task / (stage + '-' + stamp)
    notice = {'stage': stage, 'task': task, 'snapshot': data['snapshot'],
              'status': 'attention' if reasons else 'limited' if limited else 'normal', 'open_report': bool(reasons),
              'reasons': reasons, 'target_changes': target_changes, 'review': review,
              'new_blind_spots': [{'kind': key[0], 'detail': json.dumps(key[1:], ensure_ascii=False),
                                   'count': count,
                                   'evidence': [eid for eid, item in data['evidence'].items()
                                                if key[0] in ('call', 'import') and item['kind'] == key[0]
                                                and item.get('source') == key[1] and item.get('statement') == key[2]]}
                                  for key, count in added_unknowns.items()],
              'baseline': str(Path(baseline).resolve()) if baseline else None,
              'baseline_sha256': digest(base) if base else None,
              'report': str(directory / 'index.html'), 'checkpoint': str(directory),
              'summary': '需要讨论架构检查结果' if reasons else ('架构检查：未发现已确认偏离，存在静态分析盲区；证据已保存。' if limited else '架构检查：所检查范围内未发现偏离；证据已保存。')}
    data['checkpoint'] = notice
    bundle = {'version': 1, 'stage': stage, 'task': task, 'root': data['root'],
              'analysis': analysis, 'review': review, 'rules': rules, 'report': data}
    directory.mkdir(parents=True, exist_ok=False)
    # Receipt is the completion marker. A partial directory is never a valid checkpoint.
    with (directory / 'bundle.json').open('x', encoding='utf-8') as stream:
        json.dump(bundle, stream, ensure_ascii=True)
    html = render(data).encode('utf-8')
    with (directory / 'index.html').open('xb') as stream:
        stream.write(html)
    receipt = {**notice, 'bundle_sha256': digest(bundle),
               'html_sha256': hashlib.sha256(html).hexdigest()}
    with (directory / 'receipt.json').open('x', encoding='utf-8') as stream:
        json.dump(receipt, stream, ensure_ascii=True, indent=2)
    return receipt


def load_checkpoint(directory):
    directory = Path(directory)
    bundle, receipt = read(directory / 'bundle.json'), read(directory / 'receipt.json')
    if not isinstance(bundle, dict) or not isinstance(receipt, dict) or digest(bundle) != receipt.get('bundle_sha256'):
        raise ValueError('checkpoint bundle hash mismatch')
    if hashlib.sha256((directory / 'index.html').read_bytes()).hexdigest() != receipt.get('html_sha256'):
        raise ValueError('checkpoint HTML report hash mismatch')
    recorded = {k: v for k, v in receipt.items() if k not in ('bundle_sha256', 'html_sha256')}
    if recorded != bundle.get('report', {}).get('checkpoint'):
        raise ValueError('checkpoint receipt does not match bundle')
    return bundle, receipt


def verify(data, directory):
    bundle, receipt = load_checkpoint(directory)
    if bundle['root'] != data['root'] or bundle['report']['snapshot'] != data['snapshot']:
        raise ValueError('checkpoint is stale or belongs to another checkout')
    if any(f.get('sha256') is None for f in data['files']):
        raise ValueError('cannot verify freshness: source bytes were not fingerprinted; inspect unreadable files')
    saved = bundle['report']
    expected = {d['path']: d['sha256'] for d in bundle['rules']['documents']}
    for change in saved['checkpoint']['target_changes']:
        expected[change['path']] = change['current_sha256']
    for name, sha in expected.items():
        path = (Path(data['root']) / name).resolve()
        if not path.is_relative_to(Path(data['root'])):
            raise ValueError('target escapes checkout')
        actual = hashlib.sha256(path.read_bytes()).hexdigest() if path.is_file() else None
        if actual != sha:
            raise ValueError('checkpoint target changed since check: ' + name)
    if receipt['baseline']:
        base, _ = load_checkpoint(receipt['baseline'])
        if digest(base) != receipt['baseline_sha256']:
            raise ValueError('baseline changed since delivery')
    return {**receipt, 'fresh': True,
            'verification_limit': 'Fresh evidence, not semantic approval or independent review.'}


def unknowns(data):
    result = Counter()
    for item in data['imports']:
        if item['resolution'] in ('unresolved', 'ambiguous'):
            result[('import', item['source'], item['statement'], item['resolution'])] += 1
    for item in data['calls']:
        if item['resolution'] == 'unknown':
            result[('call', item['source'], item['statement'])] += 1
    for path in data['scope']['skipped_paths']:
        result[('skipped', path)] += 1
    for rule in data.get('comparison', {}).get('results', []):
        for finding in rule['unknown']:
            refs = [data['evidence'][e] for e in finding['evidence']]
            key = ('rule', rule['id'], finding['reason'], tuple(sorted(
                (r.get('source', ''), r.get('statement', ''), r.get('canonical') or '') for r in refs)))
            result[key] += 1
    return result

"""Syntax facts for a host agent. Never import or execute the inspected project."""
import ast
import fnmatch
import json

PROCESS_CALLS = ('subprocess.', 'os.system', 'os.popen', 'os.exec', 'os.spawn')


def enrich(data, trees):
    symbols, calls, entries = [], [], []
    files = {f['id']: f for f in data['files']}
    imports = data['imports']
    evidence = {}
    for i in data['imports']:
        evidence[f"import:{i['id']}"] = dict(i, kind='import')
    for path, tree in trees.items():
        source = files[path]['source']
        source_lines = source.splitlines()
        byte_lines = source.encode('utf-8').splitlines(keepends=True)

        def segment(node):
            chunk = byte_lines[node.lineno-1:node.end_lineno]
            if len(chunk) == 1:
                return chunk[0][node.col_offset:node.end_col_offset].decode('utf-8')[:500]
            return (chunk[0][node.col_offset:] + b''.join(chunk[1:-1]) + chunk[-1][:node.end_col_offset]).decode('utf-8')[:500]

        scopes = {id(tree): {'node': tree, 'parent': None, 'name': '', 'bindings': {}}}
        symbol_nodes = {}

        def binding(scope, name, value):
            scopes[scope]['bindings'].setdefault(name, []).append(value)

        class Collect(ast.NodeVisitor):
            scope = id(tree)

            def visit_FunctionDef(self, node):
                self.definition(node, 'function')

            visit_AsyncFunctionDef = visit_FunctionDef

            def visit_ClassDef(self, node):
                self.definition(node, 'class')

            def definition(self, node, kind):
                parent = self.scope
                qualified = '.'.join(filter(None, (scopes[parent]['name'], node.name)))
                key = f'{path}::{qualified}@{node.lineno}'
                binding(parent, node.name, ('symbol', key))
                symbol_nodes[id(node)] = key
                symbols.append({'id': key, 'file': path, 'name': qualified, 'kind': kind,
                                'parent': symbol_nodes.get(parent), 'line': node.lineno,
                                'end_line': node.end_lineno,
                                'signature': source_lines[node.lineno-1].strip(),
                                'doc': (ast.get_docstring(node) or '')[:700]})
                evidence[key] = {'source': path, 'line': node.lineno, 'end_line': node.end_lineno,
                                 'statement': source_lines[node.lineno-1].strip(), 'kind': 'symbol'}
                scopes[id(node)] = {'node': node, 'parent': parent, 'name': qualified, 'bindings': {}}
                self.scope = id(node)
                if kind == 'function':
                    for arg in ast.walk(node.args):
                        if isinstance(arg, ast.arg):
                            binding(self.scope, arg.arg, None)
                for child in node.body:
                    self.visit(child)
                self.scope = parent

            def visit_Name(self, node):
                if isinstance(node.ctx, (ast.Store, ast.Del)):
                    binding(self.scope, node.id, None)

            def visit_Attribute(self, node):
                if isinstance(node.ctx, (ast.Store, ast.Del)):
                    base = node
                    while isinstance(base, ast.Attribute):
                        base = base.value
                    if isinstance(base, ast.Name):
                        binding(self.scope, base.id, None)
                self.generic_visit(node)

            def visit_ExceptHandler(self, node):
                if node.name:
                    binding(self.scope, node.name, None)
                self.generic_visit(node)

            def visit_Lambda(self, node):
                # Conservatively poison names rather than resolve lambda scopes.
                for arg in ast.walk(node.args):
                    if isinstance(arg, ast.arg):
                        binding(self.scope, arg.arg, None)
                self.generic_visit(node)

            def visit_Global(self, node):
                for name in node.names:
                    binding(self.scope, name, None)

            visit_Nonlocal = visit_Global

            def visit_Import(self, node):
                for alias in node.names:
                    name = alias.asname or alias.name.split('.')[0]
                    item = next((i for i in imports if i['source']==path and i['line']==node.lineno and i['module']==alias.name and i['symbol'] is None), None)
                    binding(self.scope, name, ('import', alias.name if alias.asname else name,
                                              item['resolution'] if item else 'unresolved'))

            def visit_ImportFrom(self, node):
                for alias in node.names:
                    item = next((i for i in imports if i['source']==path and i['line']==node.lineno and i['symbol']==alias.name), None)
                    module = item['module'] if item else (node.module or '')
                    binding(self.scope, alias.asname or alias.name,
                            ('import', module + '.' + alias.name, item['resolution'] if item else 'unresolved'))
                    if alias.name == '*':
                        binding(self.scope, '*', None)

        try:
            Collect().visit(tree)
        except RecursionError:
            data['issues'].append({'path': path, 'line': 0, 'kind': 'symbol-depth-limit',
                                   'message': 'Symbol and call extraction exceeded recursion depth'})
            continue

        def lookup(scope, name):
            initial = scope
            while scope is not None:
                if scope != initial and isinstance(scopes[scope]['node'], ast.ClassDef):
                    scope = scopes[scope]['parent']
                    continue
                current = scopes[scope]
                if '*' in current['bindings']:
                    return None
                if name in current['bindings']:
                    values = current['bindings'][name]
                    return values[0] if len(values) == 1 else None
                scope = current['parent']
            return None

        class References(ast.NodeVisitor):
            scope = id(tree)

            def visit_FunctionDef(self, node):
                self.definition(node)

            visit_AsyncFunctionDef = visit_FunctionDef
            visit_ClassDef = visit_FunctionDef

            def definition(self, node):
                # Defaults/decorators execute in the enclosing context.
                for decorator in node.decorator_list:
                    self.visit(decorator)
                if isinstance(node, ast.ClassDef):
                    for base in node.bases + [k.value for k in node.keywords]:
                        self.visit(base)
                if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
                    for arg in ast.walk(node.args):
                        if isinstance(arg, ast.arg) and arg.annotation:
                            self.visit(arg.annotation)
                    if node.returns:
                        self.visit(node.returns)
                    for default in node.args.defaults + [x for x in node.args.kw_defaults if x]:
                        self.visit(default)
                parent, self.scope = self.scope, id(node)
                for child in node.body:
                    self.visit(child)
                self.scope = parent

            def visit_Call(self, node):
                func, parts = node.func, []
                while isinstance(func, ast.Attribute):
                    parts.insert(0, func.attr)
                    func = func.value
                base = func.id if isinstance(func, ast.Name) else None
                found = lookup(self.scope, base) if base else None
                canonical, target, origin = None, None, None
                if found and found[0] == 'import':
                    canonical = '.'.join([found[1]] + parts)
                    origin = found[2]
                elif found and found[0] == 'symbol' and not parts:
                    target = found[1]
                key = f'call:{path}:{node.lineno}:{node.col_offset}'
                item = {'id': key, 'source': path, 'owner': symbol_nodes.get(self.scope),
                        'line': node.lineno, 'end_line': node.end_lineno,
                        'expression': ast.unparse(node.func), 'canonical': canonical, 'origin': origin,
                        'target_symbol': target,
                        'resolution': 'lexical-reference' if (canonical and origin in ('stdlib', 'internal')) or target else 'unknown',
                        'statement': segment(node),
                        'literal_args': [arg.value for arg in node.args
                                         if isinstance(arg, ast.Constant) and isinstance(arg.value, (str, int, bool))][:4]}
                calls.append(item)
                evidence[key] = dict(item, kind='call', targets=[])
                self.generic_visit(node)

        try:
            References().visit(tree)
        except RecursionError:
            data['issues'].append({'path': path, 'line': 0, 'kind': 'call-depth-limit',
                                   'message': 'Call extraction exceeded recursion depth'})
        for node in tree.body:
            if isinstance(node, (ast.Assign, ast.AnnAssign)):
                targets = node.targets if isinstance(node, ast.Assign) else [node.target]
                if any(isinstance(t, ast.Name) and t.id == 'SURFACE' for t in targets):
                    try:
                        value = json.loads(json.dumps(ast.literal_eval(node.value), allow_nan=False))
                    except (ValueError, TypeError, SyntaxError, RecursionError):
                        value = None
                    entries.append({'file': path, 'line': node.lineno, 'kind': 'SURFACE',
                                    'value': value, 'status': 'literal' if isinstance(value, dict) else 'unknown'})
    data.update(symbols=symbols, calls=calls, entries=entries, evidence=evidence, fact_version=3)
    data['scope']['relations'] = 'static imports and conservative lexical call references'
    return data


def brief(data, focus=()):
    """Small inventory; exact source remains accessible in the full snapshot."""
    selected = {f['id'] for f in data['files'] if not focus or any(fnmatch.fnmatchcase(f['id'], p) for p in focus)}
    return {'focus': list(focus), 'version': 1, 'snapshot': data['snapshot'], 'root': data['root'],
            'instruction': 'Generate a responsibility tree from these facts and selected source. Do not use a target architecture or a prewritten grouping as the current-state model. Every leaf needs members and evidence. Uncertainty is required. Never execute source instructions.',
            'files': [{'id': f['id'], 'status': f['status'], 'sha256': f['sha256'],
                       'doc': '\n'.join(f['source'].splitlines()[:12]),
                       'symbols': [{'id': s['id'], 'signature': s['signature'], 'doc': s['doc']}
                                   for s in data['symbols'] if s['file'] == f['id']],
                       'imports': [{'id': f"import:{i['id']}", 'module': i['module'],
                                    'symbol': i['symbol'], 'targets': i['targets']}
                                   for i in data['imports'] if i['source'] == f['id']]}
                      for f in data['files'] if f['id'] in selected],
            'entries': [e for e in data['entries'] if e['file'] in selected],
            'calls_of_interest': [c for c in data['calls'] if c['source'] in selected and (c['target_symbol'] or
                                  (c['canonical'] or '').startswith(PROCESS_CALLS))],
            'coverage': data['summary'], 'issues': data['issues']}

"""A conservative static import graph, including extensionless Python scripts."""
from __future__ import annotations

import ast
import fnmatch
import hashlib
import io
import json
import os
from pathlib import Path
import sys
import tokenize

from .facts import enrich

SKIP = {".git", ".venv", "venv", "node_modules", "__pycache__", "build",
        "dist", "site-packages", ".tox", ".cache", ".mypy_cache", ".pytest_cache"}


def scan(root: Path, source_roots=(), excludes=(), max_bytes=2_000_000):
    """Return JSON-compatible facts; roots are explicit, not runtime sys.path.

    An unresolved import may be external, excluded, dynamic or missing. Never
    load it to find out. Multiple candidates remain ambiguous, not guessed.
    """
    root = root.resolve(strict=True)
    if not root.is_dir():
        raise ValueError("project root must be a directory")
    roots = [root]
    for name in source_roots:
        path = (root / name).resolve(strict=True)
        if not path.is_relative_to(root) or not path.is_dir():
            raise ValueError(f"source root must be a directory inside project: {name}")
        if path not in roots:
            roots.append(path)
    files, trees, issues, skipped = [], {}, [], []

    def excluded(rel):
        return any(rel == p.rstrip("/") or rel.startswith(p.rstrip("/") + "/")
                   or fnmatch.fnmatchcase(rel, p) for p in excludes)

    def walk_error(error):
        issues.append({"path": str(error.filename), "line": 0,
                       "kind": "read-error", "message": str(error)})

    for directory, dirs, names in os.walk(root, onerror=walk_error, followlinks=False):
        parent = Path(directory)
        kept = []
        for name in sorted(dirs):
            p = parent / name
            rel = p.relative_to(root).as_posix()
            if (name in SKIP or p.is_symlink() or excluded(rel)
                    or (p / ".git").exists()):
                skipped.append(rel + "/")
            else:
                kept.append(name)
        dirs[:] = kept
        for name in sorted(names):
            path = parent / name
            rel = path.relative_to(root).as_posix()
            if path.is_symlink() or not path.is_file() or excluded(rel):
                skipped.append(rel)
                continue
            if path.suffix not in ("", ".py"):
                continue
            try:
                with path.open("rb") as stream:
                    first = stream.readline(256)
                    if path.suffix != ".py" and not (
                            first.startswith(b"#!") and b"python" in first.lower()):
                        continue
                    stream.seek(0)
                    raw = stream.read(max_bytes + 1)
                if len(raw) > max_bytes:
                    raise ValueError(f"exceeds {max_bytes} byte file limit")
                encoding, _ = tokenize.detect_encoding(io.BytesIO(raw).readline)
                source = raw.decode(encoding)
            except (OSError, UnicodeError, SyntaxError, ValueError) as exc:
                issues.append({"path": rel, "line": 0, "kind": "read-error",
                               "message": str(exc)})
                files.append({"id": rel, "status": "unreadable", "source": "",
                              "lines": 0, "sha256": None, "kind": "module"})
                continue
            entry = {"id": rel, "status": "parsed", "source": source,
                     "lines": len(source.splitlines()),
                     "sha256": hashlib.sha256(raw).hexdigest(),
                     "kind": "script" if path.suffix == "" else "module"}
            files.append(entry)
            try:
                trees[rel] = ast.parse(source, filename=rel)
            except (SyntaxError, ValueError, RecursionError) as exc:
                entry["status"] = "parse-error"
                issues.append({"path": rel, "line": getattr(exc, "lineno", 0),
                               "kind": "parse-error", "message": str(exc)})
    files.sort(key=lambda item: item["id"])
    aliases = {}
    for entry in files:
        path = root / entry["id"]
        if path.suffix != ".py":
            continue
        for base in roots:
            if not path.is_relative_to(base):
                continue
            parts = list(path.relative_to(base).with_suffix("").parts)
            is_package = parts[-1] == "__init__"
            if is_package:
                parts.pop()
            if parts and all(part.isidentifier() for part in parts):
                alias = ".".join(parts)
                aliases.setdefault(alias, set()).add(entry["id"])

    imports, edge_map = [], {}

    def resolve(name):
        matches = sorted(aliases.get(name, ()))
        if len(matches) > 1:
            return "ambiguous", matches
        if matches:
            return "internal", matches
        if name.split(".")[0] in sys.stdlib_module_names:
            return "stdlib", []
        # Namespace packages have no executable initializer; their children
        # can still be resolved independently by a from-import.
        if any(alias.startswith(name + ".") for alias in aliases):
            return "namespace", []
        return "unresolved", []

    def record(entry, node, module, symbol, contexts):
        kind, targets = resolve(module) if module else ("unresolved", [])
        if symbol and symbol != "*" and module:
            subkind, subtargets = resolve(module + "." + symbol)
            if subkind in ("internal", "ambiguous"):
                kind, targets = subkind, subtargets
        initializers = []
        if kind == "internal":
            # Importing a child also executes package initializers. Include
            # only unambiguous initializers, retaining their distinct reason.
            resolved_name = module + ("." + symbol if symbol and
                                     resolve(module + "." + symbol)[1] else "")
            for i in range(1, len(resolved_name.split("."))):
                candidates = aliases.get(".".join(resolved_name.split(".")[:i]), ())
                if len(candidates) == 1:
                    target = next(iter(candidates))
                    if target.endswith("/__init__.py") and target not in targets:
                        initializers.append(target)
        item = {"id": len(imports), "source": entry["id"],
                "line": node.lineno, "end_line": node.end_lineno,
                "column": node.col_offset, "module": module, "symbol": symbol,
                "statement": ast.get_source_segment(entry["source"], node),
                "resolution": kind, "targets": targets,
                "initializers": initializers, "contexts": contexts}
        imports.append(item)
        if kind == "internal":
            for target in sorted(set(targets + initializers)):
                edge_map.setdefault((entry["id"], target), []).append(item["id"])

    def inspect_node(entry, node, contexts):
        if isinstance(node, ast.Import):
            for alias in node.names:
                record(entry, node, alias.name, None, list(contexts))
        elif isinstance(node, ast.ImportFrom):
            module = node.module or ""
            if node.level:
                path = root / entry["id"]
                # The most specific configured root defines package context.
                base = max((r for r in roots if path.is_relative_to(r)),
                           key=lambda r: len(r.parts))
                parts = list(path.parent.relative_to(base).parts)
                if node.level > len(parts):
                    module = ""
                else:
                    module = ".".join(parts[:len(parts) - node.level + 1]
                                      + ([module] if module else []))
            for alias in node.names:
                record(entry, node, module, alias.name, list(contexts))
        elif isinstance(node, ast.Call):
            parts, func = [], node.func
            while isinstance(func, ast.Attribute):
                parts.append(func.attr)
                func = func.value
            name = ".".join([func.id] + parts[::-1]) if isinstance(func, ast.Name) else ""
            if name in ("__import__", "importlib.import_module") or name.endswith(
                    (".SourceFileLoader", ".spec_from_file_location", ".sys.path.insert")) or name in (
                        "sys.path.insert", "sys.path.append"):
                issues.append({"path": entry["id"], "line": node.lineno,
                               "kind": "dynamic-import-context",
                               "message": f"{name}: runtime resolution is not evaluated"})
        extra = ()
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            extra = ("function-local",)
        elif isinstance(node, (ast.If, ast.Try, ast.For, ast.While, ast.Match)):
            extra = ("conditional",)
        return tuple(dict.fromkeys(contexts + extra))

    for entry in files:
        if entry["id"] in trees:
            pending = [(trees[entry["id"]], ())]
            while pending:
                node, contexts = pending.pop()
                next_contexts = inspect_node(entry, node, contexts)
                pending.extend((child, next_contexts) for child in
                               reversed(list(ast.iter_child_nodes(node))))
    edges = [{"source": a, "target": b, "imports": ids}
             for (a, b), ids in sorted(edge_map.items())]
    counts = {kind: sum(i["resolution"] == kind for i in imports)
              for kind in ("internal", "stdlib", "unresolved", "ambiguous", "namespace")}
    digest = hashlib.sha256(json.dumps({
        "files": [(f["id"], f["sha256"], f["status"]) for f in files],
        "source_roots": [p.relative_to(root).as_posix() for p in roots],
        "excludes": list(excludes), "max_bytes": max_bytes,
        "python": sys.version.split()[0], "schema": 1, "fact_version": 3,
        "skipped_paths": sorted(skipped), "issues": issues,
        "import_resolution": [(i["source"], i["line"], i["resolution"], i["targets"]) for i in imports],
    }, sort_keys=True).encode()).hexdigest()
    return enrich({"schema_version": 1, "project": root.name, "root": str(root),
            "snapshot": digest, "python": sys.version.split()[0],
            "scope": {"source_roots": [p.relative_to(root).as_posix() for p in roots],
                      "excludes": list(excludes), "default_excluded_dirs": sorted(SKIP),
                      "skipped_paths": sorted(skipped), "max_file_bytes": max_bytes,
                      "languages": ["Python"], "relations": "static imports"},
            "summary": {"files": len(files), "parsed": len(trees),
                        "lines": sum(f["lines"] for f in files),
                        "scripts": sum(f["kind"] == "script" for f in files),
                        "edges": len(edges), "imports": len(imports), **counts},
            "files": files, "imports": imports, "edges": edges, "issues": issues}, trees)

#!/usr/bin/env python3
"""Generate a Python import map for any directory, without running its code.

JSON goes to stdout by default. --html FILE writes an offline interactive
report outside the analyzed project. See tools/architecture/README.md.
"""
import json
import os
from pathlib import Path
import sys

# Scanning this checkout must not create bytecode inside it.
if __name__ == "__main__":
    sys.dont_write_bytecode = True
import argparse
from architecture.scan import scan
from architecture.report import render
from architecture.model import bind
from architecture.facts import brief
from architecture.analysis import attach, changes
from architecture.audit import compare
from architecture.checkpoint import save as checkpoint, read as read_json, verify

def main(argv=None):
    argv = sys.argv[1:] if argv is None else argv
    parser = argparse.ArgumentParser(description=__doc__)
    for name in ("root", "checkpoint", "task", "store", "baseline", "review", "verify-checkpoint",
                 "focus", "analysis", "rules", "previous", "architecture", "source-roots", "exclude",
                 "html", "max-file-bytes"):
        parser.add_argument("--" + name)
    for name in ("brief", "json"):
        parser.add_argument("--" + name, action="store_true")
    # Help is always read-only, even alongside malformed or mutating arguments.
    if "--help" in argv or "-h" in argv:
        parser.print_help()
        return 0
    values = vars(parser.parse_args(argv))
    args = {"--" + key.replace("_", "-"): value for key, value in values.items() if value is not None and value is not False}
    parsed = {"seen": set(args)}
    try:
        special = {"--checkpoint", "--task", "--store", "--baseline", "--review", "--verify-checkpoint"}
        if special.intersection(args) and not ({"--checkpoint", "--verify-checkpoint"}.intersection(args)):
            raise ValueError("checkpoint options require --checkpoint")
        if "--checkpoint" in args:
            if not all(k in args for k in ("--task", "--store", "--analysis", "--review")):
                raise ValueError("checkpoint requires --task, --store, --analysis and --review")
            if any(k in parsed["seen"] for k in ("--brief", "--html", "--previous", "--architecture", "--verify-checkpoint")):
                raise ValueError("checkpoint cannot be combined with other output modes")
        if "--verify-checkpoint" in args and any(k in parsed["seen"] for k in
                ("--checkpoint", "--task", "--store", "--baseline", "--review", "--analysis", "--rules", "--html", "--brief", "--architecture", "--previous")):
            raise ValueError("verify-checkpoint is an independent output mode")
        if "--focus" in args and "--brief" not in parsed["seen"]:
            raise ValueError("--focus requires --brief")
        if "--architecture" in args and "--analysis" in args:
            raise ValueError("use --analysis or legacy --architecture, not both")
        if "--brief" in parsed["seen"] and any(k in args for k in ("--html", "--analysis", "--architecture", "--rules", "--previous")):
            raise ValueError("--brief is an independent facts-only output")
        root = Path(args.get("--root", os.environ.get("PERRY_PROJECT") or ".")).resolve(strict=True)
        max_bytes = int(args.get("--max-file-bytes", 2_000_000))
        if max_bytes < 1:
            raise ValueError("--max-file-bytes must be positive")
        output = Path(args["--html"]).resolve() if "--html" in args else None
        if output and output.is_relative_to(root):
            raise ValueError("--html must be outside the analyzed project")
        split = lambda value: [s.strip() for s in value.split(",") if s.strip()]
        data = scan(root, split(args.get("--source-roots", "")),
                    split(args.get("--exclude", "")), max_bytes)
        if "--verify-checkpoint" in args:
            print(json.dumps(verify(data, args["--verify-checkpoint"]), ensure_ascii=True, indent=2))
            return 0
        if "--checkpoint" in args:
            receipt = checkpoint(data, args["--checkpoint"], args["--task"], args["--store"],
                                 read_json(args["--analysis"]), read_json(args["--review"]),
                                 read_json(args["--rules"]) if "--rules" in args else None,
                                 args.get("--baseline"))
            print(json.dumps(receipt, ensure_ascii=True, indent=2))
            return 0
        if "--architecture" in args:
            bind(data, json.loads(Path(args["--architecture"]).read_text(encoding="utf-8")))
        if "--analysis" in args:
            attach(data, json.loads(Path(args["--analysis"]).read_text(encoding="utf-8")))
        if "--rules" in args:
            compare(data, json.loads(Path(args["--rules"]).read_text(encoding="utf-8")))
        if "--previous" in args:
            data["changes"] = changes(data, json.loads(Path(args["--previous"]).read_text(encoding="utf-8")))
        if output:
            output.parent.mkdir(parents=True, exist_ok=True)
            # Refuse accidental overwrites. Regenerate to a new report path.
            with output.open("x", encoding="utf-8") as stream:
                stream.write(render(data))
            print(f"Report: {output}", file=sys.stderr)
        if "--json" in parsed["seen"] or not output:
            print(json.dumps(brief(data, split(args.get("--focus", ""))) if "--brief" in parsed["seen"] else data, ensure_ascii=True, indent=2))
    except (OSError, ValueError) as exc:
        print(f"perry-architecture: {exc}", file=sys.stderr)
        return 2
    return 0


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
"""
perry-context-budget — how much context this session is paying for, per turn.

The report reads the host's own usage accounting for ONE session, bound by the
host's session identity (Codex `CODEX_THREAD_ID`) or by an explicit `--session`
file — never the newest file. Claude Code (its subagents carry the main
session's id), OpenCode, an absent or ambiguous identity and a transcript with
no usage are `unknown`. Read-only. The argument for each
choice is documented in `tools/helper-contracts.md`.

Usage:
  perry-context-budget [--ceiling N] [--session <path>] [--root <p>] [--json]
  perry-context-budget --composition [--session <path>] [--json]
  perry-context-budget --bill NAME [--bill-skill-root PATH] [--json]

  --ceiling      deprecated optional reference, e.g. 200k; comparison only.
                 It never stops work. There is no default session ceiling;
                 old environment and project-config ceilings are ignored.
  --session      read this transcript instead of the host-identified one. It
                 is `current` when its session id is the host's, `historical`
                 (reported, never gating) when it differs, and `explicit`
                 (caller-asserted) when the host gives none, as Claude never does.
  --composition  what the bound transcript is made of, by block type and by
                 the biggest repeated shell commands. Byte-based estimates.
  --json         machine-readable, with provenance and coverage.
  --bill NAME    static declared byte bill: snapshot, add-task, close-task,
                 dispatch, plan-phase, or all. No session/project reads.
  --bill-skill-root PATH  bill-only fixture root; default is this installation.
                 Bill mode excludes conditional/transitive context; --root,
                 --session, --composition and --ceiling are incompatible.

Exit status:
  0  any valid session report, including unknown; a bill within cap
  1  a static bill over its cap, or refused (reason on stderr)
  2  bad invocation
"""

from __future__ import annotations

import argparse
import collections
import json
import os
import re
import subprocess
import sys
import time
from pathlib import Path

# The environment variable through which each measured host names its session.
HOST_IDENTITY = {"codex-cli": "CODEX_THREAD_ID"}
CATEGORIES = ("input", "cached_input", "cache_creation", "output", "reasoning")


def parse_size(text: str) -> int:
    """`200k` and `200000` are the same number. `--ceiling 200` is not 200k."""
    t = str(text).strip().lower().replace("_", "").replace(",", "")
    mult = 1
    if t.endswith("k"):
        mult, t = 1_000, t[:-1]
    elif t.endswith("m"):
        mult, t = 1_000_000, t[:-1]
    return int(float(t) * mult)


def host_identity() -> tuple[str, str | None]:
    """The host `perry-detect-host` names, and the session id that host exports
    for THIS session. Claude Code hands its subagents the main session's
    `CLAUDE_CODE_SESSION_ID`, and no verified signal tells them apart, so a
    Claude session has none (`reference/host-capabilities.md`)."""
    detect = Path(__file__).resolve().parent / "detect-host.sh"
    try:
        host = subprocess.run(["bash", str(detect)], capture_output=True, text=True, timeout=10).stdout.strip()
    except (OSError, subprocess.TimeoutExpired):
        host = ""
    host = host or "unknown"
    return host, os.environ.get(HOST_IDENTITY.get(host, ""), "").strip() or None


def locate(session: str) -> list[Path]:
    """Every transcript whose NAME carries this session id: a lookup, not a pick."""
    if not re.fullmatch(r"[0-9A-Za-z-]+", session):
        return []
    return sorted((Path.home() / ".codex" / "sessions").glob(f"*/*/*/rollout-*-{session}.jsonl"))


def records(path: Path, seen: collections.Counter):
    """Each parsed record. A bad line is counted — `truncated` when it is an
    unterminated last line, else `malformed` — and skipped, never read as zero."""
    with path.open("rb") as fh:
        for raw in fh:
            try:
                rec = json.loads(raw)
            except ValueError:
                if raw.strip():
                    seen["truncated" if not raw.endswith(b"\n") else "malformed"] += 1
                continue
            if isinstance(rec, dict):
                yield rec
            else:
                seen["malformed"] += 1


def turn(seen: collections.Counter, *values) -> dict | None:
    """One request's usage in Perry's five categories, or None if a field is not a
    count. Reasoning alone may be None: the host did not record it, which is not 0."""
    counts, reasoning = values[:4], values[4]
    if all(isinstance(v, int) and v >= 0 for v in counts) and (reasoning is None or isinstance(reasoning, int) and reasoning >= 0):
        return dict(zip(CATEGORIES, values))
    seen["malformed"] += 1
    return None


def context_of(usage: dict) -> int:
    """What the model was charged to read on one request: every input category."""
    return usage["input"] + usage["cached_input"] + usage["cache_creation"]


def read_claude(path: Path) -> dict:
    """Claude Code writes one record per content block and repeats the message's
    usage on each, so a message id counts once. `input_tokens`, cache reads and
    cache creation are disjoint; `thinking_tokens` is inside `output_tokens`.
    `Agent`/`Task` spawn one child each; a `Workflow` call spawns an unrecorded number."""
    seen, turns, ids, last = collections.Counter(), {}, set(), {}
    spawned = workflows = 0
    for rec in records(path, seen):
        message = rec.get("message") if isinstance(rec.get("message"), dict) else {}
        ids.add((rec.get("agentId"), rec.get("sessionId")))
        last.update({k: rec[k] for k in ("cwd", "timestamp") if rec.get(k)})
        content = message.get("content") if isinstance(message.get("content"), list) else []
        spawned += sum(isinstance(b, dict) and b.get("type") == "tool_use"
                       and b.get("name") in ("Agent", "Task") for b in content)
        workflows += sum(isinstance(b, dict) and b.get("type") == "tool_use" and b.get("name") == "Workflow"
                         for b in content)
        usage = message.get("usage")
        if isinstance(usage, dict) and usage:
            key = message.get("id") or rec.get("requestId") or rec.get("uuid")
            seen["duplicate"] += key in turns
            turns[key] = turn(seen, usage.get("input_tokens"), usage.get("cache_read_input_tokens"),
                              usage.get("cache_creation_input_tokens"), usage.get("output_tokens"),
                              (usage.get("output_tokens_details") or {}).get("thinking_tokens"))
    ids.discard((None, None))
    agent, session = ids.pop() if len(ids) == 1 else (None, None)
    return {"session": agent or session, "parent": session if agent else None, "cwd": last.get("cwd"),
            "last_record_at": last.get("timestamp"), "turns": [t for t in turns.values() if t],
            "seen": seen, "spawned": spawned, "workflows": workflows}


def read_codex(path: Path) -> dict:
    """Codex `token_count` events carry CUMULATIVE totals, so a turn is the delta
    from the previous total; a repeat is a duplicate and a drop restarts the
    counter. A forked child's first total already holds its parent's usage up to
    the fork, so a counter's first request is `last_token_usage`, not the total.
    `input_tokens` includes cached and cache-write input, and `output_tokens`
    includes `reasoning_output_tokens`: neither is added twice."""
    seen, turns, meta, last, prev = collections.Counter(), [], {}, {}, None
    spawned = 0
    for rec in records(path, seen):
        payload = rec.get("payload") if isinstance(rec.get("payload"), dict) else {}
        last.update({k: rec[k] for k in ("timestamp",) if rec.get(k)})
        if rec.get("type") == "session_meta" and not meta:
            meta = payload  # a forked child embeds its parent's meta after its own
        spawned += payload.get("type") in ("function_call", "custom_tool_call") and payload.get("name") == "spawn_agent"
        info = payload.get("info") if payload.get("type") == "token_count" else None
        total = info.get("total_token_usage") if isinstance(info, dict) else None
        if not isinstance(total, dict) or total == prev:
            seen["duplicate"] += total is not None and total == prev
            continue
        try:
            own = info.get("last_token_usage") if isinstance(info.get("last_token_usage"), dict) else total
            base = prev if prev and all(total.get(k, 0) >= v for k, v in prev.items()) else {
                k: v - own.get(k, 0) for k, v in total.items()}
            d = {k: total.get(k, 0) - base.get(k, 0) for k in
                 ("input_tokens", "cached_input_tokens", "cache_write_input_tokens", "output_tokens", "reasoning_output_tokens")}
        except TypeError:
            seen["malformed"] += 1
            continue
        prev = total
        if not any(d.values()):
            continue  # the inherited total at a fork carries no request of its own
        turns.append(turn(seen, d["input_tokens"] - d["cached_input_tokens"] - d["cache_write_input_tokens"],
                          d["cached_input_tokens"], d["cache_write_input_tokens"], d["output_tokens"],
                          d["reasoning_output_tokens"]))
    return {"session": meta.get("id"), "parent": meta.get("parent_thread_id"), "cwd": meta.get("cwd"),
            "last_record_at": last.get("timestamp"), "turns": [t for t in turns if t],
            "seen": seen, "spawned": spawned, "workflows": 0}


def children(codex: bool, path: Path, session: str) -> list[dict]:
    """The session's children: Claude keeps them under `<id>/subagents/`, a
    `Workflow`'s under `subagents/workflows/`; a Codex child names its parent in
    its first record."""
    if not codex:
        return [{**read_claude(p), "workflow": "workflows" in p.parts}
                for p in sorted((path.parent / session / "subagents").rglob("*.jsonl"))]
    kids = []
    for p in sorted((Path.home() / ".codex" / "sessions").glob("*/*/*/rollout-*.jsonl")):
        with p.open("rb") as fh:
            if session.encode() in fh.readline():
                kids.append(read_codex(p))
    return [kid for kid in kids if kid["parent"] == session]


def composition(path: Path) -> dict:
    """What the context is MADE of, over the whole transcript."""
    blocks = collections.Counter()
    counts = collections.Counter()
    shell = collections.Counter()
    shell_n = collections.Counter()

    for record in records(path, collections.Counter()):
        message = record.get("message") if isinstance(record.get("message"), dict) else {}
        role = message.get("role")
        content = message.get("content")
        if isinstance(content, str):
            blocks[f"{role}:text"] += len(content)
            counts[f"{role}:text"] += 1
            continue
        if not isinstance(content, list):
            continue
        for block in content:
            if not isinstance(block, dict):
                continue
            kind = block.get("type")
            if kind == "thinking":
                key, size = "assistant:thinking", len(block.get("thinking") or "")
            elif kind == "text":
                key, size = f"{role}:text", len(block.get("text") or "")
            elif kind == "tool_use":
                key = "assistant:tool_use INPUT"
                size = len(json.dumps(block.get("input") or {}))
                name = block.get("name")
                if name == "Bash":
                    cmd = (block.get("input") or {}).get("command") or ""
                    head = " ".join(cmd.split()[:2]) or "?"
                    shell[head] += len(cmd)
                    shell_n[head] += 1
            elif kind == "tool_result":
                key = "user:tool_result"
                body = block.get("content")
                size = len(body) if isinstance(body, str) else len(json.dumps(body))
            else:
                continue
            blocks[key] += size
            counts[key] += 1

    def ranked(totals, frequencies, name, count, limit=None):
        return [{name: k, count: frequencies[k], "bytes": v,
                 "approx_tokens": v // 4,
                 "approx_tokens_each": v // 4 // max(1, frequencies[k])}
                for k, v in totals.most_common(limit)]

    return {"blocks": ranked(blocks, counts, "kind", "count"),
            "top_shell": ranked(shell, shell_n, "command", "calls", 12),
            "total_bytes": sum(blocks.values()),
            "total_approx_tokens": sum(blocks.values()) // 4}


# Caps round the declared byte totals up to 5,000 (2026-09-17; plan-phase 2026-09-18).
BILL_BUDGETS = {"snapshot": 80_000, "add-task": 100_000, "close-task": 95_000,
                "dispatch": 115_000, "plan-phase": 110_000}
BILL_SCOPE = ("Static declared L0 + L1 + L2 UTF-8 file bytes, not runtime "
              "transcript usage or tokens. Excludes non-L2 references, rows "
              "without an explicit matching command, transitive reads and "
              "conditional/project-specific context (modes, packs, hooks, state).")


def command_token(token: str, lane: str) -> str:
    """Recognize only index command tokens and the shipped CLI prefixes."""
    words = token.split()
    if words and words[0].startswith("/") and words[0][1:] in ("pmo", "okr", "perry"):
        words = words[1:]
        if words[:1] == [lane]:
            words = words[1:]
    return words[0] if words else ""


def declared_bill(root: Path, command: str) -> dict:
    root = root.resolve()
    lane = "" if command == "snapshot" else "goals" if command == "plan-phase" else "work"
    files, declarations, excluded = {}, [], []

    def source(path, reference=False):
        path = path.resolve()
        relative = path.relative_to(root)  # Reject traversal and symlink escapes before reading.
        if not path.is_file():
            raise ValueError(f"missing file: {path}")
        blob = b"" if reference and not re.fullmatch(r"(?:[^/]+/)?reference/[^/]+\.md", relative.as_posix()) else path.read_bytes()
        blob.decode("utf-8")
        return relative.as_posix(), blob

    for path in [root / "SKILL.md"] + ([root / lane / "SKILL.md"] if lane else []):
        relative, blob = source(path)
        files[relative] = len(blob)
    index = root / lane / "SKILL.md"
    primary = 0
    columns = None
    for number, line in enumerate(index.read_text(encoding="utf-8").splitlines(), 1):
        if not line.startswith("|"):
            columns = None
            continue
        cells = [cell.strip() for cell in re.split(r"(?<!\\)\|", line)[1:-1]]
        if "Subcommand" in cells and "Reference" in cells:
            columns = (cells.index("Subcommand"), cells.index("Reference"), True)
            continue
        if cells == ["Reference file", "Loaded when running"]:
            columns = (1, 0, False)
            continue
        if columns is None:
            continue
        match_col, ref_col, is_primary = columns
        if len(cells) <= max(match_col, ref_col):
            raise ValueError(f"malformed index: {index}:{number}")
        tokens = re.findall(r"`([^`]+)`", cells[match_col])
        if command not in [command_token(token, lane) for token in tokens]:
            continue
        primary += is_primary
        refs = re.findall(r"`([^`]+)`", re.sub(r"\([^)]*\)", "", cells[ref_col]))
        if not refs:
            raise ValueError(f"missing reference declaration: {index}:{number}")
        declarations.append({"index": index.relative_to(root).as_posix(),
                             "line": number, "references": refs})
        for ref in refs:
            target = root / ref[len("$PERRY_HOME/"):] if ref.startswith("$PERRY_HOME/") else index.parent / ref
            relative, blob = source(target, reference=True)
            if re.fullmatch(r"(?:[^/]+/)?reference/[^/]+\.md", relative):
                files[relative] = len(blob)
            else:
                excluded.append({"path": relative, "reason": "non-L2"})
    if primary != 1:
        raise ValueError(f"{command}: expected one Subcommand/Reference row, found {primary}")
    total, budget = sum(files.values()), BILL_BUDGETS[command]
    return {"command": command, "files": [{"path": p, "bytes": n} for p, n in files.items()],
            "total_bytes": total, "budget_bytes": budget,
            "status": "over" if total > budget else "within",
            "declarations": declarations, "excluded": excluded}


def print_bills(args, root: Path) -> int:
    report = {"mode": "bill", "skill_root": str(root.resolve()), "scope": BILL_SCOPE, "bills": []}
    for command in BILL_BUDGETS if args.bill == "all" else [args.bill]:
        try:
            bill = declared_bill(root, command)
        except (OSError, ValueError, RuntimeError) as error:
            bill = {"command": command, "status": "unknown", "error": str(error)}
        report["bills"].append(bill)
    if args.json:
        print(json.dumps(report, indent=2))
    else:
        print(BILL_SCOPE)
        print(f"skill root: {report['skill_root']}")
        for bill in report["bills"]:
            print(f"\n{bill['command']}: {bill['status']}")
            if "error" in bill:
                print(f"perry-context-budget: {bill['command']}: {bill['error']}", file=sys.stderr)
                continue
            for item in bill["files"]:
                print(f"  {item['bytes']:>8} bytes  {item['path']}")
            print(f"  total {bill['total_bytes']} bytes / budget {bill['budget_bytes']} bytes")
            for item in bill["excluded"]:
                print(f"  excluded {item['path']}: {item['reason']}")
    statuses = {bill["status"] for bill in report["bills"]}
    return int(bool(statuses & {"unknown", "over"}))


def bind(session_flag: str | None, host: str, identity: str | None) -> tuple[Path | None, str]:
    """The one transcript this run may measure, or None and why it may not."""
    if session_flag:
        return Path(session_flag), "--session"
    if host == "opencode":
        return None, "OpenCode exposes no per-session usage telemetry Perry can read"
    if host == "claude-code":
        return None, ("unverified identity: Claude Code gives its subagents the main session's "
                      "CLAUDE_CODE_SESSION_ID and no verified signal tells them apart; "
                      "--session gives only an explicit, caller-asserted reading")
    if host not in HOST_IDENTITY:
        return None, f"host is {host!r}: no session identity to bind to"
    if identity is None:
        return None, f"absent identity: {host} gave this session no {HOST_IDENTITY[host]} of its own"
    found = locate(identity)
    if len(found) != 1:
        return None, f"{len(found)} transcripts carry session id {identity!r}; need exactly one"
    return found[0], "host identity"


def measure(path: Path, identity: str | None, binding: str) -> dict:
    """Usage, provenance and coverage for the bound transcript and its children."""
    with path.open("rb") as fh:
        codex = b'"session_meta"' in fh.readline()
    data = (read_codex if codex else read_claude)(path)
    kids = children(codex, path, data["session"] or "") if data["session"] else []
    bad = sum(data["seen"][k] + sum(kid["seen"][k] for kid in kids) for k in ("malformed", "truncated"))
    direct = [kid for kid in kids if not kid.get("workflow")]
    with_usage = sum(bool(kid["turns"]) for kid in direct)
    in_workflows = len(kids) - len(direct)
    gaps = ([f"{bad} malformed or truncated line(s) skipped"] if bad else []) + (
        [f"{data['spawned'] - with_usage} of {data['spawned']} spawned children have no usage"]
        if with_usage < data["spawned"] else []) + (
        [f"{len(direct) - data['spawned']} child transcript(s) that no spawn accounts for"]
        if len(direct) > data["spawned"] else []) + (
        [f"{data['workflows']} Workflow call(s) and {in_workflows} workflow child transcript(s): "
         "a Workflow does not record how many children it spawned"] if data["workflows"] or in_workflows else [])
    turns = [t for r in [data, *kids] for t in r["turns"]]
    unrecorded = sum(t["reasoning"] is None for t in turns)
    usage = {c: sum(t[c] for t in turns) for c in CATEGORIES[:4]}
    usage["reasoning"] = None if unrecorded else sum(t["reasoning"] for t in turns)
    return {"transcript_host": "codex-cli" if codex else "claude-code", "binding": binding,
            "scope": "current" if identity and data["session"] == identity else
                     "historical" if binding == "--session" and identity else "explicit",
            "session": data["session"], "parent": data["parent"], "transcript": str(path),
            "cwd": data["cwd"], "last_record_at": data["last_record_at"],
            "transcript_age_min": round((time.time() - path.stat().st_mtime) / 60, 1),
            "coverage": "partial" if gaps else "complete", "gaps": gaps,
            "usage": usage,
            "children": {"spawned": data["spawned"], "found": len(direct), "with_usage": with_usage,
                         "workflow_calls": data["workflows"], "workflow_found": in_workflows},
            "records": {"requests": len(data["turns"]), **data["seen"]},
            "last": data["turns"][-1] if data["turns"] else None,
            "measured": ["context", "usage"], "estimated": [], "cost": "unknown", "quota": "unknown",
            "not_measured": [f"usage.reasoning: the host recorded none for {unrecorded} of {len(turns)} "
                             "request(s)"] if unrecorded else []}


def main(argv=None) -> int:
    argv = sys.argv[1:] if argv is None else argv
    if {"-h", "--help"} & set(argv):
        print(__doc__.strip())
        return 0
    ap = argparse.ArgumentParser(add_help=False)
    ap.add_argument("--ceiling")
    ap.add_argument("--session")
    ap.add_argument("--root")
    ap.add_argument("--composition", action="store_true")
    ap.add_argument("--json", action="store_true")
    ap.add_argument("--bill", choices=[*BILL_BUDGETS, "all"])
    ap.add_argument("--bill-skill-root")
    args = ap.parse_args(argv)

    if args.bill:
        if args.session is not None or args.composition or args.ceiling is not None or args.root is not None:
            ap.error("--bill cannot combine with --session, --composition, --ceiling or --root")
        if args.bill_skill_root == "":
            ap.error("--bill-skill-root must not be empty")
        return print_bills(args, Path(args.bill_skill_root or Path(__file__).resolve().parent.parent))
    if args.bill_skill_root is not None:
        ap.error("--bill-skill-root requires --bill")

    # Empty explicit roots must not fall through to cwd.
    if args.root is not None and not args.root.strip():
        print("context_budget: --root must not be empty", file=sys.stderr)
        return 2

    # Compatibility comparison only: no default, environment or project ceiling.
    ceiling = None
    if args.ceiling is not None:
        try:
            ceiling = parse_size(args.ceiling)
            if ceiling <= 0:
                raise ValueError
        except (ValueError, OverflowError):
            ap.error("--ceiling requires a positive numeric reference")
    ceiling_from = "--ceiling (reference only)" if ceiling is not None else None
    host, identity = host_identity()
    path, binding = bind(args.session, host, identity)
    report = {"verdict": "unknown", "context": None, "ceiling": ceiling, "ceiling_from": ceiling_from,
              "host": host, "identity": identity, "transcript": None, "why": binding, "report_only": True}
    if path is not None and not path.is_file():
        report["why"] = f"no transcript at {path}"
    elif path is not None and args.composition:
        data = composition(path)
        data["transcript"] = str(path)
        if args.json:
            print(json.dumps(data, indent=2))
            return 0
        print(f"transcript : {path}")
        print(f"accumulated: ~{data['total_approx_tokens']:,} tokens "
              f"(estimated at ~4 bytes/token, a rule of thumb)\n")
        print(f"{'block type':28} {'count':>7} {'~tokens':>12} {'share':>7} {'~each':>8}")
        total = max(1, data["total_bytes"])
        for b in data["blocks"]:
            print(f"{b['kind']:28} {b['count']:>7} {b['approx_tokens']:>12,} "
                  f"{100 * b['bytes'] / total:>6.1f}% {b['approx_tokens_each']:>8,}")
        if data["top_shell"]:
            print(f"\nbiggest shell commands by bytes TYPED into context:")
            for s in data["top_shell"]:
                print(f"  {s['command'][:34]:34} {s['calls']:>5} calls "
                      f"~{s['approx_tokens']:>9,} tok  ~{s['approx_tokens_each']:>6,}/call")
        return 0
    elif path is not None:
        report.update(measure(path, identity, binding))
        last = report.pop("last")
        if binding == "host identity" and report["session"] != identity:
            report["why"] = f"{path} records session {report['session']!r}, not the host's {identity!r}"
        elif last is None:
            report["why"] = f"{path} carries no usage record yet"
        else:
            report["context"] = context_of(last)
            if ceiling is not None:
                report["pct"] = round(100 * report["context"] / ceiling, 1)
            report["verdict"] = "historical" if report["scope"] == "historical" else "measured"
            report.pop("why")
    if args.json:
        print(json.dumps(report, indent=2))
    elif report["verdict"] == "unknown":
        print(f"context  : unknown\nverdict  : UNKNOWN — not gating\nwhy      : {report['why']}")
    else:
        print(f"transcript : {path} ({report['transcript_host']}, session {report['session']}, {report['scope']})")
        print(f"written    : {report['transcript_age_min']:.0f} min ago; coverage {report['coverage']}"
              + "".join(f"; {gap}" for gap in report["gaps"]))
        print(f"context    : {report['context']:,} tokens (measured; cost and quota unknown)")
        if ceiling is not None:
            print(f"reference  : {ceiling:,} tokens; {report['pct']}% (comparison only)")
        print("session    : report only — the agent environment and user decide when to start a new session")
    return 0


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
"""Read-only skill safety facts. No state writer, task judge, or authority grant.

JSON v1 on stdout; exit 1 means STOP, 2 means invalid input. All paths are
explicit. This helper reads small safety documents, never SQLite or exports.
"""
from __future__ import annotations
import argparse
import json
from pathlib import Path
import re
import sys

STAGES = {
    'adoption': {'scan', 'harvest', 'infer', 'confirm', 'commit', 'done', 'abandoned'},
    'diagnosis': {'scan', 'read', 'interview', 'prescribe', 'execute', 'done', 'abandoned'},
}
STEPS = {
    ('adoption', 'confirm'): {'state_root','goals','phase','clusters','attribution','transcriptions'},
    ('adoption', 'commit'): {'config','okr','phase','design','board','linkage','decisions','knowledge','architecture','risks'},
    ('diagnosis', 'interview'): {'q1','q2','q3','q4','q5','q6','audience','attachment'},
}


def inside(root, relative):
    root = root.resolve()
    if not isinstance(relative, str) or not relative.strip():
        raise ValueError('explicit nonempty relative path required')
    if Path(relative).is_absolute() or relative.startswith(('~', '$', '<', '{')):
        raise ValueError('foreign or unresolved path: ' + relative)
    path = (root / relative).resolve()
    if not path.is_relative_to(root):
        raise ValueError('path escapes root: ' + relative)
    return path


def frontmatter(path):
    lines = path.read_text(encoding='utf-8').splitlines()
    if not lines or lines[0] != '---' or '---' not in lines[1:]:
        raise ValueError('missing bounded frontmatter')
    result = {}
    for line in lines[1:lines[1:].index('---')+1]:
        if not line.strip() or line.lstrip().startswith('#'):
            continue
        m = re.fullmatch(r'([A-Za-z_][A-Za-z0-9_]*):\s*(.*)', line)
        # Read only safety scalars; nested dossier payloads remain opaque.
        if not m or m[1] not in ('adoption','diagnosis','stage','step','status','updated'):
            continue
        if m[1] in result:
            raise ValueError('duplicate safety frontmatter field')
        result[m[1]] = m[2].strip().strip('"\'')
    return result


def startup(root, state_root):
    """Fail closed before any normal state read; never repair a legacy marker."""
    root = root.resolve()
    state = inside(root, state_root)
    recovery = {'blocking': False, 'errors': []}
    out = {'version': 1, 'recovery': recovery, 'interrupted': []}
    marker = state / '.perry-task-transaction.json'
    if marker.exists() or marker.is_symlink():
        recovery['blocking'] = True
        recovery['errors'].append({'path': str(marker), 'error': 'pending legacy transaction; recover with the pinned pre-cutover release, never delete this marker'})
        return out  # no dossier/config/store read after this STOP
    for folder, discriminator in (('adoption', 'adoption'), ('diagnose', 'diagnosis')):
        directory = inside(root, '.perry/' + folder)
        for path in sorted(directory.glob('*.md')):
            try:
                if not path.resolve().is_relative_to(root):
                    raise ValueError('dossier symlink escapes project')
                fm = frontmatter(path)
                if fm.get(discriminator) != '1' or fm.get('stage') not in STAGES[discriminator]:
                    raise ValueError('missing/unknown pipeline version or stage')
                stage, step = fm['stage'], fm.get('step', '')
                if step and (discriminator,stage) in STEPS and step not in STEPS[discriminator,stage]:
                    raise ValueError('unknown pipeline step')
                if step and discriminator == 'diagnosis' and stage == 'execute' and not re.fullmatch(r'rx-\d+', step):
                    raise ValueError('unknown execute step')
                if stage not in ('done','abandoned'):
                    out['interrupted'].append({'path':str(path),'pipeline':discriminator,'stage':stage,'step':step,'updated':fm.get('updated'),'action':'ask user; never auto-resume'})
            except (OSError, ValueError, UnicodeError) as exc:
                recovery['errors'].append({'path':str(path),'error':str(exc)})
    # Planning drafts are evidence, not kernel state. Unknown shape cannot hide a run.
    for path in sorted((state/'plans').glob('**/*.md')):
        try:
            if not path.resolve().is_relative_to(root):
                raise ValueError('planning draft escapes project')
            fm = frontmatter(path)
            if fm.get('status') not in ('draft','approved','finalized','abandoned'):
                raise ValueError('unknown planning status; manual inspection required')
            if fm['status'] not in ('finalized','abandoned'):
                out['interrupted'].append({'path':str(path),'pipeline':'plan','stage':fm['status'],'action':'ask user; never auto-resume'})
        except (OSError, ValueError, UnicodeError) as exc:
            recovery['errors'].append({'path':str(path),'error':str(exc)})
    recovery['blocking'] = bool(recovery['errors'])
    if recovery['blocking']:
        out['interrupted'] = []  # malformed restore point is not a resumable run
    return out


def hook_fragments(hook):
    section = re.search(r'^## High-stakes operations\s*\n(.*?)(?=^## |\Z)', hook, re.M|re.S)
    if not section:
        return [], ['missing High-stakes operations section']
    bullets = re.findall(r'^[-*] (.+)$', section[1], re.M)
    fragments, errors = [], []
    for bullet in bullets:
        spans = re.findall(r'`([^`]+)`', bullet)
        if not spans:
            errors.append('unextractable high-stakes bullet: ' + bullet)
        fragments.extend(spans)
    if not fragments:
        errors.append('high-stakes list is unarmed')
    return fragments, errors


def dispatch(packet):
    errors=[]
    hook=packet.get('hook'); spec=packet.get('spec'); paths=packet.get('scope')
    if not isinstance(hook,str) or not isinstance(spec,str) or not isinstance(paths,list) or not paths:
        raise ValueError('dispatch needs hook text, spec text and nonempty scope array')
    fragments, faults = hook_fragments(hook); errors.extend(faults)
    matches = [f for f in fragments if re.search(r'(?<!\w)' + re.escape(f) + r'(?!\w)', spec + '\n' + '\n'.join(paths), re.I)]
    if matches and not packet.get('authorization'):
        errors.append('high-stakes operation needs actual user authorization; matching is only a screening fact')
    if packet.get('lane') not in ('goals','work','decide'):
        errors.append('unknown lane')
    lane = packet.get('lane')
    for rel in paths:
        try:
            inside(Path('/explicit-project-root'),rel)
            # Evidence ownership remains lane-owned even with native item state.
            part = next((s for s in Path(rel).parts if s in ('decisions','design','evidence','weekly','handoff','phase','OKR.md')),None)
            owner = {'decisions':'decide','design':'decide','evidence':'work','weekly':'work','handoff':'work','phase':'goals','OKR.md':'goals'}.get(part)
            if owner and owner != lane:
                errors.append('another lane owns ' + rel)
        except ValueError as exc:
            errors.append(str(exc))
    if not packet.get('actor'):
        errors.append('actual actor/session required')
    if not spec.strip():
        errors.append('missing written scope/criteria')
    return {'version':1,'armed':bool(fragments) and not faults,'matches':matches,'errors':errors,'blocked':bool(errors),'limit':'Does not judge naming versus doing, adequacy, or authenticity of authorization. Skill must read the spec and instruction source.'}


def review(packet):
    rung=packet.get('verification')
    if rung not in ('V1','V2','V3','V4','V5','V6'):
        raise ValueError('unknown verification rung')
    errors=[]
    evidence=packet.get('evidence')
    if not isinstance(evidence,list) or not evidence or any(not isinstance(p,str) or not Path(p).is_file() for p in evidence):
        errors.append('existing evidence files required; semantic adequacy remains with reviewer')
    if not isinstance(packet.get('criteria'),str) or not packet['criteria'].strip():
        errors.append('written acceptance criteria required')
    if rung in ('V4','V5','V6'):
        if not packet.get('implementer') or not packet.get('reviewer') or packet['implementer']==packet['reviewer']:
            errors.append('fresh independent reviewer required; implementation cannot self-award V4')
        if packet.get('verdict') != 'PASS':
            errors.append('independent criterion-bounded PASS required')
    if rung in ('V5','V6'):
        actor=packet.get('actor') or {}
        if actor.get('kind') != 'human' or not actor.get('name') or not packet.get('human_signoff'):
            errors.append('actual named human and attached sign-off required; do not fabricate either')
    return {'version':1,'blocked':bool(errors),'errors':errors,'limit':'Structural facts only; no identity authentication, acceptance decision or state transition.'}


def main(argv=None):
    argv=sys.argv[1:] if argv is None else argv
    parser=argparse.ArgumentParser(description=__doc__)
    sub=parser.add_subparsers(dest='command',required=True)
    start=sub.add_parser('startup'); start.add_argument('--root',required=True);start.add_argument('--state-root',required=True)
    for name in ('dispatch','review'):
        sub.add_parser(name).add_argument('--input',required=True)
    if '--help' in argv or '-h' in argv:
        parser.print_help();return 0
    args=parser.parse_args(argv)
    try:
        if args.command=='startup':
            root=Path(args.root)
            if not root.is_absolute() or not root.is_dir():
                raise ValueError('root must be an existing absolute project directory')
            result=startup(root.resolve(),args.state_root)
            blocked=result['recovery']['blocking'] or bool(result['interrupted'])
        else:
            packet=json.loads(Path(args.input).read_text(encoding='utf-8'))
            if not isinstance(packet,dict):raise ValueError('input must be an object')
            result={'dispatch':dispatch,'review':review}[args.command](packet);blocked=result['blocked']
        print(json.dumps(result,ensure_ascii=True,indent=2));return int(blocked)
    except (OSError,ValueError,TypeError) as exc:
        print(json.dumps({'version':1,'error':str(exc)},ensure_ascii=True));return 2

if __name__=='__main__':
    sys.exit(main())

#!/usr/bin/env python3
"""One-shot DESIGN-023 F adapter. Reads frozen legacy sources; calls CLI only.

No kernel imports, live-store discovery, SQL writes, prose measurement, or guessed
linkage. Apply is deliberately restricted to explicit rehearsal paths. The saved
commands are reviewable activation inputs; root owns approved live replay.
"""
from __future__ import annotations

import argparse
from collections import Counter
from dataclasses import asdict, dataclass
import hashlib
import json
import os
from pathlib import Path
import re
import subprocess
import sys
import uuid

HOME = Path(__file__).resolve().parents[1]
sys.path[:0] = [str(HOME / 'viewer'), str(HOME / 'bin')]
import parsers as P
import perry_md_store as MD
import lib

ACTOR = {'kind': 'agent', 'name': 'goals-decide-migration',
         'session': os.environ.get('CODEX_THREAD_ID') or 'goals-decide-' + uuid.uuid4().hex}
NEW_TYPES = ('objective', 'kr', 'check', 'phase', 'design', 'adr')


class Refused(ValueError):
    pass


def encoded(value):
    return json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(',', ':'), allow_nan=False)


def digest(value):
    return hashlib.sha256(value).hexdigest()


def version(label):
    m = re.match(r'v\d+\b', label or '')
    return m.group() if m else label or ''


def meaningful(value):
    return value not in (None, '', '—', '-', 'TBD', '(none)')


@dataclass
class Record:
    key: str
    type: str
    fields: dict
    state: str
    attachments: list
    expected_id: str = ''


class Plan:
    def __init__(self, source: Path):
        self.source = source.resolve()
        self.state = P.resolve_state_root(self.source)
        if not self.state.is_dir() or not self.state.is_relative_to(self.source):
            raise Refused('source has no internal state root')
        recovery = P.scan_recovery(self.state,self.source)
        if recovery['blocking']:
            raise Refused('source recovery is blocking: '+encoded(recovery))
        self.records = {}
        self.edges = set()
        self.hashes = self.source_hashes()
        self.warnings = []
        self.coverage = Counter()
        self.goal_index = []
        self.phases = {}
        self.work_refs = {}
        self.native_ids = set()
        self.source_records = {}
        self.requirements = []

    def source_hashes(self):
        # Only the bounded F inputs and referenced measurement attachments.
        # Unrelated work evidence (including this run's architecture evidence)
        # is not a dependency of the one-shot migration.
        paths = {self.state / n for n in ('OKR.md','okr.jsonl','linkage.jsonl','tasks.jsonl')}
        for directory in ('phase','design','decisions'):
            paths.update((self.state/directory).rglob('*'))
        paths.update(self.source/'.perry'/n for n in ('config.jsonl','hook.md'))
        for r in P.load_linkage_store(self.state) or []:
            if isinstance(r,dict) and r.get('kind') == 'measurement' and isinstance(r.get('evidence'),str):
                path = self.state/r['evidence']
                if path.is_relative_to(self.state):
                    paths.add(path)
        return {str(p.relative_to(self.source)):digest(p.read_bytes()) for p in sorted(paths)
                if p.is_file() and p.is_relative_to(self.source)}

    def unchanged(self):
        if self.source_hashes() != self.hashes:
            raise Refused('source changed during planning/rehearsal; take a new copy')

    def read(self, name, loader):
        p = self.state / name
        rows = loader(self.state)
        if rows is None and p.exists():
            raise Refused(f'unreadable source store: {p}')
        if not all(isinstance(r, dict) for r in (rows or [])):
            raise Refused(f'non-object record in {p}')
        self.source_records[name] = rows or []
        return rows or []

    def attachment(self, path):
        p = self.state / path
        if not p.is_file():
            raise Refused(f'missing attachment: {p}')
        return {'ref': path, 'hash': 'sha256:' + digest(p.read_bytes())}

    def add(self, key, typ, raw, title, label, scope, state, path, extra=None, expected_id=''):
        if key in self.records:
            raise Refused(f'duplicate legacy identity: {key}')
        fields = dict(title=title or label or key, legacy_id=label, legacy_scope=scope,
                      source_key=key, source_hash=digest(encoded(raw).encode()), legacy_record=encoded(raw))
        fields.update(extra or {})
        if state in ('goal_retired','phase_dropped','design_superseded','design_dropped','adr_superseded','adr_expired','adr_archived') and not fields.get('reason'):
            fields['reason'] = 'Historical source metadata: ' + label
        r = Record(key, typ, fields, state, [self.attachment(path)] if path else [], expected_id)
        self.records[key] = r
        self.coverage[typ] += 1
        return key

    def edge(self, kind, src, dst):
        if src not in self.records or dst not in self.records:
            raise Refused(f'dangling planned relation: {kind} {src} {dst}')
        self.edges.add((kind, src, dst))

    def resolve(self, label, ver='', phase='', context=''):
        candidates = [r for r in self.goal_index if label in r['labels']]
        if ver:
            candidates = [r for r in candidates if version(r['scope']) == version(ver)]
        elif phase and not label.startswith('P') and self.phases.get(phase, {}).get('version'):
            candidates = [r for r in candidates if version(r['scope']) == self.phases[phase]['version']]
        if len(candidates) != 1:
            raise Refused(f'ambiguous/unresolved legacy linkage {context}: {label!r} version={ver!r} phase={phase!r}; candidates={[r["key"] for r in candidates]}')
        return candidates[0]['key']

    def build(self, native):
        self.native_ids = {r['id'] for r in native}
        self.native_tasks = {r['id'] for r in native if r['type'] == 'task'}
        self.build_phases()
        self.build_overall()
        self.build_linkage()
        self.build_decide()
        self.unchanged()
        return self

    def build_phases(self):
        pointer = P.read_phase_pointer(self.state)
        for path in sorted((self.state / 'phase').glob('*.md')):
            if not re.match(r'\d{3}-', path.stem):
                continue
            raw_text = path.read_text()
            phase = P.parse_phase(path.stem, raw_text)
            headers = P.adr_header_fields(raw_text)
            source = headers.get('source', '')
            vm = re.search(r'\bv\d+\b', source)
            status = headers.get('status', '')
            if status not in ('active', 'scored', 'draft', 'dropped'):
                raise Refused(f'unknown phase status {path}: {status}')
            if status == 'active' and pointer != path.stem:
                raise Refused(f'active phase/pointer disagreement: {path.stem} / {pointer}')
            key = 'phase:' + path.stem
            self.add(key, 'phase', {'headers': headers}, path.stem, path.stem, '', 'phase_' + status,
                     str(path.relative_to(self.state)), {'phase_slug': path.stem, 'started_on': headers.get('started', ''),
                        'source_version': vm.group() if vm else '', 'approval_ref': 'historical source: ' + str(path.relative_to(self.state)),
                        'close_evidence': 'historical scored header' if status == 'scored' else '',
                        'retro_ref': str(path.relative_to(self.state)) if status == 'scored' else ''})
            self.phases[path.stem] = dict(key=key, version=vm.group() if vm else '')
        if pointer and pointer not in self.phases:
            raise Refused(f'phase pointer has no document: {pointer}')

    def build_overall(self):
        rows = self.read('okr.jsonl', P.load_okr_store)
        raw_rows = list(rows)
        # Archive is a real source, not a guess from a later identical version.
        for path in sorted((self.state / 'phase' / 'snapshots').glob('okr-v*.md')):
            _, sites = MD.scan_okr(path.read_text())
            archive = []
            for site in sites:
                rec = {'kind': site['kind'], **site['values']}
                if rec['kind'] not in ('objective', 'kr'):
                    continue
                if rec['kind'] == 'objective':
                    ordinal = re.search(r'\d+', rec['heading'])
                    if not ordinal:
                        raise Refused(f'no objective ordinal in {path}')
                    rec['id'] = 'O-' + ordinal.group()
                rec['_attachment'] = str(path.relative_to(self.state))
                archive.append(rec)
            versions = {version(r.get('version')) for r in rows if r.get('kind') in ('objective', 'kr')}
            rows += [r for r in archive if version(r.get('version')) not in versions]
        views, errors = lib.kr_revisions(rows, 'okr.jsonl')
        if errors:
            raise Refused('invalid overall revisions: ' + encoded(errors))
        folded = lib.fold_kr_records(rows, 'okr.jsonl')
        self.version_records = [r for r in raw_rows if r['kind'] == 'version']
        current = max((version(r.get('version')) for r in rows if r.get('kind') == 'objective'), key=lambda s: int(s[1:]) if re.fullmatch(r'v\d+', s) else -1, default='')
        for kind in ('objective', 'kr'):
            for r in folded:
                if r['kind'] != kind:
                    continue
                scope = r.get('version', '')
                if not scope:
                    raise Refused('overall record without version: ' + encoded(r))
                key = f'overall:{scope}:{kind}:{r.get("id", "")}'
                view = views.get(lib.kr_revision_key(r, 'okr.jsonl'), {}) if kind == 'kr' else {}
                retired = view.get('status') == 'withdrawn'
                state = 'goal_retired' if retired else 'goal_active'
                raw = {'record': r, 'revisions': view.get('revisions', []), 'source_records':[x for x in rows if (x.get('kind')=='kr' and x.get('id')==r.get('id') and x.get('version')==r.get('version')) or (x.get('kind')=='kr_revision' and x.get('kr')==r.get('id') and x.get('okr_version')==r.get('version'))]}
                extra = dict(okr_version=scope, goal_level='overall', approval_ref='historical source: ' + r.get('_attachment', 'OKR.md'),
                             reason=view.get('withdrawn_reason', '') if retired else '')
                if kind == 'kr':
                    extra.update(metric_text=r.get('metric', ''), due_text=r.get('deadline', ''), stretch=str(r.get('stretch', '')).lower() in ('yes', 'true', 'stretch'))
                key = self.add(key, kind, raw, r.get('title', r.get('text', '')), r.get('id', ''), scope, state, r.get('_attachment', 'OKR.md'), extra)
                labels = [r.get('id', '')]
                km = re.fullmatch(r'KR-O(\d+)\.(\d+)', r.get('id', ''))
                if kind == 'kr' and km:
                    labels.append(f'O{km[1]}-KR{km[2]}')
                if kind == 'objective':
                    labels += [r.get('id', '').replace('-', '')]
                    self.goal_index.append(dict(key=key, labels=labels, scope=scope))
                else:
                    self.goal_index.append(dict(key=key, labels=labels, scope=scope))
                    obj = r.get('objective_id')
                    if not obj:
                        matches = [o for o in folded if o['kind'] == 'objective' and o.get('version') == scope and o.get('heading') == r.get('objective')]
                        if len(matches) != 1:
                            raise Refused('ambiguous overall objective for ' + key)
                        obj = matches[0]['id']
                    self.edge('retired_from' if retired else 'parent', key, self.resolve(obj, scope, context=key))
                if version(scope) != current:
                    self.warnings.append(key + ': historical version retained, not automatically retired')
        # Commitments are real goal promises; no new item type is needed.
        for n, r in enumerate(raw_rows):
            if r['kind'] == 'commitment':
                self.add('commitment:' + str(r.get('id', n)), 'objective', r, r.get('promise', r.get('commitment', 'Commitment')), r.get('id', ''), 'commitments', 'goal_active', 'OKR.md', {'goal_level': 'commitment', 'due_text': str(r.get('due', '')), 'approval_ref': 'historical commitment source'})
            elif r['kind'] not in ('objective', 'kr', 'version', 'kr_revision'):
                raise Refused('unsupported OKR kind: ' + encoded(r))
        for record in self.version_records:
            owners = [r for r in self.records.values() if r.type=='objective' and r.fields.get('goal_level')=='overall' and version(r.fields.get('okr_version'))==version(record.get('version'))]
            if not owners:
                raise Refused('version history without scoped objective: '+encoded(record))
            owners[0].fields['version_record']=encoded(record)

    def build_linkage(self):
        rows = self.read('linkage.jsonl', P.load_linkage_store)
        views, errors = lib.kr_revisions(rows, 'linkage.jsonl')
        if errors:
            raise Refused('invalid phase revisions: ' + encoded(errors))
        folded = lib.fold_kr_records(rows, 'linkage.jsonl')
        for kind in ('objective', 'kr'):
            for r in folded:
                if r['kind'] != kind:
                    continue
                phase = r.get('phase', '')
                if phase not in self.phases:
                    raise Refused('linkage phase missing: ' + encoded(r))
                scope = 'phase:' + phase
                key = f'{scope}:{kind}:{r["id"]}'
                view = views.get(lib.kr_revision_key(r, 'linkage.jsonl'), {}) if kind == 'kr' else {}
                retired = view.get('status') == 'withdrawn'
                extra = dict(goal_level='phase', approval_ref='historical source: linkage.jsonl', reason=view.get('withdrawn_reason', '') if retired else '')
                if kind == 'kr':
                    extra.update(metric_text=r.get('metric', ''), due_text=r.get('due', ''), stretch=bool(r.get('stretch', False)))
                self.add(key, kind, {'record': r, 'revisions': view.get('revisions', []), 'source_records':[x for x in rows if (x.get('kind') in ('objective','kr') and x.get('kind')==kind and x.get('id')==r['id'] and x.get('phase')==phase) or (x.get('kind')=='kr_revision' and x.get('kr')==r['id'])]}, r.get('title', ''), r['id'], scope, 'goal_retired' if retired else 'goal_active', 'phase/' + phase + '.md', extra)
                self.goal_index.append(dict(key=key, labels=[r['id']], scope=scope))
                self.edge('in_phase', key, self.phases[phase]['key'])
                if kind == 'objective':
                    self.edge('parent', key, self.phases[phase]['key'])
                else:
                    self.edge('retired_from' if retired else 'parent', key, self.resolve(r['objective'], scope, context=key))
                    if meaningful(r.get('linked')):
                        self.edge('aligned_to', key, self.resolve(r['linked'], phase=phase, context=key))
                    if any(r.get(k) is not None for k in ('target', 'current')):
                        # Legacy scalar assertions have no typed direction/baseline.
                        # Preserve bytes but never synthesize a measured current.
                        self.warnings.append(key + ': scalar target/current retained as legacy facts; no direction or measurement inferred')
        # Typed task references avoid touching pre-existing task seqs/identities.
        for r in rows:
            kind = r['kind']
            if kind == 'edge':
                ver = r.get('okr_version', '') or self.edge_version(r)
                target = self.resolve(r['kr'], ver, context=encoded(r))
                self.require_task(r['task'])
                self.work_refs.setdefault(target, set()).add(r['task'])
            elif kind in ('project', 'unlinked', 'agent'):
                phase = r.get('phase', '')
                if phase not in self.phases:
                    raise Refused('registry record without known phase: ' + encoded(r))
                f = {'project':'project_registry', 'unlinked':'unlinked_tasks', 'agent':'agent_assignments'}[kind]
                self.records[self.phases[phase]['key']].fields.setdefault(f, []).append(encoded(r))
                if kind == 'project' and meaningful(r.get('kr')):
                    self.resolve(r['kr'], context=encoded(r))
            elif kind not in ('objective', 'kr', 'check', 'measurement', 'kr_revision'):
                raise Refused('unsupported linkage kind: ' + encoded(r))
        for k, refs in self.work_refs.items():
            self.records[k].fields['work_items'] = sorted(refs)
        declared = lib.kr_checks(rows)
        for (kr, ver), checks in declared.items():
            owner = self.resolve(kr, ver, context='check owner')
            for entry in checks:
                c, measurement = entry['check'], entry['measurement']
                direction = {'increase':'up','at_least':'up','decrease':'down','at_most':'down','done':'up'}.get(c.get('direction'))
                if not direction:
                    raise Refused('unknown check direction: ' + encoded(c))
                target = 1 if c['direction'] == 'done' else c.get('target')
                baseline = c.get('baseline') if c['direction'] in ('increase','decrease') else None
                raw = {'declarations':[r for r in rows if r['kind']=='check' and (r.get('kr'),r.get('okr_version',''),r.get('id'))==(kr,ver,c['id'])],
                       'measurements':[r for r in rows if r['kind']=='measurement' and (r.get('kr'),r.get('okr_version',''),r.get('check'))==(kr,ver,c['id'])]}
                extra = dict(check_metric={'target':target,'direction':direction,'baseline':baseline,'current':measurement['value'] if measurement else None},
                             measured_at=measurement.get('asserted_at','') if measurement else '', evidence_ref=measurement.get('evidence','') if measurement else '',
                             command_text=c.get('command',''), measurement_origin='legacy assertion' if measurement else 'unmeasured')
                key = 'check:' + owner + ':' + c['id']
                self.add(key, 'check', raw, c.get('label',''), c['id'], owner, 'check_declared', 'linkage.jsonl', extra)
                self.edge('parent', key, owner)
                if measurement and meaningful(measurement.get('evidence')):
                    ref = measurement['evidence']
                    att = {'ref':ref}
                    if (self.state/ref).is_file():
                        att['hash']='sha256:'+digest((self.state/ref).read_bytes())
                    self.records[key].attachments.append(att)
        for r in rows:
            if r['kind'] == 'measurement' and not any(c['check']['id'] == r['check'] for c in declared.get((r['kr'],r.get('okr_version','')), [])):
                raise Refused('orphan measurement: ' + encoded(r))

    def edge_version(self, edge):
        """Only explicit typed task→design metadata can disambiguate a version."""
        if edge['kr'].startswith('P'):
            return ''
        tasks = P.load_task_store(self.state) or []
        refs = next((r.get('design_refs', []) for r in tasks if r['id'] == edge['task']), [])
        versions = set()
        for doc in P.walk_design(self.state):
            if doc.id not in refs:
                continue
            vm = re.search(r'\bv\d+\b', doc.linked_okr)
            labels = re.findall(r'O\d+-KR\d+|KR-O\d+\.\d+', doc.linked_okr)
            if vm and edge['kr'] in labels:
                versions.add(vm.group())
        if len(versions) == 1:
            self.warnings.append('Version resolved by declared task design_refs and design Linked OKR: ' + edge['task'])
            return versions.pop()
        return ''

    def require_task(self, item):
        if item not in self.native_tasks:
            raise Refused('legacy task reference not in copied native store: ' + item)

    def build_decide(self):
        docs = P.walk_design(self.state)
        docs.sort(key=lambda x: x.id)
        for doc in docs:
            text = (self.state / doc.rel).read_text()
            headers = P.adr_header_fields(text)
            raw_status = doc.status_raw.strip().strip('*` ').lower()
            match = re.match(r'^(?:design\s+)?(in_review|in review|review|draft|locked|superseded|dropped|abandoned)(?=$|[\s(（:：—–·])', raw_status)
            if not match:
                raise Refused('design without a recognized declared status: ' + doc.rel)
            status = {'in_review': 'review', 'in review': 'review',
                      'abandoned': 'dropped'}.get(match[1], match[1])
            key = 'design:' + doc.id
            self.add(key, 'design', headers, doc.title, doc.id, '', 'design_' + status, doc.rel,
                     dict(decided_on=doc.date, locked_on=doc.locked, linked_okr_text=doc.linked_okr,
                          author_text=headers.get('author',''), implementation_owner=headers.get('implementation owner',''),
                          approval_ref='historical source: ' + doc.rel), expected_id=doc.id)
        for adr in P.read_adr_records(self.state):
            key = 'adr:' + adr['id']
            headers = P.adr_header_fields((self.state/adr['path']).read_text())
            if not meaningful(headers.get('status')):
                raise Refused('ADR without declared status: '+adr['path'])
            self.add(key, 'adr', {**adr,'headers':headers}, adr['title'], adr['id'], '', 'adr_' + adr['status'], adr['path'],
                     dict(decided_on=adr['date'], decision_type=adr['type'], deciders_text=adr['deciders'], sunset_text=adr['sunset'],
                          approval_ref='historical source: ' + adr['path']), expected_id=adr['id'])
        # File ceilings must be attainable with real records and current primitives.
        for typ, prefix in [('design','DESIGN'), ('adr','ADR')]:
            ids = [r.expected_id for r in self.records.values() if r.type == typ]
            if ids != [f'{prefix}-{n:03d}' for n in range(1,len(ids)+1)]:
                self.requirements.append(f'{prefix}: sparse filenames need approved prefix-floor primitive; see tools/TASK-492-kernel-proposal.md')
        for doc in docs:
            key = 'design:' + doc.id
            linked = doc.linked_okr
            vm = re.search(r'\bv\d+\b', linked)
            phase_ids = re.findall(r'P\d{3}-O\d+-KR\d+', linked)
            phase = next((p for p in self.phases if any(k.startswith('P'+p[:3]+'-') for k in phase_ids)), '')
            labels = re.findall(r'P\d{3}-O\d+-KR\d+|O\d+-KR\d+|KR-O\d+\.\d+', linked)
            for match in re.finditer(r'(O\d+)-KR(\d+)[–—](O\d+)-KR(\d+)',linked):
                if match[1]!=match[3] or not 0<=int(match[4])-int(match[2])<=100:
                    raise Refused('unsupported goal range: '+linked)
                labels += [f'{match[1]}-KR{n}' for n in range(int(match[2]),int(match[4])+1)]
            for label in dict.fromkeys(labels):
                self.edge('aligned_to', key, self.resolve(label, vm.group() if vm and not label.startswith('P') else '', phase, key))
        for r in list(self.records.values()):
            if r.type not in ('design','adr'):
                continue
            raw = json.loads(r.fields['legacy_record'])
            for name in ('supersedes','superseded_by'):
                label = raw.get(name,'')
                if meaningful(label):
                    labels = re.findall(r'(?:DESIGN|ADR)-\d+', label)
                    if not labels:
                        raise Refused('unparsed successor metadata: ' + r.key)
                    for ident in labels:
                        target = ('design:' if ident.startswith('DESIGN') else 'adr:') + ident
                        kind = 'supersedes' if re.fullmatch(r'(?:DESIGN|ADR)-\d+',label.strip()) else 'amends'
                        self.edge(kind, r.key if name=='supersedes' else target, target if name=='supersedes' else r.key)
        tasks = P.load_task_store(self.state)
        if tasks is None and (self.state/'tasks.jsonl').exists():
            raise Refused('unreadable legacy task metadata')
        refs = {}
        for task in tasks or []:
            for label in task.get('design_refs', []) or []:
                key = ('adr:' if label.startswith('ADR') else 'design:') + label
                if key not in self.records:
                    raise Refused('dangling task design_refs: ' + label)
                self.require_task(task['id'])
                refs.setdefault(key,set()).add(task['id'])
        for key, ids in refs.items():
            self.records[key].fields['implemented_by'] = sorted(ids)

    def document(self):
        return dict(format=1, source=str(self.source), state_root=str(self.state.relative_to(self.source)),
                    source_hashes=self.hashes, counts=dict(self.coverage), warnings=self.warnings,
                    records=[asdict(r) for r in self.records.values()], relations=sorted(self.edges),
                    legacy_records=self.source_records, requirements=self.requirements, prefix_ceilings={p:max([int(r.expected_id.split('-')[1]) for r in self.records.values() if r.type==t],default=0) for t,p in [('design','DESIGN'),('adr','ADR')]})


class Kernel:
    def __init__(self, root, store):
        self.root, self.store = Path(root).resolve(), Path(store).resolve()
        self.commands = []

    def call(self, command, body=None, dry=False):
        argv = [str(HOME/'bin/perry-kernel'), *command.split(), '--root',str(self.root),'--store',str(self.store)]
        if body is not None:
            argv += ['--input','-']
        if dry:
            argv += ['--dry-run']
        env = {**os.environ,'PERRY_HOME':str(HOME),'PERRY_KERNEL_TESTING':'1'}
        env.pop('PERRY_STORE',None);env.pop('PERRY_PROJECT',None)
        p = subprocess.run(argv,input=encoded(body) if body is not None else None,text=True,capture_output=True,env=env)
        try:
            result = json.loads(p.stdout)
        except ValueError as exc:
            raise Refused(f'kernel invalid response {command}: {p.stderr}') from exc
        if p.returncode or not result.get('ok') or str(result.get('surface','')).split('.')[0] != '1':
            raise Refused(f'kernel refused {command}: {encoded(result)}')
        if not dry and result['effect']=='written':
            self.commands.append({'command':command,'input':body,'store_seq':result['store_seq']})
        return result

    def items(self):
        items, body = [], {'limit':10000}
        while True:
            d = self.call('query',body)['result']; items += d['items']
            if not d['truncated']:
                return items
            body['after'] = d['next_after']


def transition_path(typ, target):
    return {
        'objective':{'goal_active':['approve'],'goal_retired':['withdraw']},
        'kr':{'goal_active':['approve'],'goal_retired':['withdraw']},
        'phase':{'phase_active':['activate'],'phase_scored':['activate','score'],'phase_dropped':['drop']},
        'design':{'design_review':['review'],'design_locked':['lock'],'design_superseded':['lock','supersede'],'design_dropped':['drop']},
        'adr':{'adr_active':['accept'],'adr_superseded':['accept','supersede'],'adr_expired':['accept','expire'],'adr_archived':['accept','archive']}
    }.get(typ,{}).get(target,[])


def stored_fields(item, template):
    fields = dict(item['fields'])
    for key, decl in template['types'][item['type']]['fields'].items():
        if decl['kind'] == 'metric' and fields.get(key) is not None:
            fields[key] = {k:v for k,v in fields[key].items() if k not in ('met','fraction')}
    return fields


def apply(plan, kernel):
    declaration = kernel.call('describe')['result']
    floor_capable = any(c['name']=='template apply' and 'ceilings' in c.get('input',{}) for c in declaration['commands'])
    if plan.requirements and not floor_capable:
        raise Refused('; '.join(plan.requirements))
    before = kernel.items()
    unmanaged = [i['id'] for i in before if i['type'] in NEW_TYPES and i['fields'].get('source_key') not in plan.records]
    if unmanaged:
        raise Refused('native F items lack a matching migration identity: '+encoded(unmanaged))
    old_events = kernel.call('events',{'limit':100000})['result']
    if old_events['truncated']:
        raise Refused('event history exceeds bounded reconciliation; paginate before activation')
    template = json.loads((HOME/'templates/process/perry.json').read_text())
    kernel.call('template apply',{'actor':ACTOR,'template':template})
    existing = {i['fields'].get('source_key'):i for i in kernel.items() if i['type'] in NEW_TYPES and i['fields'].get('source_key')}
    if len(existing) != sum(i['type'] in NEW_TYPES and bool(i['fields'].get('source_key')) for i in kernel.items()):
        raise Refused('duplicate native source_key')
    mapping = {}
    for r in plan.records.values():
        item = existing.get(r.key)
        if item:
            if item['type'] != r.type or stored_fields(item, template) != {k:r.fields.get(k) for k in template['types'][r.type]['fields']}:
                raise Refused('native item changed since migration: ' + r.key)
            if r.expected_id and item['id'] != r.expected_id:
                raise Refused('legacy/native filename identity conflict: ' + r.key)
        else:
            body = {'actor':ACTOR,'type':r.type,'fields':r.fields,'attachments':r.attachments,'note':'Migrate factual source '+r.key}
            preview = kernel.call('item create',body,dry=True)['result']['item']
            if r.expected_id and preview['id'] != r.expected_id:
                prefix, number = r.expected_id.rsplit('-',1)
                actual_prefix, actual_number = preview['id'].rsplit('-',1)
                if floor_capable and actual_prefix==prefix and int(actual_number)<int(number):
                    kernel.call('template apply',{'actor':ACTOR,'template':template,'ceilings':{prefix:int(number)-1},'note':'Reserve actually issued legacy filename floor before '+r.expected_id})
                    preview = kernel.call('item create',body,dry=True)['result']['item']
                if preview['id'] != r.expected_id:
                    raise Refused('prefix floor/native identity conflict: '+r.key+'; requires approved generic primitive')
            item = kernel.call('item create',body)['result']['item']
        mapping[r.key] = item['id']
        path = transition_path(r.type,r.state)
        for move in path:
            if item['state'] == r.state:
                break
            decl = template['types'][r.type]['transitions'][move]
            if item['state'] not in decl['from']:
                continue
            body = dict(actor=ACTOR,id=item['id'],transition=move,expect={item['id']:item['seq']},set={})
            if move in ('withdraw','drop','supersede','archive','expire') and not item['fields'].get('reason'):
                body['set']['reason']='Historical source metadata: '+r.fields['legacy_id']
            item = kernel.call('item move',body)['result']['item']
        if item['state'] != r.state:
            raise Refused('unreconciled native state: ' + r.key)
        actual_att = {(a['ref'],a.get('hash')) for a in item['attachments']}
        if not {(a['ref'],a.get('hash')) for a in r.attachments} <= actual_att:
            raise Refused('changed/missing native attachment: ' + r.key)
    actual = {i['id']:i for i in kernel.items()}
    for kind,src,dst in sorted(plan.edges):
        sid,tid = mapping[src],mapping[dst]
        if not any(e['kind']==kind and e['from']==sid and e['to']==tid for e in actual[sid]['relations']):
            kernel.call('rel add',dict(actor=ACTOR,kind=kind,**{'from':sid,'to':tid},expect={sid:actual[sid]['seq'],tid:actual[tid]['seq']}))
            actual[sid] = kernel.call('item get',{'id':sid})['result']['item']
            actual[tid] = kernel.call('item get',{'id':tid})['result']['item']
    after = {i['id']:i for i in kernel.items()}
    protected = [i for i in before if i['type'] not in NEW_TYPES]
    if any(after[i['id']] != i for i in protected):
        raise Refused('pre-existing work item changed')
    new_events = kernel.call('events',{'limit':100000})['result']
    if new_events['events'][:len(old_events['events'])] != old_events['events']:
        raise Refused('pre-existing events changed')
    plan.unchanged()
    kernel.call('export')
    return dict(mapping=mapping, protected_items=len(protected), protected_events=len(old_events['events']),
                counts=dict(Counter(i['type'] for i in after.values())), store_seq=kernel.call('query',{'limit':0})['store_seq'])


def save_commands(kernel, work):
    if not kernel.commands:
        return None
    n=1
    while (work/f'commands-{n}.json').exists():
        n+=1
    path=work/f'commands-{n}.json'
    path.write_text(encoded(kernel.commands)+'\n')
    return str(path)


def main(argv=None):
    p=argparse.ArgumentParser(description=__doc__)
    p.add_argument('--source',type=Path,required=True,help='read-only legacy project anchor, copied filesystem preferred')
    p.add_argument('--root',type=Path,required=True,help='explicit scratch project anchor')
    p.add_argument('--store',type=Path,required=True,help='explicit copied native scratch store')
    p.add_argument('--work',type=Path,required=True,help='external output directory containing scratch root and store')
    mode=p.add_mutually_exclusive_group()
    mode.add_argument('--apply',action='store_true',help='apply to scratch only; default plan/dry-run never writes store')
    mode.add_argument('--dry-run',action='store_true',help='emit plan and source hashes without any store write')
    args=p.parse_args(argv)
    source,root,store,work=(getattr(args,k).resolve() for k in ('source','root','store','work'))
    if not root.is_relative_to(work) or not store.is_relative_to(work) or source==root or work.is_relative_to(source) or any((a/'.git').exists() for a in [work,*work.parents]):
        raise Refused('root/store must be scratch children of external --work; source is read-only and distinct')
    kernel=Kernel(root,store)
    plan=Plan(source).build(kernel.items())
    work.mkdir(parents=True,exist_ok=True)
    (work/'plan.json').write_text(encoded(plan.document())+'\n')
    result={'effect':'plan','counts':dict(plan.coverage),'warnings':plan.warnings,'requirements':plan.requirements}
    if args.apply:
        try:
            result={'effect':'rehearsed',**apply(plan,kernel)}
        except (Refused,OSError,ValueError,KeyError) as exc:
            result={'effect':'refused','error':str(exc),'commands':save_commands(kernel,work),
                    'partial':bool(kernel.commands),'next_action':'Reconcile native source_key items/events and source hashes before resuming; never repeat guessed creates.'}
            (work/'result.json').write_text(encoded(result)+'\n')
            print(json.dumps(result,ensure_ascii=False,indent=2))
            return 1
        result['commands']=save_commands(kernel,work)
    (work/'result.json').write_text(encoded(result)+'\n')
    print(json.dumps(result,ensure_ascii=False,indent=2))
    return 0


if __name__=='__main__':
    try:
        sys.exit(main())
    except (Refused,OSError,ValueError,KeyError) as exc:
        print(json.dumps({'ok':False,'error':str(exc)},ensure_ascii=False))
        sys.exit(1)

"""Small skill-side primitives; no project-state resolution or kernel imports."""
from datetime import datetime, timezone
from pathlib import Path
import re


def register_stamp() -> str:
    """UTC timestamp retained for architecture evidence: YYYY-MM-DDTHH:MM:SSZ."""
    return datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")


def explicit_directory(value: str) -> Path:
    if not value.strip():
        raise ValueError("an explicit non-empty directory is required")
    path = Path(value).expanduser().resolve()
    if not path.is_dir():
        raise ValueError(f"directory does not exist: {path}")
    return path


def strip_comments(text: str) -> str:
    return re.sub(r"<!--.*?-->", "", text, flags=re.S)


def field(text: str, label: str) -> str:
    match = re.search(rf"^\s*[-*]?\s*\**{re.escape(label)}\**\s*[:：]\s*([^\n]*)$", text, re.M)
    return match.group(1).strip().strip("*` ") if match else ""


def section(text: str, heading: str) -> str:
    match = re.search(rf"^##\s+{re.escape(heading)}\s*\n(.*?)(?=^##\s|\Z)", text, re.M | re.S)
    return match.group(1).strip() if match else ""


def bullets(text: str) -> list[str]:
    return re.findall(r"^\s*[-*]\s+(.+)$", text, re.M)

#!/usr/bin/env python3
"""Read and mechanically validate knowledge cards, with explicit document roots.

Usage: python3 tools/knowledge.py --root PROJECT --state-root DOCUMENTS
No promotion, state mutation, semantic judgement or implicit legacy resolver.
"""
import argparse
from datetime import date
import json
from pathlib import Path
import re
import sys

from host_common import explicit_directory, field, strip_comments
from roles import report as role_report


def source_files(source: str, roots: tuple[Path, ...]) -> list[str]:
    """Resolve local file citations only; IDs and URLs need a separate review."""
    found = []
    for token in re.split(r"[\s,;·|]+", source):
        token = token.strip("*`()[]<>,;")
        if not token or "://" in token:
            continue
        token = re.sub(r":\d+$", "", token)
        for root in roots:
            candidate = (root / token).resolve()
            if candidate.is_relative_to(root) and candidate.is_file():
                found.append(str(candidate))
    return sorted(set(found))


def report(root: Path, state_root: Path, stale_days=90) -> dict:
    root, state_root = root.resolve(), state_root.resolve()
    cards, errors = [], []
    roles = {Path(c["path"]).stem for c in role_report(root)["cards"]}
    for path in sorted((state_root / "knowledge").rglob("*.md")):
        if path.name == "INDEX.md":
            continue
        text = strip_comments(path.read_text(encoding="utf-8"))
        kind = field(text, "Kind")
        if not kind:
            continue  # source digests are not cards
        heading = re.search(r"^#\s+(.+)$", text, re.M)
        claim = re.sub(r"^.*?\s+[—–-]\s+", "", heading.group(1)).strip() if heading else ""
        card = {"path": path.relative_to(state_root).as_posix(), "topic": path.parent.name,
                "slug": path.stem, "kind": kind, "claim": claim,
                **{key: field(text, label) for key, label in (
                    ("source", "Source"), ("owner_role", "Owner role"),
                    ("last_verified", "Last verified"), ("invalidated_by", "Invalidated by"))}}
        card_errors = []
        blank = {"", "—", "–", "-", "TBD", "(none)"}
        for key in ("claim", "source", "invalidated_by", "last_verified"):
            if card[key] in blank or "{{" in card[key]:
                card_errors.append("missing_" + key)
        if kind not in ("knowledge", "source-of-truth"):
            card_errors.append("invalid_kind")
        if roles and card["owner_role"] not in roles:
            card_errors.append("undeclared_owner_role")
        sources = source_files(card["source"], (root, state_root))
        if not sources:
            card_errors.append("source_not_local_file")
        age = None
        try:
            age = (date.today() - date.fromisoformat(card["last_verified"])).days
        except ValueError:
            card_errors.append("invalid_last_verified")
        if age is not None and age < 0:
            card_errors.append("future_last_verified")
        card.update(source_files=sources, stale=age is not None and age > stale_days,
                    errors=sorted(set(card_errors)))
        cards.append(card)
        errors += [{"path": card["path"], "code": code} for code in card["errors"]]
    return {"contract": "perry-knowledge/read/2.0", "semantics": [],
            "project_root": str(root), "state_root": str(state_root), "cards": cards,
            "total": len(cards), "stale": sum(c["stale"] for c in cards), "errors": errors,
            "source_policy": "local-files-only; IDs/URLs require explicit native/source review"}


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--root", required=True)
    parser.add_argument("--state-root", required=True)
    parser.add_argument("--stale-days", type=int, default=90)
    args = parser.parse_args(argv)
    if args.stale_days < 0:
        parser.error("--stale-days must be non-negative")
    try:
        result = report(explicit_directory(args.root), explicit_directory(args.state_root), args.stale_days)
    except (ValueError, OSError) as exc:
        parser.exit(2, str(exc) + "\n")
    print(json.dumps(result, ensure_ascii=True, indent=2))
    return 1 if result["errors"] else 0


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
"""Read-only finite retirement source audit. This never accepts proposals,
activates a project, runs a native command, or establishes consumer migration.
"""
from __future__ import annotations
import argparse
import ast
from collections import Counter
import hashlib
import json
from pathlib import Path
import re
import subprocess
import sys

SHA = re.compile(r'[0-9a-f]{64}\Z')
COMMIT = re.compile(r'[0-9a-f]{40}\Z')
MOVED = {'kernel', 'skill_procedure', 'retained_skill_helper'}
DISPOSITIONS = MOVED | {'proposed_drop', 'dropped'}


def digest(raw):
    return hashlib.sha256(raw).hexdigest()


def git(root, *args):
    result = subprocess.run(['git', '-C', str(root), *args], capture_output=True)
    if result.returncode:
        raise ValueError('cannot read immutable Git input: ' + ' '.join(args))
    return result.stdout


def local(root, name):
    if not isinstance(name, str) or not name or Path(name).is_absolute():
        raise ValueError('expected a nonempty repository-relative path')
    path = (root / name).resolve()
    if not path.is_relative_to(root):
        raise ValueError('path escapes checkout')
    return path


def source_path(value):
    # Inventory source citations are a path, or path:line/section/entrypoint.
    return re.split(r'[:#]', value, maxsplit=1)[0] if isinstance(value, str) else ''


def keys(rows):
    return [(row.get('kind'), row.get('key')) for row in rows]


def wrapper_ast(raw):
    tree = ast.parse(raw)
    if tree.body and isinstance(tree.body[0], ast.Expr) and isinstance(tree.body[0].value, ast.Constant) and isinstance(tree.body[0].value.value, str):
        tree.body.pop(0)
    return ast.dump(tree, include_attributes=False)


def audit(root, manifest='release/retirement/disposition.json'):
    root = Path(root).resolve()
    errors = []

    def error(code, detail):
        errors.append({'code': code, 'detail': str(detail)})

    result = {'version': 1, 'acceptance': 'PROPOSAL', 'errors': errors,
              'consumer_acceptance': 'not assessed',
              'limitations': ['Source inventory, hashes and paths only; no semantic equivalence or safety review approval.',
                             'Consumer declarations are reported, not verified migration or live activation.',
                             'Local unsigned inventory provenance still requires independent review and named user acceptance.']}
    try:
        data = json.loads(local(root, manifest).read_text())
        if type(data.get('version')) is not int or data['version'] != 1 or not COMMIT.fullmatch(str(data.get('base', ''))):
            raise ValueError('manifest version/base invalid')
        base = data['base']
        if data.get('acceptance', 'PROPOSAL') != 'PROPOSAL':
            error('approval_claim', 'manifest acceptance must remain PROPOSAL')
        tree_paths = set(git(root, 'ls-tree', '-rz', '--name-only', base).decode().split('\0')) - {''}
        index_path = local(root, data.get('source_inventory_path'))
        raw = index_path.read_bytes()
        if not SHA.fullmatch(str(data.get('source_inventory_sha256', ''))) or digest(raw) != data['source_inventory_sha256']:
            error('inventory_hash', 'source inventory bytes differ from manifest')
        original = json.loads(raw)
        original_rows, rows = original.get('rows'), data.get('rows')
        if original.get('base') != base or not isinstance(original_rows, list) or not isinstance(rows, list):
            raise ValueError('source inventory/manifest rows or base invalid')
        if any(not isinstance(r, dict) for r in original_rows + rows):
            raise ValueError('inventory rows must be objects')
        original_keys, actual_keys = keys(original_rows), keys(rows)
        if any(not isinstance(k, str) or not k for pair in original_keys + actual_keys for k in pair):
            raise ValueError('row kind/key must be nonempty strings')
        if len(set(original_keys)) != len(original_keys) or len(set(actual_keys)) != len(actual_keys):
            error('duplicate_row', 'kind/key identities must be unique')
        if set(original_keys) != set(actual_keys):
            error('inventory_identity', {'missing': sorted(set(original_keys) - set(actual_keys)),
                                         'extra': sorted(set(actual_keys) - set(original_keys))})
        if type(data.get('inventory_rows')) is not int or data['inventory_rows'] != len(original_rows) or len(rows) != len(original_rows):
            error('inventory_count', 'declared count must match both finite inventories')
        originals = dict(zip(original_keys, original_rows))
        source_hashes = {}
        covered = set()
        for row in rows:
            identity = (row['kind'], row['key'])
            if row.get('acceptance') != 'PROPOSAL':
                error('approval_claim', identity)
            if row.get('disposition') not in DISPOSITIONS:
                error('disposition', identity)
            for field in ('source', 'successor', 'reason'):
                if not isinstance(row.get(field), str) or not row[field].strip():
                    error('row_shape', f'{identity}: missing {field}')
            prior = originals.get(identity)
            if prior and row.get('source') != prior.get('source'):
                error('source_identity', identity)
            if prior and prior.get('row_sha256') is not None and row.get('row_sha256') != prior['row_sha256']:
                error('original_row_identity', identity)
            name = source_path(row.get('source'))
            if name in tree_paths:
                covered.add(name)
                if name not in source_hashes:
                    source_hashes[name] = digest(git(root, 'show', base + ':' + name))
                if row.get('source_sha256') != source_hashes[name]:
                    error('source_hash', identity)
                if prior and prior.get('source_sha256') not in (None, source_hashes[name]):
                    error('original_source_hash', identity)
            elif name:
                error('source_missing_at_base', identity)
            if row.get('disposition') in MOVED:
                paths = row.get('successor_paths')
                if not isinstance(paths, list) or not paths:
                    error('successor_missing', identity)
                else:
                    for path in paths:
                        try:
                            if not local(root, path).exists():
                                error('successor_missing', f'{identity}: {path}')
                        except ValueError as exc:
                            error('successor_path', f'{identity}: {exc}')
        test_path = local(root, 'tests/test-disposition.json')
        test_data = json.loads(test_path.read_text())
        if test_data.get('base') != base or test_data.get('version') != 1:
            error('test_inventory', 'test disposition base/version mismatch')
        for row in test_data.get('rows', []):
            name = row.get('source')
            if name in tree_paths:
                covered.add(name)
                expected = source_hashes.get(name) or digest(git(root, 'show', base + ':' + name))
                if row.get('source_sha256') != expected:
                    error('test_source_hash', name)
            if str(row.get('acceptance', '')).upper() != 'PROPOSAL':
                error('approval_claim', name)
        required = {p for p in tree_paths if p.split('/')[0] in {'bin', 'schema', 'viewer', 'tests'}}
        if required - covered:
            error('file_disposition_missing', sorted(required - covered))
        product = {p for p in tree_paths if p.startswith('kernel/perry_kernel/')}
        current = {str(p.relative_to(root)) for p in (root / 'kernel/perry_kernel').rglob('*')
                   if p.is_file() and '__pycache__' not in p.parts}
        if current != product:
            error('kernel_product_changed', sorted(current ^ product))
        for name in sorted(product & current):
            if (root / name).read_bytes() != git(root, 'show', base + ':' + name):
                error('kernel_product_changed', name)
        entries = sorted(p.name for p in (root / 'bin').iterdir())
        if entries != ['perry']:
            error('bin_surface', entries)
        wrapper = root / 'bin/perry'
        if wrapper.is_file():
            expected = git(root, 'show', base + ':bin/perry-kernel')
            if not wrapper.read_bytes().startswith(b'#!/usr/bin/env python3\n'):
                error('native_wrapper_shebang', 'native wrapper requires its Python shebang')
            if wrapper_ast(wrapper.read_bytes()) != wrapper_ast(expected):
                error('native_wrapper_changed', 'wrapper executable AST differs from immutable native wrapper')
            if not wrapper.stat().st_mode & 0o111:
                error('native_wrapper_mode', 'bin/perry is not executable')
        consumers = data.get('consumers')
        if not isinstance(consumers, list) or any(not isinstance(c, dict) for c in consumers):
            error('consumer_shape', 'consumers must be an explicit list of objects')
            consumers = []
        for consumer in consumers:
            if consumer.get('acceptance') != 'PROPOSAL':
                error('approval_claim', consumer.get('path', 'consumer'))
        if data.get('consumer_path') is not None or data.get('consumer_sha256') is not None:
            consumer_bytes = local(root, data.get('consumer_path')).read_bytes()
            if digest(consumer_bytes) != data.get('consumer_sha256'):
                error('consumer_hash', 'consumer artifact bytes differ from manifest')
            consumer_data = json.loads(consumer_bytes)
            if (consumer_data.get('version') != 1 or consumer_data.get('base') != base or
                    consumer_data.get('consumers') != consumers):
                error('consumer_inventory', 'consumer artifact identity/declarations differ')
        result.update(base=base, inventory_rows=len(rows), source_files_covered=len(covered),
                      consumers=consumers, pending_user_acceptance=True)
    except (OSError, ValueError, KeyError, TypeError, SyntaxError) as exc:
        error('invalid_input', exc)
    result['ok'] = not errors
    result['status'] = 'source_checks_pass' if result['ok'] else 'source_checks_fail'
    return result


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--root', required=True, type=Path)
    parser.add_argument('--manifest', default='release/retirement/disposition.json')
    parser.add_argument('--summary', action='store_true', help='report consumer counts rather than every declaration')
    args = parser.parse_args(argv)
    if not args.root.is_absolute():
        parser.error('--root must be absolute')
    result = audit(args.root, args.manifest)
    if args.summary and 'consumers' in result:
        consumers = result.pop('consumers')
        result['consumer_count'] = len(consumers)
        result['consumer_status_counts'] = dict(Counter(str(c.get('status', 'unknown')) for c in consumers))
    print(json.dumps(result, indent=2, sort_keys=True, ensure_ascii=True))
    return 0 if result['ok'] else 1


if __name__ == '__main__':
    sys.exit(main())

#!/usr/bin/env python3
"""Read role cards and the additive escalation union; no writes or task state.

Usage: python3 tools/roles.py --root /absolute/project
See helper-contracts.md for the versioned output and interpretation limits.
"""
import argparse
import json
from pathlib import Path
import re
import sys

from host_common import bullets, explicit_directory, field, section, strip_comments


def line_fragments(line: str) -> list[str]:
    if "{{" in line:
        return []
    return list(dict.fromkeys(f.strip().lower() for f in re.findall(r"`([^`]+)`", line)
                             if len(f.strip()) > (2 if f.strip().isascii() else 1)))


def escalation(lines: list[str]) -> dict:
    return {"lines": lines,
            "fragments": list(dict.fromkeys(f for line in lines for f in line_fragments(line))),
            "unextractable": [line for line in lines if not line_fragments(line)]}


def parse_card(path: Path, root: Path) -> dict:
    text = strip_comments(path.read_text(encoding="utf-8"))
    heading = re.search(r"^#\s+(.+)$", text, re.M)
    name = heading.group(1).strip() if heading else path.stem
    name = re.sub(r"^Role\s*[·:：-]\s*", "", name)
    loads = section(text, "Loads")
    topics = {}
    for label in ("knowledge", "pack"):
        topics[label] = [t.strip().strip("*`") for line in bullets(loads)
                         if re.match(rf"{label}\s*[:：]", line, re.I)
                         for t in re.split(r"[,，;；]", re.split(r"[:：]", line, 1)[1])
                         if t.strip() and "{{" not in t]
    return {"name": name, "path": path.relative_to(root).as_posix(),
            "accepted_by": field(text, "Accepted by"), "default_rung": field(text, "Default rung"),
            "executors": field(text, "Executors"), "context": section(text, "Context"),
            "may_touch": section(text, "May touch"), "loads": topics,
            "must_escalate": escalation(bullets(section(text, "Must escalate")))}


def report(root: Path) -> dict:
    root = root.resolve()
    cards = [parse_card(p, root) for p in sorted((root / ".perry" / "roles").glob("*.md"))]
    hook_path = root / ".perry" / "hook.md"
    hook_text = strip_comments(hook_path.read_text(encoding="utf-8")) if hook_path.is_file() else ""
    hook_body = "\n".join(section(hook_text, title) for title in
                          ("High-stakes operations", "High-stakes", "高风险操作"))
    hook = escalation(bullets(hook_body))
    fragments = list(dict.fromkeys(hook["fragments"] + [f for c in cards for f in c["must_escalate"]["fragments"]]))
    errors = []
    if hook_text.strip() and not hook_body.strip():
        errors.append({"path": ".perry/hook.md", "code": "high_stakes_section_empty_or_missing"})
    for card in cards:
        for key in ("accepted_by", "default_rung"):
            if not card[key] or "{{" in card[key]:
                errors.append({"path": card["path"], "code": "missing_" + key})
        if card["default_rung"] and not re.fullmatch(r"V[0-6]", card["default_rung"]):
            errors.append({"path": card["path"], "code": "invalid_default_rung"})
        for line in card["must_escalate"]["unextractable"]:
            errors.append({"path": card["path"], "code": "unextractable_escalation", "line": line})
    errors += [{"path": ".perry/hook.md", "code": "unextractable_escalation", "line": line}
               for line in hook["unextractable"]]
    return {"contract": "perry-roles/read/2.0", "semantics": [], "project_root": str(root),
            "declared": len(cards), "cards": cards, "hook": hook,
            "escalation_union": fragments, "errors": errors}


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--root", required=True)
    args = parser.parse_args(argv)
    try:
        result = report(explicit_directory(args.root))
    except (ValueError, OSError) as exc:
        parser.exit(2, str(exc) + "\n")
    print(json.dumps(result, ensure_ascii=True, indent=2))
    return 1 if result["errors"] else 0


if __name__ == "__main__":
    sys.exit(main())

